INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('java-b12', 'java', 'Stream و پردازش تابعی', 56, 17, '[{"k":"p","t":"Stream عملیات‌های تبدیل و فیلتر را روی Collection زنجیره می‌کند؛ با map، filter و collect کد پردازش داده declarative و خوانا می‌شود."},{"k":"h","t":"Stream؛ پردازش declarative داده"},{"k":"p","t":"Stream راهی برای پردازش مجموعه‌ها به سبک declarative است: به‌جای اینکه با حلقه و متغیر موقت بنویسی «چطور» بگردی، زنجیره‌ای از عملیات توصیف می‌کنی — filter برای انتخاب، map برای تبدیل، و collect برای جمع‌آوری نتیجه. کد شبیه توصیف صورت‌مسئله می‌شود و خوانایی‌اش بالا می‌رود. عملیات میانی (filter، map) تنبل‌اند؛ یعنی تا یک عملیات پایانی (مثل collect یا sum) نیاید، هیچ کاری انجام نمی‌شود و بعد همه در یک پاس بهینه اجرا می‌شوند."},{"k":"h","t":"تنبل بودن و عملیات پایانی"},{"k":"p","t":"تنبلیِ Stream یک بهینه‌سازی هوشمند است: چون عملیات میانی اجرا را شروع نمی‌کنند، می‌توان چند عملیات را در یک پیمایش ترکیب کرد و با short-circuit (مثل limit یا findFirst) زود متوقف شد. ولی باید بدانی که Stream فقط با یک عملیات پایانی «مصرف» می‌شود و بعد از آن قابل‌استفاده مجدد نیست. برای اعداد از mapToInt/mapToLong استفاده کن تا از boxing (تبدیل int به Integer) جلوگیری شود و جمع‌زدن‌ها سریع‌تر شوند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["عملیات","نوع","کار"],"rows":[["filter","میانی (تنبل)","انتخاب عناصری که شرط را دارند"],["map","میانی (تنبل)","تبدیل هر عنصر به چیز دیگر"],["collect","پایانی","جمع‌آوری نتیجه در List یا Map"],["sum / count","پایانی","تجمیع روی اعداد"]]},{"k":"warn","title":"دام رایج","t":"Stream را برای همه‌چیز به کار نبر؛ برای حلقه‌های ساده یا وقتی نیاز به کنترل دقیق جریان (مثل break با شرط پیچیده) داری، حلقه معمولی خواناتر و ساده‌تر است. Stream برای تبدیل و فیلترِ زنجیره‌ای داده عالی است، نه جایگزینِ مطلقِ حلقه."},{"k":"tip","title":"نکته منتور","t":"وقتی چندبار به نتیجه یک Stream نیاز داری، آن را با collect به یک List تبدیل کن و از آن استفاده کن؛ چون Stream بعد از مصرف دوباره قابل‌استفاده نیست و هر بار ساختنِ مجددش یعنی اجرای دوباره کل زنجیره."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["filter انتخاب، map تبدیل، collect جمع‌آوری","عملیات میانی تنبل‌اند تا یک عملیات پایانی بیاید","mapToInt از boxing برای اعداد جلوگیری می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"java","title":"Stream.java","code":"int total = orders.stream()\n    .filter(Order::isPaid)\n    .mapToInt(Order::amount)\n    .sum();\nList<String> names = users.stream()\n    .map(User::name)\n    .toList();"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: filter انتخاب، map تبدیل، collect جمع‌آوری بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا عملیات میانی Stream تنبل‌اند؟","opts":["باگ","تا بدون عملیات پایانی کاری نکنند و با آن، همه در یک پاس بهینه اجرا شوند","کندند","ممکن نیست"],"ans":1,"why":"تنبلی اجازه می‌دهد limit و short-circuit کار کنند و چند عملیات در یک پیمایش ترکیب شوند."},{"q":"چرا عملیات میانیِ Stream (مثل filter و map) تنبل هستند؟","opts":["کند هستند","تا بدون عملیات پایانی کاری نکنند؛ سپس همه در یک پاس ترکیب و با short-circuit بهینه اجرا شوند","باگ است","ممکن نیست"],"ans":1,"why":"تنبلی اجازه می‌دهد چند عملیات در یک پیمایش ترکیب شوند و با limit یا findFirst زود متوقف شود؛ اگر هر عملیات جدا اجرا می‌شد، چندین پیمایش لازم بود."},{"q":"mapToInt چه مزیتی نسبت به map برای اعداد دارد؟","opts":["کوتاه‌تر است","از boxing (تبدیل int به Integer) جلوگیری می‌کند و عملیات عددی سریع‌تر می‌شود","امن‌تر است","ترتیب را حفظ می‌کند"],"ans":1,"why":"map خروجی‌اش شیء (Integer) است که برای اعداد اولیه سربار boxing دارد؛ mapToInt مستقیم روی int کار می‌کند و sum و امثال آن بدون boxing انجام می‌شوند."}]'::jsonb),
('cpp-r1', 'cpp', 'اشاره‌گر، مرجع و دو قلمرو حافظه', 60, 1, '[{"k":"p","t":"هیچ مفهومی در سی‌پلاس‌پلاس به اندازه اشاره‌گر هم قدرت می‌دهد و هم قربانی می‌گیرد. اشاره‌گر یعنی متغیری که مقدارش «آدرس» است — دسترسی مستقیم به حافظه، جایی که پایتون و جاوا پشت دیوار امنشان پنهانش کرده‌اند. فهم Stack و Heap و تفاوت اشاره‌گر با مرجع، مرز بین «کسی که C++ کپی می‌کند» و «مهندس سیستم» است."},{"k":"h","t":"دو قلمرو: Stack در برابر Heap"},{"k":"p","t":"هر تابع که صدا زده می‌شود، یک قاب در Stack می‌گیرد: متغیرهای محلی‌اش آنجا ساخته و با برگشتن تابع خودکار نابود می‌شوند — سریع، منظم و بی‌دردسر. Heap قلمروی «تا اطلاع ثانوی» است: با new حافظه می‌گیری و تا خودت delete نکنی (یا صاحبش نابود نشود) زنده می‌ماند — منعطف ولی خطرناک. قاعده: هر چیزی که عمرش از تابع کوتاه‌تر است، در Stack؛ چیزی که باید بعد از برگشتن تابع زنده بماند یا اندازه‌اش در زمان کامپایل معلوم نیست، در Heap. بیشتر فاجعه‌های C++ از شکستن همین قاعده‌اند: برگرداندن اشاره‌گر به متغیر محلی، یا فراموش‌کردن delete."},{"k":"h","t":"اشاره‌گر در برابر مرجع"},{"k":"p","t":"اشاره‌گر (int* p) آدرس نگه می‌دارد: می‌تواند null باشد، می‌تواند جابه‌جا شود و با * مقدارش را می‌خوانی. مرجع (int& r) نامِ مستعار است: از لحظه تولد به یک متغیر وصل است، نه null می‌پذیرد نه جابه‌جا می‌شود. در API، مرجع را ترجیح بده — چون «همیشه معتبر» است و چک null نمی‌خواهد؛ اشاره‌گر فقط وقتی که «شاید هیچ» یا «شاید بعداً چیز دیگر» واقعی باشد. و const int& برای پارامترهای بزرگِ فقط‌خواندنی: نه کپی می‌شود نه تغییر می‌کند — بهترین قرارداد برای رشته‌ها و ظرف‌ها."},{"k":"h","t":"سه باگ کلاسیک حافظه"},{"k":"p","t":"Use-After-Free: اشاره‌گری که بعد از delete هنوز استفاده می‌شود — حافظه‌اش شاید مال کس دیگری شده باشد؛ مادرِ همه باگ‌های امنیتی. Double Free: دو بار delete روی یک آدرس — خرابی Heap. Dangling Pointer: اشاره‌گر به متغیری که عمرش تمام شده (مثل متغیر محلیِ تابعی که برگشته). ابزار مدرن کمک می‌کند: کامپایلر با AddressSanitizer هر سه را تقریباً همان لحظه لو می‌دهد، و Smart Pointer (درس بعد) کلاً delete دستی را حذف می‌کند. ولی حتی با ابزار، باید «مدل ذهنی مالکیت» را داشته باشی: هر بایت حافظه، دقیقاً یک صاحب دارد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"pointers.cpp","code":"#include <iostream>\n#include <string>\n\nint* bad() {\n    int x = 42;          // x در Stack این تابع است\n    return &x;           // ❌ Dangling: با برگشتن تابع، x می‌میرد\n}\n\nstd::string greet(const std::string& name) {  // نه کپی، نه تغییر\n    return \"سلام \" + name;\n}\n\nint main() {\n    int a = 10;\n    int* p = &a;         // p آدرسِ a را دارد\n    int& r = a;          // r نام دیگرِ a است\n    *p = 20;             // از راه اشاره‌گر نوشتیم\n    std::cout << r;      // 20 — r همان a است\n\n    int* h = new int(7); // Heap: تا delete زنده است\n    delete h;            // صاحبش ما بودیم؛ تمام شد\n    // *h;               // ❌ Use-After-Free — کامنت بماند!\n}"},{"k":"list","items":["تابع bad آدرس متغیر محلی‌اش را برمی‌گرداند — با برگشتن تابع، Stack پاک می‌شود و اشاره‌گر به هیچ می‌ماند.","greet با const string& می‌گیرد: برای رشته‌های بزرگ، نه کپی می‌شود (کارایی) نه تغییر می‌کند (امنیت قرارداد).","p و r هر دو به a می‌رسند؛ نوشتن از راه p، از راه r هم دیده می‌شود — چون یک حافظه‌اند.","هر new باید دقیقاً یک delete داشته باشد، از همان صاحب؛ این قانون مالکیت است که درس بعد خودکارش می‌کند."]},{"k":"def","term":"مالکیت حافظه","t":"قانونی که می‌گوید هر تکه حافظه Heap دقیقاً یک صاحب دارد — همان که مسئول delete‌کردنش است. وقتی مالکیت مبهم شود (دو نفر فکر می‌کنند صاحب‌اند یا هیچ‌کس)، باگ حافظه حتمی است. Smart Pointerها این قانون را در سیستم نوع کامپایلر حک می‌کنند: unique_ptr یعنی دقیقاً یک صاحب."},{"k":"table","head":["","اشاره‌گر (int*)","مرجع (int&)"],"rows":[["چیست","متغیری که مقدارش آدرس است","نام مستعار یک متغیر موجود"],["null","می‌تواند باشد","هرگز"],["جابه‌جایی","به چیزهای دیگر هم وصل می‌شود","از تولد ثابت"],["کاربرد API","«شاید هیچ» واقعی","پارامتر همیشه‌معتبر"]]},{"k":"warn","title":"دام رایج","t":"برگرداندن اشاره‌گر یا مرجع به متغیر محلی: کامپایلر شاید ساکت بماند (هشدار را روشن کن!) ولی برنامه در عمل دیر یا زود مقادیر مزخرف برمی‌گرداند — بدتر از کرش، چون «گاهی» درست کار می‌کند. اگر داده باید بعد از تابع زنده بماند، آن را برگردان (کپی/انتقال) یا در Heap با مالکیت روشن بساز."},{"k":"tip","title":"نکته حرفه‌ای","t":"همین امروز AddressSanitizer را فعال کن (فلگ ‎-fsanitize=address) و بگذار برنامه‌ات را اذیت کند — باگی که در توسعه با جیغ لو برود، در Production با سکوت نمی‌نشیند. ده دقیقه تنظیم، صدها ساعت دیباگ."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Stack خودکار و سریع برای عمرهای کوتاه؛ Heap دستی و منعطف برای عمرهای بلند.","مرجع برای APIهای همیشه‌معتبر؛ اشاره‌گر برای «شاید هیچ».","هر بایت Heap یک صاحب دارد؛ Sanitizer نگهبانِ ارزانِ این قانون است."]}]'::jsonb, '[{"q":"چرا برگرداندن اشاره‌گر به متغیر محلی فاجعه است؟","opts":["کند است","چون متغیر محلی با برگشتن تابع از Stack پاک می‌شود و اشاره‌گر به حافظه آزاد اشاره می‌کند","کامپایل نمی‌شود","جا نمی‌شود"],"ans":1,"why":"آن حافظه برای قاب بعدی Stack استفاده می‌شود؛ خواندنش یعنی خواندن داده کس دیگر — باگی که گاهی کار می‌کند و قابل‌اعتمادترین باگ‌ها را می‌سازد."},{"q":"در API، کی اشاره‌گر به مرجع ترجیح دارد؟","opts":["همیشه","وقتی «شاید هیچ» یا تغییرِ هدف واقعی است — مرجع null نمی‌پذیرد و ثابت است","هیچ‌وقت","برای اعداد"],"ans":1,"why":"مرجع یعنی «همیشه معتبر و همین یکی»؛ اگر API واقعاً می‌تواند «نداشته باشد» (مثل find)، اشاره‌گر یا optional راستش را می‌گوید."},{"q":"const string& در پارامتر چه فایده‌ای دارد؟","opts":["زیبایی","نه کپی می‌شود (کارایی برای داده بزرگ) نه تغییر می‌کند (قرارداد شفاف)","اجباری است","سرعت کامپایل"],"ans":1,"why":"کپی‌کردن رشته‌های بزرگ برای هر فراخوانی، هزینه واقعی است؛ مرجعِ ثابت، کاراییِ اشاره‌گر را با امنیتِ «دست نمی‌زنم» ترکیب می‌کند."}]'::jsonb),
('cpp-r2', 'cpp', 'RAII و Smart Pointer: بازنشستگیِ delete', 60, 2, '[{"k":"p","t":"بزرگ‌ترین ایده سی‌پلاس‌پلاس که بقیه زبان‌ها دزدیدندش: وصل‌کردن عمر منابع به عمر اشیاء. RAII می‌گوید منبع را داخل کلاسی بگذار که سازنده‌اش بگیرد و مخربش آزاد کند — و چون C++ مخرب را «تضمینی» صدا می‌زند (حتی وسط استثنا)، منبع هیچ‌وقت گم نمی‌شود. Smart Pointerها همین ایده را برای خودِ حافظه اعمال کرده‌اند: delete دستی، بازنشسته شده است."},{"k":"h","t":"RAII: قانون طلایی C++"},{"k":"p","t":"فایل، قفل، اتصال دیتابیس، socket — همه منابعی‌اند که باید آزاد شوند، و آزادکردن دستی‌شان در ده مسیر خروجی تابع، غیرممکن است درست انجام شود. RAII الگو را برعکس می‌کند: منبع را در سازنده بگیر، در مخرب رها کن؛ متغیرش را محلی بساز و تمام — وقتی از Scope خارج شد، مخرب خودکار صدا زده می‌شود، حتی اگر استثنا همه‌چیز را به‌هم بریزد. lock_guard (قفل)، fstream (فایل) و unique_ptr (حافظه) همه RAII‌اند. در C++ مدرن، هیچ تابعی نباید delete یا unlock دستی داشته باشد — اگر دارد، RAII‌اش ناقص است."},{"k":"h","t":"unique_ptr: مالکیت انحصاری"},{"k":"p","t":"unique_ptr<T> یعنی «من تنها صاحب این حافظه‌ام»: کپی نمی‌شود (کامپایلر نمی‌گذارد)، فقط منتقل می‌شود (std::move). وقتی unique_ptr از Scope خارج شود، delete خودش زده می‌شود. این «ممنوعیت کپی» باگ نیست، قرارداد است: مالکیت دقیقاً یک نفر است و کامپایلر این قانون را قبل از اجرا ثابت می‌کند. همیشه با make_unique بساز — استثنا‌امن است و new دستی ندارد. اگر جایی احساس کردی به کپی نیاز داری، اول بپرس: آیا واقعاً دو صاحب لازم است، یا فقط می‌خواهم ببینمش؟ برای دیدن، خام‌اش (get()) یا مرجع کافی است."},{"k":"h","t":"shared_ptr و قیمتش"},{"k":"p","t":"وقتی مالکیت واقعاً اشتراکی است (مثلاً یک Texture بین چند صحنه)، shared_ptr با شمارنده مرجع: آخرین کسی که می‌رود، چراغ را خاموش می‌کند. ولی رایگان نیست: شمارنده اتمیک، سربار دارد و چرخه‌های مرجع (دو shared_ptr که به هم اشاره می‌کنند) هرگز صفر نمی‌شوند و نشت می‌کنند — درمانش weak_ptr است. قاعده صنعت: default را unique_ptr بگذار؛ فقط وقتی طراحی واقعاً مالکیت اشتراکی می‌خواهد، shared_ptr بیاور — و چرخه‌ها را با weak بشکن."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"raii.cpp","code":"#include <memory>\n#include <mutex>\n#include <fstream>\n\nclass DbConnection {              // RAII برای اتصال دیتابیس\npublic:\n    DbConnection()  { open(); }   // سازنده: گرفتن منبع\n    ~DbConnection() { close(); }  // مخرب: آزادسازی تضمینی\n    DbConnection(const DbConnection&) = delete;  // کپی ممنوع\n};\n\nvoid process() {\n    DbConnection db;                       // گرفتم\n    auto user = std::make_unique<User>(42); // مالکیت انحصاری\n    std::lock_guard<std::mutex> lock(mtx);  // قفل تا پایان Scope\n    std::ifstream file(\"data.txt\");        // فایل تا پایان Scope\n    if (user->isBad()) throw std::runtime_error(\"x\");\n    // حتی با استثنا: file، قفل و db همه آزاد می‌شوند — خودکار\n}"},{"k":"list","items":["چهار منبع (دیتابیس، حافظه، قفل، فایل) — صفر آزادسازی دستی؛ همه به Scope گره خورده‌اند.","حتی مسیر استثنا امن است: stack unwinding مخرب‌ها را یکی‌یکی صدا می‌زند.","کپی DbConnection حذف شده: اتصال یک صاحب دارد؛ اگر لازم شد، منتقلش کن (move).","lock_guard کوتاه‌ترین شعر RAII است: قفل در سازنده، آزادسازی در مخرب — بن‌بستِ فراموشی، غیرممکن."]},{"k":"def","term":"قانون پنج","t":"در C++11 به بعد: اگر کلاسی یکی از این پنج را دستی نوشت — مخرب، کپی‌سازنده، انتسابِ کپی، move‌سازنده، انتسابِ move — احتمالاً بقیه را هم لازم دارد (یا باید صریحاً حذف کند). نشانه‌اش این است: کلاسِ مدیریت‌کننده منبع که فقط مخرب دارد، با اولین کپی، Double Free می‌سازد. درمان مدرن: عضوها را Smart کن تا قانون پنج، خودکار شود."},{"k":"table","head":["","new/delete دستی","unique_ptr","shared_ptr"],"rows":[["مالکیت","در قرارداد نانوشته","دقیقاً یکی (کامپایلر ثابت می‌کند)","اشتراکی با شمارنده"],["نشت","با یک فراموشی","غیرممکن","ممکن با چرخه مرجع"],["هزینه","فکری!","صفر","شمارنده اتمیک"]]},{"k":"warn","title":"دام رایج","t":"چرخه مرجع با shared_ptr: والد و فرزند که هر دو shared_ptr به هم دارند، شمارنده‌شان هیچ‌وقت صفر نمی‌شود و هر دو برای همیشه زنده می‌مانند. هر جا رابطه «مالک و دیده‌شونده» بود (والد→فرزند مالکیت، فرزند→والد فقط نگاه)، سمت نگاه را weak_ptr بگذار."},{"k":"tip","title":"نکته حرفه‌ای","t":"ریفکتور تدریجی کد قدیمی: هر بار که تابعی با new/‌delete را لمس می‌کنی، new را به make_unique و delete را به حذف تبدیل کن. بعد از چند ماه، کدی که «نمی‌تواند نشت کند» داری — بدون یک روز توقف پروژه."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["RAII: گرفتن منبع در سازنده، آزادسازی تضمینی در مخرب — حتی وسط استثنا.","unique_ptr پیش‌فرض است؛ shared_ptr فقط برای مالکیت واقعاً اشتراکی.","delete دستی در C++ مدرن بوی کهنگی می‌دهد؛ کامپایلر، مالکیت را ثابت می‌کند."]}]'::jsonb, '[{"q":"چرا RAII حتی وسط استثنا هم منبع را آزاد می‌کند؟","opts":["catch می‌گیرد","چون Stack unwinding هنگام خروج از Scope، مخرب‌های اشیاء محلی را تضمینی صدا می‌زند","کامپایلر حذفش می‌کند","GC دارد"],"ans":1,"why":"C++ برخلاف جاوا و پایتون، مخرب اشیاء محلی را در هر خروجی از Scope — عادی یا استثنایی — اجرا می‌کند؛ RAII سوار همین تضمین است."},{"q":"چرا unique_ptr کپی نمی‌شود؟","opts":["باگ است","چون مالکیت انحصاری قراردادش است؛ کپی یعنی دو صاحب و delete دوبار — فقط move مجاز است","کند است","ممکن نیست"],"ans":1,"why":"کامپایلر قانون مالکیت را در سیستم نوع حک کرده؛ اگر کپی لازم داری، احتمالاً یا اشتباه فکر می‌کنی یا باید shared_ptr باشد."},{"q":"نشت حافظه با shared_ptr چطور رخ می‌دهد؟","opts":["نمی‌شود","با چرخه مرجع: دو شیء که به هم shared_ptr دارند، شمارنده‌شان هیچ‌وقت صفر نمی‌شود","با delete","با move"],"ans":1,"why":"هر دو منتظر دیگری‌اند که اول برود؛ درمان، weak_ptr برای سمتی است که فقط «نگاه می‌کند» بدون اینکه مالک باشد."}]'::jsonb),
('n-cpp-l1', 'cpp', 'حافظه: Stack، Heap و اشاره‌گرها', 60, 3, '[{"k":"p","t":"هر متغیر یک آدرس دارد و اشاره‌گر، متغیری است که مقدارش آدرس است. درک اینکه چه چیزی روی Stack ساخته می‌شود (خودکار و سریع) و چه چیزی روی Heap (دستی و خطرناک)، مرز بین برنامه‌نویس معمولی و مهندس سیستم است."},{"k":"code","lang":"cpp","title":"memory.cpp","code":"#include <iostream>\nusing namespace std;\n\nvoid byValue(int x) { x = 100; }           // کپی — بی‌اثر روی اصلی\nvoid byRef(int& x) { x = 100; }            // ارجاع — همان متغیر\nvoid byPtr(int* p) { *p = 100; }           // اشاره‌گر — با واسطه آدرس\n\nint main() {\n    int n = 5;\n    byValue(n); cout << n << endl;   // 5\n    byRef(n);   cout << n << endl;   // 100\n    n = 5;\n    byPtr(&n);  cout << n << endl;   // 100\n\n    // Heap: مسئولیتش با توست!\n    int* arr = new int[1000];\n    // ... اگر delete[] فراموش شود => نشت حافظه\n    delete[] arr;\n}"},{"k":"visual","visual":"stackHeap","title":"شبیه‌ساز: حافظه Stack و Heap"},{"k":"def","term":"اشاره‌گر در برابر ارجاع","t":"اشارهگر می‌تواند null باشد و بعداً به چیز دیگری اشاره کند؛ ارجاع باید همان لحظه ساخت به یک متغیر واقعی وصل شود و دیگر جدا نمی‌شود. برای پارامتر خروجی، ارجاع امن‌تر و خواناتر است."},{"k":"warn","title":"اشاره‌گر معلق (Dangling)","t":"اگر به آدرس متغیری اشاره کنی که از Stack خارج شده (مثلاً آدرس متغیر محلی یک تابع برگردانده شود)، برنامه «گاهی» درست کار می‌کند و «گاهی» کرش — بدترین نوع باگ. هیچ اشاره‌گری نباید به عمرِ کوتاه‌تر از خودش گره بخورد."},{"k":"tip","title":"چرا Stack سریع است؟","t":"تخصیص Stack فقط جابه‌جایی یک اشاره‌گر است؛ Heap دنبال بلوک خالی می‌گردد و نیاز به مدیریت دارد. به همین دلیل متغیرهای محلی ارزان‌اند و new هزینه دارد."}]'::jsonb, '[{"q":"تفاوت byRef(int& x) و byValue(int x) چیست؟","opts":["هیچ تفاوتی ندارند","ارجاع با خود متغیر اصلی کار می‌کند؛ مقدار فقط یک کپی می‌گیرد","مقدار سریع‌تر است","ارجاع فقط برای آرایه‌هاست"],"ans":1,"why":"در call-by-value تابع یک کپی دارد و تغییرش به اصلی نمی‌رسد؛ ارجاع نامِ دیگری برای همان متغیر اصلی است."},{"q":"نشت حافظه (Memory Leak) یعنی چه؟","opts":["RAM خراب شده","بلوکی از Heap تخصیص یافته ولی هیچ اشاره‌گری به آن نمانده تا آزادش کند","استفاده از Stack زیاد شده","اشاره‌گر null است"],"ans":1,"why":"وقتی new می‌زنی و delete را گم می‌کنی، آن بلوک تا پایان برنامه اشغال می‌ماند؛ در سرورهای بلندمدت این یعنی مرگ تدریجی."}]'::jsonb),
('n-cpp-l2', 'cpp', 'RAII و Smart Pointerها؛ خداحافظی با delete', 60, 4, '[{"k":"p","t":"RAII یعنی «تملک منبع = شروع عمر یک شی». وقتی منبع را داخل یک کلاس بگذاری، دِستراکتر — که جاوا و پایتون تضمینش نمی‌کنند ولی سی‌پلاس‌پلاس همیشه صدایش می‌زند — آزادسازی را تضمین می‌کند. حتی اگر استثنا پرتاب شود."},{"k":"code","lang":"cpp","title":"raii.cpp","code":"#include <fstream>\n#include <memory>\n#include <vector>\nusing namespace std;\n\n// RAII کلاسیک: فایل با ساخت باز، با تخریب بسته می‌شود\nvoid read_log() {\n    ifstream f(\"app.log\");      // باز شد\n    string line;\n    getline(f, line);\n    // حتی اگر اینجا استثنا پرتاب شود، f بسته می‌شود\n}\n\n// Smart Pointer: مالکیت هوشمند\nstruct Report { string title; };\n\nauto make_report() {\n    auto r = make_unique<Report>();   // مالک: unique_ptr\n    r->title = \"Q1\";\n    return r;                          // بدون کپی منتقل (Move) می‌شود\n}\n\nint main() {\n    vector<unique_ptr<Report>> reports;\n    reports.push_back(make_report());\n    // خروج از scope => همه به‌طور خودکار پاک می‌شوند. delete‌ای در کار نیست!\n}"},{"k":"def","term":"Move Semantics","t":"به‌جای کپی‌کردن محتویات یک شی بزرگ، «مالکیت» منابعش را به شی جدید منتقل می‌کنیم (std::move). نتیجه: بازگشت آبجکت‌های بزرگ از تابع تقریباً رایگان می‌شود — چیزی که در سی‌پلاس‌پلاس قدیم درد بود."},{"k":"warn","title":"new/delete ممنوع در کد مدرن","t":"تقریباً هرگز نباید خام new بزنی. make_unique و make_shared همه سناریوها را پوشش می‌دهند و نشت حافظه را ساختاری غیرممکن می‌کنند. new خام فقط هنگام نوشتن خودِ Smart Pointerها مجاز است."},{"k":"tip","title":"قانون انتخاب","t":"پیش‌فرض: unique_ptr (یک مالک، صفر هزینه سربار). فقط وقتی واقعاً چند مالک لازم داری shared_ptr — و بدان که شمارنده اتمی آن هزینه دارد. circular reference با shared_ptr = نشت؛ از weak_ptr استفاده کن."}]'::jsonb, '[{"q":"unique_ptr چه زمانی حافظه را آزاد می‌کند؟","opts":["وقتی delete صدا زده شود","وقتی از scope خارج شود — خودکار","وقتی گربج‌کالکتور برسد","هرگز"],"ans":1,"why":"unique_ptr یک شی RAII است؛ دِستراکترش در خروج از scope اجرا و منبع آزاد می‌شود. سی‌پلاس‌پلاس GC ندارد، ولی RAII از GC قابل‌پیش‌بینی‌تر است."},{"q":"std::move چه می‌کند؟","opts":["بایت‌ها را جابه‌جا می‌کند","کپی عمیق می‌گیرد","با تبدیل به rvalue اجازه می‌دهد منابع «دزدیده» شوند به‌جای کپی","شی را حذف می‌کند"],"ans":2,"why":"move خودش چیزی جابه‌جا نمی‌کند؛ فقط به کامپایلر می‌گوید «این شی دیگر لازم نیست، می‌توانی محتویاتش را ببری» — سازنده Move بقیه کار را می‌کند."}]'::jsonb),
('n-cpp-l3', 'cpp', 'STL و الگوریتم‌های مدرن', 55, 5, '[{"k":"p","t":"STL سه‌گانه‌ی کانتینر + الگوریتم + ایتراتور است. به‌جای حلقه دستی برای جست‌وجو و مرتب‌سازی، الگوریتم‌های استاندارد را با Lambda ترکیب کن: کوتاه‌تر، درست‌تر، و معمولاً سریع‌تر — چون بهینه‌سازی‌شده‌اند."},{"k":"code","lang":"cpp","title":"stl.cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Student { string name; double gpa; };\n\nint main() {\n    vector<Student> s = {{\"ara\", 17.2}, {\"sara\", 19.1}, {\"kia\", 15.8}};\n\n    // مرتب‌سازی با Lambda — GPA نزولی\n    sort(s.begin(), s.end(), [](const Student& a, const Student& b) {\n        return a.gpa > b.gpa;\n    });\n\n    // اولین دانشجوی ممتاز\n    auto top = find_if(s.begin(), s.end(),\n        [](const Student& x) { return x.gpa >= 19; });\n\n    if (top != s.end()) cout << top->name << endl;   // sara\n\n    // Range-for مدرن\n    for (const auto& st : s) cout << st.name << \" \";\n}"},{"k":"table","head":["کانتینر","دسترسی","جست‌وجو","کاربرد"],"rows":[["vector","ایندکس O(1)","O(n)","پیش‌فرض مطلق؛ کش‌دوست"],["unordered_map","با کلید O(1)","O(1)","جدول کلید-مقدار"],["map","با کلید O(log n)","O(log n)","وقتی ترتیب کلید مهم است"],["list","O(n)","O(n)","فقط درج/حذف وسط زیاد"]]},{"k":"tip","title":"C++20 در یک نگاه","t":"Ranges نوشتن pipeline مثل sort(v) | filter | transform را ممکن کردند، Concepts خطاهای قالب را خواندنی کردند و constexpr محاسبات زمان کامپایل را گسترش داد. پروژه‌های جدید را با استاندارد 20 شروع کن."}]'::jsonb, '[{"q":"چرا vector تقریباً همیشه انتخاب پیش‌فرض است؟","opts":["همه عملیاتش O(1) است","حافظه پیوسته دارد و با کش CPU دوست است","از list کوچک‌تر است","تنها کانتینر STL است"],"ans":1,"why":"پیوستگی حافظه یعنی prefetch و کش بهتر؛ حتی درج انتهای vector معمولاً از هر کانتینر دیگری در عمل سریع‌تر است. اول vector، بعد پروفایل، بعد تغییر."},{"q":"Lambda در الگوریتم‌های STL چه نقشی دارد؟","opts":["جایگزین کلاس‌هاست","رفتار دلخواه (مقایسه، فیلتر) را بدون نوشتن تابع جدا تزریق می‌کند","حافظه آزاد می‌کند","خطا می‌گیرد"],"ans":1,"why":"الگوریتم‌ها اسکلت عمومی‌اند (sort، find_if)؛ Lambda بخش «چطور مقایسه/فیلتر کن» را در همان جا و خوانا مشخص می‌کند."}]'::jsonb),
('cpp-x1', 'cpp', 'Move Semantics و Template — سرعت بدون کپی', 60, 6, '[{"k":"p","t":"سوال بزرگ C++: چطور آبجکت‌های بزرگ (بردار میلیونی) را بین توابع جابه‌جا کنیم بدون کپی؟ جواب C++11 شاهکار است: Move Semantics. وقتی آبجکتی «موقت» است و دیگر کسی لازمش ندارد (مثل مقدار برگشتی تابع)، به‌جای کپی‌کردن داده‌هایش، «داخلی‌هایش را می‌دزدیم»: اشاره‌گر به بافر منتقل می‌شود و منبع خالی می‌ماند. کپی یک بردار میلیونی میلی‌ثانیه‌ها هزینه دارد؛ Move فقط چند اشاره‌گر جابه‌جا می‌کند — تقریباً رایگان. std::move هم خودش چیزی را جابه‌جا نمی‌کند؛ فقط به کامپایلر قول می‌دهد که «این آبجکت را دیگر نمی‌خوانم، می‌توانی بدزدی‌اش»."},{"k":"code","lang":"cpp","title":"move.cpp","code":"#include <vector>\n#include <utility>\n\nstd::vector<int> make_big() {\n    std::vector<int> v(1''000''000, 42);\n    return v;     // بدون Move: کپی میلیون‌ها int!\n}                 // با Move (یا NRVO): صفر کپی\n\nstd::vector<int> a = make_big();          // انتقال، نه کپی\nstd::vector<int> b = std::move(a);        // قول: a دیگر استفاده نمی‌شود\n// a حالا در وضعیت «معتبر ولی نامشخص» است — فقط جایگزینی (assignment) یا نابودی‌اش امن است\n\n// کلاسی که Move را بلد است:\nclass Buffer {\n    int* data_; size_t size_;\npublic:\n    Buffer(Buffer&& o) noexcept           // سازنده انتقال\n        : data_(o.data_), size_(o.size_) {\n        o.data_ = nullptr; o.size_ = 0;   // دزدیدن + خالی‌کردن منبع\n    }\n    Buffer& operator=(Buffer&& o) noexcept {\n        delete[] data_;\n        data_ = o.data_; size_ = o.size_;\n        o.data_ = nullptr; o.size_ = 0;\n        return *this;\n    }\n};"},{"k":"p","t":"Rule of Five تکمیل‌کننده بحث RAII جلسه قبل است: اگر کلاسی یکی از این پنج را لازم داشت — سازنده کپی، عملگر کپی، سازنده انتقال، عملگر انتقال، ویراستار — معمولاً هر پنج را باید بنویسد (یا بهتر: = default و = delete بدهی تا کامپایلر و خواننده دقیقاً بدانند چه قراردادی داری). و بهترین کلاس‌ها اغلب Rule of Zero دارند: منابع را به اعضای هوشمند (unique_ptr، vector) بسپار تا خودت هیچ‌کدام را ننویسی. کپی ممنوعِ منحصربه‌فرد را هم بشناس: unique_ptr copy ندارد، فقط move — مالکیت دقیقاً یک نفر است و کامپایلر این قانون را اجرا می‌کند."},{"k":"code","lang":"cpp","title":"templates.cpp","code":"// Template — یک الگوریتم برای همه تایپ‌ها، بدون هزینه اجرا:\ntemplate <typename T>\nT max_of(T a, T b) { return a > b ? a : b; }\n\nmax_of(3, 7);          // T = int   — در کامپایل ساخته می‌شود\nmax_of(2.5, 1.1);      // T = double\n\n// Template کلاس: Stack برای هر تایپی\ntemplate <typename T>\nclass Stack {\n    std::vector<T> items_;\npublic:\n    void push(T v)  { items_.push_back(std::move(v)); }\n    T pop() {\n        T top = std::move(items_.back());   // انتقال بیرون\n        items_.pop_back();\n        return top;\n    }\n};\nStack<std::string> names;   // فقط stringها — ایمنی تایپ کامل\nnames.push(\"سارا\");\n\n// مفاهیم مدرن (C++20): محدود کردن Template\n// template <typename T> requires std::integral<T>\n// T gcd(T a, T b) { ... }   ← فقط اعداد صحیح مجازند"},{"k":"table","head":["مفهوم","چیست","چرا مهم است"],"rows":[["lvalue","چیزی که نام و آدرس دارد","قابل‌ارجاع و ماندگار"],["rvalue","موقت و رو به مرگ","کاندیدای Move"],["std::move","تبدیل lvalue به rvalue (قول می‌دهم!)","اجازه دزدی منابع"],["noexcept","قولِ بدون استثنا","بدون آن، کانتینرها از Move صرف‌نظر می‌کنند!"]]},{"k":"warn","title":"std::move اشتباه","t":"Move روی چیزی که بعدش دوباره خوانده می‌شود، باگ است — چون منبع خالی شده. مخصوصاً در حلقه‌ها: auto x = std::move(vec[i]) و بعد خواندن vec[i] فاجعه است. و noexcept را روی عملگرهای انتقال فراموش نکن؛ بدونش vector هنگام رشد، به‌جای انتقال، کپی می‌کند و عملاً همه سرعت از دست می‌رود."},{"k":"tip","title":"نکته منتور","t":"Compiler Explorer (godbolt.org) را باز کن و تابعی که vector برمی‌گرداند را با و بدون -O2 ببین: NRVO چطور کپی را حذف می‌کند و Move چه اسمبلی‌ای تولید می‌کند. دیدن صفر بودن فراخوانی‌های کپی، Move Semantics را برای همیشه ملموس می‌کند."}]'::jsonb, '[{"q":"std::move واقعاً چه می‌کند؟","opts":["داده را جابه‌جا می‌کند","فقط یک تبدیل است که به کامپایلر اجازه دزدی منابع می‌دهد — انتقال را سازنده انتقال انجام می‌دهد","حافظه آزاد می‌کند","کپی عمیق می‌سازد"],"ans":1,"why":"std::move فقط static_cast به rvalue reference است؛ کار واقعی را move constructor/assignment با جابه‌جا کردن اشاره‌گرها و خالی‌کردن منبع انجام می‌دهد."},{"q":"چرا noexcept روی move constructor حیاتی است؟","opts":["برای خوانایی است","چون بدون آن، کانتینرها (مثل vector) هنگام رشد از ترس استثنا کپی می‌کنند نه انتقال","کامپایلر اجبار می‌کند","سرعت اسمبلی بیشتر"],"ans":1,"why":"vector فقط وقتی می‌تواند با خیال راحت عناصر را منتقل کند که مطمئن باشد وسط کار استثنا پرت نمی‌شود؛ بدون noexcept به نسخه امن (کپی) برمی‌گردد."}]'::jsonb),
('cpp-b1', 'cpp', 'ساختار برنامه و main', 63, 7, '[{"k":"p","t":"هر برنامه C++ از main شروع می‌شود؛ #include کتابخانه‌ها را می‌آورد و std فضای نام استاندارد است که cout و endl در آن‌اند."},{"k":"h","t":"چرا main و چه اتفاقی هنگام اجرا می‌افتد"},{"k":"p","t":"وقتی برنامه اجرا می‌شود، سیستم‌عامل فایل باینری را بارگذاری و کنترل را به تابع main می‌سپارد؛ هر چه قبل از main نوشته‌ای (سازنده‌های سراسری) قبلش اجرا و هر چه بعد از return main است (مخرب‌های سراسری) بعدش پاک‌سازی می‌شود. مقدار بازگشتی main کد وضعیت فرایند است که ۰ یعنی موفقیت — و همین عدد همان چیزی است که shell در $? می‌گیرد و اسکریپت‌ها برای تصمیم‌گیری می‌خوانند. پس return 0 فقط یک سنت نیست؛ یک قرارداد سیستمی است."},{"k":"h","t":"فضای نام std و هزینه آلودن آن"},{"k":"p","t":"کتابخانه استاندارد صدها نام دارد و همه در std زندگی می‌کنند تا با نام‌های تو تصادف نکنند. نوشتن std::cout کمی طولانی‌تر است ولی دقیقاً مشخص می‌کند از کجا می‌آید. دستور using namespace std همه این نام‌ها را به فضای جهانی می‌ریزد؛ در فایل .cpp کوچک شاید راحت باشد، ولی در هدر یعنی آلوده‌کردن هر فایلی که آن را include می‌کند — و یک روز نامی که خودت ساختی با نامی از std برخورد می‌کند و خطایی می‌گیری که ریشه‌اش کیلومترها دورتر است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"main و کد وضعیت در عمل","code":"#include <iostream>\n#include <cstdlib>\n\nint main(int argc, char* argv[]) {\n    if (argc < 2) {\n        std::cerr << \"استفاده: prog <نام>\\n\";   // خطا به stderr\n        return EXIT_FAILURE;                    // = 1\n    }\n    std::cout << \"سلام \" << argv[1] << \"\\n\";\n    return EXIT_SUCCESS;                        // = 0\n}\n// در shell:\n//   $ ./prog          → پیام خطا، $? برابر 1\n//   $ ./prog سارا     → سلام سارا، $? برابر 0"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","std::cout","using namespace std"],"rows":[["شفافیت","مشخص است از کجا می‌آید","منشأ نام‌ها گم می‌شود"],["تصادف نام","تقریباً غیرممکن","در پروژه بزرگ محتمل"],["جای مجاز","همه‌جا","فقط .cpp کوچک، هرگز هدر"]]},{"k":"warn","title":"دام رایج","t":"include کردن هدری که داخلش using namespace std دارد، در پروژه‌های بزرگ یکی از سخت‌ترین خطاها برای ردیابی است؛ چون خطا جایی ظاهر می‌شود که مشکل نیست. قانون: هدر همیشه با std:: کامل بنویس."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["#include <iostream> برای ورودی/خروجی","std::cout خروجی و std::cin ورودی","using namespace std در فایل کوچک راحت است ولی در بزرگ بد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"main.cpp","code":"#include <iostream>\nint main() {\n    int age;\n    std::cout << \"سن؟ \";\n    std::cin >> age;\n    std::cout << \"سال دیگر: \" << age + 1 << \"\\n\";\n    return 0;\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: #include <iostream> برای ورودی/خروجی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا using namespace std در هدر بد است؟","opts":["کند","چون همه نام‌ها را به هر فایلی که include کند می‌ریزد و تداخل اسم می‌سازد","اجباری نیست","حافظه"],"ans":1,"why":"هدر توسط فایل‌های زیاد include می‌شود؛ آلودن فضای نام جهانی، تداخل غیرقابل‌ردیابی می‌سازد."},{"q":"مقدار return main چه معنایی برای سیستم‌عامل دارد؟","opts":["فقط برای خوانایی","کد وضعیت فرایند است؛ ۰ موفقیت و غیر۰ خطا — shell و اسکریپت‌ها آن را می‌خوانند","حافظه را آزاد می‌کند","سرعت اجرا را تعیین می‌کند"],"ans":1,"why":"این عدد همان قرارداد استاندارد «آیا کار درست انجام شد» است؛ اسکریپت‌ها با if [ $? -ne 0 ] بر اساسش تصمیم می‌گیرند، پس برگرداندن ۰ هنگام خطا یعنی گمراه‌کردن کل زنجیره."},{"q":"چرا std::cerr برای پیام خطا مناسب‌تر از std::cout است؟","opts":["سریع‌تر است","جریان جداگانه‌ای است که با خروجی عادی قاطی نمی‌شود و می‌توان آن را جدا redirect کرد","رنگی چاپ می‌کند","اجباری است"],"ans":1,"why":"وقتی خروجی برنامه به فایل یا pipe می‌رود، خطاها نباید لابه‌لای داده گم شوند؛ stderr جدا می‌ماند تا هم دیده شود و هم بتوان آن را به‌تنهایی لاگ کرد."}]'::jsonb),
('cpp-b2', 'cpp', 'انواع داده و اشاره‌گر', 63, 8, '[{"k":"p","t":"اشاره‌گر متغیری است که آدرس حافظه نگه می‌دارد؛ * برای تعریف و دسترسی و & برای گرفتن آدرس — درک این دو، کلید فهم C++ است."},{"k":"h","t":"اشاره‌گر؛ آدرس به‌عنوان داده"},{"k":"p","t":"اشاره‌گر متغیری است که به‌جای مقدار، «کجا» را نگه می‌دارد. همین یک ایده، کل قدرت C++ است: می‌توانی به داده‌ای که خودت نساختی اشاره کنی، آن را بدون کپی جابه‌جا کنی و ساختارهایی بسازی که به هم زنجیر شده‌اند. ولی دقیقاً همین قدرت، خطرناکش می‌کند: اشاره‌گر نمی‌داند خانه‌ای که به آن اشاره می‌کند هنوز زنده است یا نه — اگر به حافظه‌ای اشاره کنی که آزاد شده، برنامه شاید اجرا شود، شاید کرش کند، شاید بی‌سروصدا داده خراب بدهد."},{"k":"h","t":"دو عملگر و یک قرارداد ذهنی"},{"k":"p","t":"عملگر & آدرس یک متغیر را می‌گیرد و عملگر * در تعریف یعنی «این یک اشاره‌گر است» و در عبارت یعنی «محتوای نقطه‌اشاره». این دوکاره‌بودنِ * گیج‌کننده‌ترین بخش برای شروع است؛ راهش یک قرارداد ذهنی است: در تعریف، * به نوع می‌چسبد (int* یعنی نوع «اشاره‌گر به int») و در عبارت، به مقدار. وقتی این را تفکیک کنی، int* p = &x یعنی «p از نوع اشاره‌گر به int است و آدرس x را دارد» و *p = 20 یعنی «مقدارِ خانه‌ای که p نشانش را دارد را ۲۰ کن» — یعنی x عوض می‌شود، نه p."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"اشاره‌گر؛ تعقیب آدرس","code":"int x = 10;\nint* p = &x;      // p ← آدرسِ x\nint* q = p;       // q هم به همان خانه اشاره می‌کند\n\n*p = 20;          // x شد ۲۰ (از راه p)\nstd::cout << x;   // 20\nstd::cout << *q;  // 20 — q هم همان خانه را می‌بیند\n\np = nullptr;      // p دیگر به جایی اشاره نمی‌کند\n// *p = 5;        // ❌ تعریف‌نشده — کرش یا بدتر"},{"k":"def","term":"اشاره‌گرِ پوچ (nullptr)","t":"اشاره‌گری که به هیچ خانه‌ای اشاره نمی‌کند. قرارداد: هر اشاره‌گری که فعلاً هدف ندارد nullptr باشد و قبل از هر dereference چک شود. nullptr مدرن جایگزین NULL و 0 است چون نوع‌امن است و ابهام با عدد صفر را از بین می‌برد."},{"k":"warn","title":"دام رایج","t":"مخطرترین باگ C++ یعنی use-after-free وقتی رخ می‌دهد که به خانه‌ای اشاره کنی که قبلاً delete شده. هیچ کامپایلری جلوی آن را نمی‌گیرد؛ فقط برنامه‌ریزی دقیق عمر اشاره‌گرها و ترجیح دادن smart pointer به new خام، این خطر را واقعاً حذف می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["int* p یک اشاره‌گر به int است","*p مقدارِ نقطه‌اشاره و &x آدرس x","اشاره‌گر به null باید قبل از dereference چک شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"ptr.cpp","code":"int x = 10;\nint* p = &x;     // p آدرس x را دارد\n*p = 20;         // مقدار x را از راه p عوض کرد\nstd::cout << x;  // 20"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: int* p یک اشاره‌گر به int است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"*p = 20 چه می‌کند؟","opts":["p را ۲۰ می‌کند","مقدارِ خانه‌ای که p به آن اشاره دارد را ۲۰ می‌کند","آدرس را عوض می‌کند","خطا"],"ans":1,"why":"*p یعنی محتوای نقطه‌اشاره؛ پس خانه x (که p آدرسش را دارد) ۲۰ می‌شود."},{"q":"تفاوت int* p و int *p چیست؟","opts":["یکی اشاره‌گر است یکی نه","هیچ — هر دو یک معنا دارند؛ فاصله فقط سلیقه است ولی خوانش int* (نوع = اشاره‌گر به int) توصیه می‌شود","دومی خطاست","بستگی به کامپایلر دارد"],"ans":1,"why":"از نظر زبان هر دو یکسان‌اند؛ ولی نوشتن int* a, b خطرناک است چون b یک int ساده می‌شود نه اشاره‌گر — خوانش «نوع، اشاره‌گر به int» این ابهام را کم می‌کند."},{"q":"چرا nullptr به NULL (یا 0) ترجیح داده می‌شود؟","opts":["جدیدتر است","نوع‌امن است؛ NULL در واقع عدد ۰ است و می‌تواند با سرباری عددی اشتباه گرفته شود، ولی nullptr فقط به اشاره‌گر می‌چسبد","سریع‌تر است","حافظه کمتری دارد"],"ans":1,"why":"اگر دو سرباری f(int) و f(int*) داشته باشی، فراخوانی f(NULL) به نسخه عددی می‌رود که معمولاً قصد تو نیست؛ f(nullptr) بدون ابهام به نسخه اشاره‌گر می‌رود."}]'::jsonb),
('cpp-b3', 'cpp', 'Stack در برابر Heap', 63, 9, '[{"k":"p","t":"Stack برای متغیرهای محلی با تخصیص و آزادسازی خودکار و سریع است؛ Heap برای داده‌ای که عمرش از تابع بیشتر است و با new/delete مدیریت می‌شود."},{"k":"h","t":"دو منطقه حافظه با دو قانون عمر"},{"k":"p","t":"Stack منطقه‌ای است که هر تابع هنگام ورود یک قاب در آن می‌گیرد و هنگام خروج کل قاب — همه متغیرهای محلی‌اش — خودکار آزاد می‌شود. تخصیصش یک حرکتِ اشاره‌گر است، پس برق‌آساست؛ ولی عمرش به عمر تابع گره خورده و اندازه‌اش محدود. Heap منطقه بزرگی است که با new از آن تکه می‌گیری و تا خودت delete نکنی ماندگار است؛ قدرتش در عمر دلخواه است و ضعفش در اینکه «خودت» یعنی مسئولیت کامل — یک فراموشی یعنی نشت و یک اشتباه یعنی خرابی."},{"k":"h","t":"چرا C++ مدرن می‌گوید new خام را فراموش کن"},{"k":"p","t":"قاعده «هر new یک delete» روی کاغز ساده است ولی در کد واقعی پر از مسیر است: return زودهنگام، پرتاب استثنا، چند نقطه خروج — هر کدام می‌توانند delete را جا بیندازند. راه‌حل مدرن این است که مالکیت را به یک شیء بسپاری که مخربش delete می‌کند (همان RAII): unique_ptr وقتی از scope خارج شود خودش حافظه را آزاد می‌کند، حتی اگر استثنا پرتاب شده باشد. پس سؤال درست دیگر «کجا delete بزنم» نیست؛ «چه شیء‌ای مالک این حافظه است» است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"Stack، Heap و مالکیت هوشمند","code":"#include <memory>\n\nvoid f() {\n    int a = 5;                       // stack: با خروج خودکار آزاد\n    int* raw = new int(5);           // heap دستی: خطرناک\n    delete raw;                      // اگر فراموش شود → نشت\n\n    auto smart = std::make_unique<int>(5);  // heap هوشمند\n    // بدون delete — با خروج f خودکار آزاد می‌شود\n    // حتی اگر قبلش return یا استثنا باشد!\n}"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Stack","Heap"],"rows":[["عمر","تا پایان تابع","تا delete (یا پایان مالک)"],["سرعت تخصیص","برق‌آسا","کندتر + سربار مدیریت"],["اندازه","محدود (چند مگابایت)","بسیار بزرگ"],["مدیریت","خودکار","دستی یا با smart pointer"]]},{"k":"tip","title":"نکته منتور","t":"قاعده عملی: داده‌های کوچک و محلی را در stack نگه دار؛ هر وقت عمر داده باید از تابع بیشتر باشد به‌جای new/delete از unique_ptr استفاده کن و shared_ptr را فقط وقتی واقعاً مالکیت اشتراکی داری — نه به‌عنوان راه فرار از تصمیم‌گیری."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["متغیر محلی در stack؛ با خروج تابع خودکار آزاد می‌شود","new در heap؛ تا delete نشود می‌ماند","فراموشی delete یعنی نشت حافظه"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"mem.cpp","code":"void f() {\n    int a = 5;              // stack — خودکار\n    int* b = new int(5);    // heap — دستی\n    delete b;               // باید آزاد شود!\n}   // a خودکار آزاد شد"},{"k":"warn","title":"هشدار","t":"هر new باید دقیقاً یک delete داشته باشد؛ نه کمتر (نشت) و نه بیشتر (خرابی heap)."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: متغیر محلی در stack؛ با خروج تابع خودکار آزاد می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چه چیزی نشت حافظه می‌سازد؟","opts":["new بدون delete","متغیر stack","delete زیاد","include"],"ans":0,"why":"اگر حافظه heap را new کنی و delete نکنی، تا پایان برنامه آزاد نمی‌شود و مصرف بالا می‌رود."},{"q":"چرا آدرس متغیر محلی را نباید از تابع برگرداند؟","opts":["کند است","چون با خروج تابع، قاب stack آن آزاد می‌شود و اشاره‌گر به خانه‌ای مرده اشاره می‌کند","کامپایل نمی‌شود","ممکن نیست"],"ans":1,"why":"متغیر محلی مالِ قاب تابع است؛ وقتی تابع برمی‌گردد آن خانه دیگر متعلق به تو نیست و خواندنش رفتار تعریف‌نشده است — شاید کار کند، شاید نه، که از هر دو بدتر است."},{"q":"unique_ptr چه چیزی را در برابر new خام تضمین می‌کند؟","opts":["سرعت بیشتر","آزادسازی حافظه هنگام پایان عمر مالک — حتی در مسیر استثنا یا return زودهنگام — پس نشت غیرممکن می‌شود","اندازه کمتر","دسترسی سریع‌تر"],"ans":1,"why":"مالکیت به مخرب شیء گره خورده (RAII) و مخرب در هر مسیری اجرا می‌شود؛ پس دیگر هیچ شاخه‌ای از کد نمی‌تواند delete را جا بیندازد."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('cpp-b4', 'cpp', 'مرجع (Reference)', 63, 10, '[{"k":"p","t":"مرجع نام مستعار یک متغیر است؛ برخلاف اشاره‌گر نمی‌تواند null باشد و بعد از اتصال عوض نمی‌شود — برای پاس‌دادن بدون کپی عالی است."},{"k":"h","t":"مرجع؛ نام دوم برای همان متغیر"},{"k":"p","t":"مرجع وقتی ساخته می‌شود به یک متغیر می‌چسبد و تا آخر عمر همان متغیر می‌ماند — نه null می‌شود و نه به چیز دیگری وصل. این یعنی وقتی تابعی مرجع می‌گیرد، داری با «همان» متغیرِ صدازننده کار می‌کنی نه یک کپی؛ پس تغییری که می‌دهی بیرون هم دیده می‌شود. در عمل، مرجع همان کاری را می‌کند که اشاره‌گر می‌کند (دسترسی بدون کپی) ولی با سینتکسِ متغیر معمولی و بدون نیاز به * و بدون خطرِ اشاره‌گرِ جابه‌جاشده."},{"k":"h","t":"const&؛ قراردادِ «می‌خوانم ولی عوض نمی‌کنم»"},{"k":"p","t":"پاس‌دادن شیء بزرگ با مرجع از کپی پرهزینه جلوگیری می‌کند؛ ولی مرجعِ ساده به طرف مقابل اجازه تغییر هم می‌دهد. اگر فقط می‌خوانی، const& بنویس تا هم کپی نشود و هم کامپایلر جلوی هر تغییر ناخواسته را بگیرد. این امضا در C++ یک پیام روشن است: «این تابع ورودی‌اش را دست نمی‌زند» — و خواننده کد بدون خواندن بدنه می‌تواند به آن اعتماد کند. تقریباً هر تابعی که شیء بزرگی را فقط می‌خواند باید const& بگیرد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"cpp","title":"مرجع و const&","code":"void inc(int& n) { n++; }        // مرجع: همان متغیرِ صدازننده\nvoid print(const std::string& s) {  // می‌خوانم، عوض نمی‌کنم\n    // s += \"!\";                  // ❌ کامپایل نمی‌شود — const\n    std::cout << s << \"\\n\";\n}\n\nint x = 1;\ninc(x);                // x شد 2 (بدون برگرداندن مقدار)\nstd::string big(10000, ''a'');\nprint(big);            // بدون کپیِ ۱۰ هزار کاراکتری"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","مرجع (int&)","اشاره‌گر (int*)"],"rows":[["null","هرگز","می‌تواند"],["جابه‌جایی","بعد از اتصال، ثابت","به چیزهای دیگر هم وصل می‌شود"],["سینتکس","مثل متغیر معمولی","نیاز به * و &"],["کاربرد API","پارامتر همیشه‌معتبر","«شاید هیچ» واقعی"]]},{"k":"tip","title":"نکته منتور","t":"قاعده سرانگشتی: اگر مقدار ممکن است «هیچ» باشد اشاره‌گر (یا std::optional)، اگر همیشه معتبر است مرجع؛ و اگر شیء بزرگی را فقط می‌خوانی همیشه const&. این سه انتخاب، امضای توابع C++ را خوانا و بی‌اشتباه می‌کنند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["int& r = x یک مرجع به x","مرجع باید هنگام تعریف مقدار بگیرد","پاس‌دادن با مرجع از کپی اشیا بزرگ جلوگیری می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"ref.cpp","code":"void inc(int& n) { n++; }   // مرجع، بدون کپی\nint x = 1;\ninc(x);\n// x حالا 2 است"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: int& r = x یک مرجع به x بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا پاس‌دادن شیء بزرگ با const& بهتر است؟","opts":["سریع‌تر کامپایل","چون کپی نمی‌شود و const تضمین می‌کند تغییر نکند","اجباری","برای GC"],"ans":1,"why":"کپی شیء بزرگ گران است؛ const& فقط آدرس را می‌دهد و const جلوی تغییر ناخواسته را می‌گیرد."},{"q":"چرا مرجع نمی‌تواند بعد از ساخت به متغیر دیگری وصل شود؟","opts":["محدودیت موقتی","مرجع از ابتدا هویتش همان متغیرِ مقصد است — «وصل‌شدن دوباره» برای مرجع معنا ندارد؛ آن کار اشاره‌گر است","کند می‌شود","نیاز به cast دارد"],"ans":1,"why":"مرجع نام مستعار است نه متغیر مستقل؛ درست مثل اینکه اسم «سارا» را نمی‌توانی به شخص دیگری بدهی. اگر به اتصالِ تغییرپذیر نیاز داری، ابزارش اشاره‌گر است."},{"q":"امضای void f(const std::string& s) چه قولی به صدازننده می‌دهد؟","opts":["فقط سریع‌تر است","ورودی کپی نمی‌شود (ارزان) و داخل تابع تغییر نمی‌کند (امن) — هر دو تضمین با کامپایلر","s تغییرناپذیر مطلق است","فقط برای رشته کار می‌کند"],"ans":1,"why":"مرجع یعنی بدون کپی و const یعنی کامپایلر جلوی تغییر را می‌گیرد؛ پس صدازننده می‌داند فراخوانی این تابع روی داده‌اش بی‌خطر و کم‌هزینه است — بدون خواندن بدنه."}]'::jsonb),
('cpp-b5', 'cpp', 'تابع و سرباری', 56, 11, '[{"k":"p","t":"توابع در C++ با نوع بازگشتی مشخص تعریف می‌شوند و سرباری بر اساس امضا کار می‌کند؛ پاس‌دادن پیش‌فرض و inline برای بهینه‌سازی‌اند."},{"k":"h","t":"تابع در C++؛ امضا و تعریف"},{"k":"p","t":"هر تابع در C++ یک نوع بازگشتی مشخص دارد که قبل از نام می‌آید و امضایش شامل نام و لیست پارامترهاست. سرباری (overloading) یعنی چند تابع هم‌نام با امضای متفاوت که کامپایلر بر اساس آرگومان‌های فراخوانی انتخاب می‌کند — ولی نوع بازگشتی جزو امضا نیست، پس دو تابع که فقط در نوع بازگشتی فرق دارند، مجاز نیستند. پاس‌دادن آرگومان به‌صورت پیش‌فرض (default) هم ممکن است ولی فقط از سمت راست، تا فراخوانی بدون ابهام بماند."},{"k":"h","t":"روش‌های پاس‌دادن آرگومان"},{"k":"p","t":"C++ سه راه برای پاس‌دادن آرگومان دارد: با مقدار (کپی می‌شود)، با مرجع (int& — بدون کپی و قابل‌تغییر) و با مرجع ثابت (const int& — بدون کپی و غیرقابل‌تغییر). برای اشیا بزرگ، پاس‌دادن با مقدار گران است چون کپی می‌کند؛ پس از const& استفاده می‌کنی که هم کپی ندارد هم تغییر نمی‌دهد. اگر می‌خواهی تابع واقعاً متغیر را تغییر بدهد، مرجع معمولی (بدون const) لازم است. این انتخاب‌ها مستقیم روی کارایی اثر دارند و یکی از تفاوت‌های کلیدی C++ با زبان‌های سطح‌بالاتر است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["روش پاس‌دادن","کپی","قابل‌تغییر در تابع","کی استفاده شود"],"rows":[["با مقدار (int x)","بله","خیر (روی کپی)","انواع کوچک مثل int"],["مرجع (int& x)","خیر","بله","وقتی باید متغیر اصلی عوض شود"],["مرجع ثابت (const int& x)","خیر","خیر","اشیا بزرگِ فقط‌خواندنی"]]},{"k":"warn","title":"دام رایج","t":"پارامتر پیش‌فرض را در وسط لیست نگذار؛ باید از سمت راست باشد. اگر وسطی پیش‌فرض باشد، فراخوانی با تعداد کمتر آرگومان مبهم می‌شود که مال کدام پارامتر است و کامپایلر اجازه نمی‌دهد."},{"k":"tip","title":"نکته منتور","t":"برای اشیا بزرگ، عادت کن همیشه const& پاس بدهی مگر اینکه واقعاً نیاز به کپی یا تغییر داشته باشی؛ این یک قانون ساده است که از کلی کپیِ غیرضروری جلوگیری می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نوع بازگشتی قبل از نام تابع","پارامتر پیش‌فرض باید از راست باشد","const بعد از امضا یعنی متد چیزی را عوض نمی‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"fn.cpp","code":"double area(double r, double pi = 3.14159) {\n    return pi * r * r;\n}\narea(2);        // pi پیش‌فرض\narea(2, 3.14);  // pi مشخص"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نوع بازگشتی قبل از نام تابع بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا پارامتر پیش‌فرض باید از سمت راست باشد؟","opts":["سلیقه","تا فراخوانی بدون ابهام باشد؛ پرش وسطی معنا ندارد","اجباری نیست","سرعت"],"ans":1,"why":"اگر وسطی پیش‌فرض باشد، فراخوانی با یک آرگومان معلوم نیست مال کدام پارامتر است."},{"q":"چرا دو تابع که فقط در نوع بازگشتی فرق دارند، مجاز نیستند؟","opts":["محدودیت قدیمی","چون نوع بازگشتی جزو امضا نیست و کامپایلر نمی‌تواند از روی آرگومان‌ها بفهمد کدام منظور است","باگ کامپایلر","ممکن است با cast"],"ans":1,"why":"فراخوانی f(x) را در نظر بگیر؛ اگر دو f فقط در نوع برگشتی فرق کنند، هیچ راهی برای انتخاب بینشان نیست. امضا فقط نام و پارامترهاست."},{"q":"برای پاس‌دادن یک شیء بزرگِ فقط‌خواندنی به تابع، کدام روش بهترین است؟","opts":["با مقدار","مرجع ثابت (const&)","مرجع معمولی","اشاره‌گر به null"],"ans":1,"why":"با مقدار کپی گران انجام می‌شود؛ مرجع معمولی اجازه تغییر ناخواسته می‌دهد؛ const& هم کپی ندارد و هم با const جلوی تغییر را می‌گیرد."}]'::jsonb),
('cpp-b6', 'cpp', 'کلاس و سازنده/مخرب', 56, 12, '[{"k":"p","t":"کلاس C++ با سازنده مقداردهی و با مخرب (~) پاک‌سازی می‌کند؛ قانون سه می‌گوید اگر یکی از کپی/انتساب/مخرب را نوشتی، احتمالاً هر سه لازم‌اند."},{"k":"h","t":"سازنده و مخرب؛ تولد و مرگ شیء"},{"k":"p","t":"کلاس در C++ با سازنده (constructor) مقداردهی اولیه می‌شود و با مخرب (destructor با علامت ~) پاک‌سازی می‌کند. مخرب هنگام پایان عمر شیء — چه خودکار در stack چه با delete در heap — صدا زده می‌شود و جای درست برای آزادکردن منابع است. لیست مقداردهی اولیه (initializer list) که قبل از بدنه سازنده می‌آید، فیلدها را مستقیم می‌سازد و برای مرجع‌ها و ثابت‌ها تنها راه است. این جفتِ سازنده/مخرب، پایه الگوی RAII است که مدیریت منابع در C++ را خودکار می‌کند."},{"k":"h","t":"قانون سه؛ کپی، انتساب، مخرب"},{"k":"p","t":"اگر کلاست منبعی مثل حافظه heap را مدیریت می‌کند، کپیِ پیش‌فرض (که فیلدها را سطحی کپی می‌کند) خطرناک است: دو شیء به یک حافظه اشاره می‌کنند و هر دو موقع تخریب delete‌اش می‌کنند — double free. قانون سه می‌گوید اگر یکی از این سه را نوشتی، احتمالاً هر سه لازم‌اند: سازنده کپی، عملگر انتساب، و مخرب. در C++ مدرن، اگر می‌توانی مالکیت را با smart pointer یا کانتینر (مثل vector) بیان کنی، اصلاً نیازی به نوشتن هیچ‌کدام نداری — این یعنی قانون صفر که ساده‌تر و امن‌تر است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کپی پیش‌فرض","کپی عمیق (دستی)"],"rows":[["فیلدها","سطحی کپی می‌شوند","محتوای منبع هم کپی می‌شود"],["اشاره‌گر به heap","هر دو به یک جا اشاره می‌کنند","هرکدام کپی خودش را دارد"],["خطر","double free هنگام تخریب","ندارد (اگر درست نوشته شود)"]]},{"k":"warn","title":"دام رایج","t":"اگر کلاست new دارد و مخرب delete، ولی سازنده کپی و عملگر انتساب ننوشته‌ای، تقریباً حتماً باگ داری؛ کپی پیش‌فرض دو شیء می‌سازد که یک حافظه را share می‌کنند و اولین تخریب، دومی را خراب می‌کند."},{"k":"tip","title":"نکته منتور","t":"در C++ مدرن اول سعی کن با قانون صفر جلو بروی: منابع را داخل smart pointer یا کانتینر بگذار تا خودشان مدیریت شوند؛ فقط وقتی واقعاً مجبوری، دستی مخرب و سازنده کپی بنویس."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سازنده هم‌نام کلاس؛ مخرب ~نام","لیست مقداردهی اولیه قبل از بدنه اجرا می‌شود","RAII: منابع در سازنده گرفته و در مخرب آزاد شوند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"cls.cpp","code":"class Buffer {\n    int* data_;\npublic:\n    Buffer(int n) : data_(new int[n]) {}\n    ~Buffer() { delete[] data_; }\n};"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سازنده هم‌نام کلاس؛ مخرب ~نام بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"RAII یعنی چه؟","opts":["یک کتابخانه","منابع با عمر شیء گره بخورند: گرفتن در سازنده، آزادسازی در مخرب","یک الگوریتم","نوع حافظه"],"ans":1,"why":"وقتی منبع داخل شیء است، با پایان عمر شیء (حتی در استثنا) خودکار آزاد می‌شود."},{"q":"RAII چه چیزی را تضمین می‌کند؟","opts":["سرعت بیشتر","منابع با عمر شیء گره می‌خورند: گرفتن در سازنده و آزادسازی خودکار در مخرب، حتی هنگام استثنا","کوتاه‌شدن کد","کاهش حافظه"],"ans":1,"why":"چون مخرب هنگام پایان عمر شیء همیشه صدا زده می‌شود (حتی اگر وسطش استثنا پرتاب شود)، منبعی که در سازنده گرفته شده حتماً آزاد می‌شود و نشتی پیش نمی‌آید."},{"q":"چرا کپی پیش‌فرض برای کلاسی که حافظه heap دارد خطرناک است؟","opts":["کند است","کپی سطحی دو شیء می‌سازد که به یک حافظه اشاره می‌کنند و هر دو موقع تخریب delete می‌کنند (double free)","حافظه زیاد می‌گیرد","کامپایل نمی‌شود"],"ans":1,"why":"کپی پیش‌فرض فقط مقدار اشاره‌گر را کپی می‌کند نه محتوای heap را؛ پس دو شیء یک منبع مشترک دارند و تخریب دومی، بعد از آزادشدنِ اولی، خطا می‌سازد."}]'::jsonb),
('cpp-b7', 'cpp', 'Smart Pointer', 56, 13, '[{"k":"p","t":"smart pointer با شمارش مرجع یا مالکیت یکتا، delete را خودکار می‌کند؛ unique_ptr مالکیت انحصاری و shared_ptr مالکیت اشتراکی دارد."},{"k":"h","t":"Smart Pointer؛ delete خودکار"},{"k":"p","t":"بزرگ‌ترین منبع باگ در C++، فراموش‌کردن delete (نشت حافظه) یا delete دوباره (خرابی) است. smart pointer این را حل می‌کند: شیءهایی که مالکیت یک منبع را می‌گیرند و وقتی خودشان از بین می‌روند، منبع را آزاد می‌کنند — پس delete خودکار می‌شود. دو نوع اصلی: unique_ptr که مالکیت انحصاری دارد (فقط یکی می‌تواند صاحبش باشد و با std::move منتقل می‌شود) و shared_ptr که مالکیت اشتراکی دارد با شمارنده مرجع (هرکس یک کپی بگیرد شمارنده یکی زیاد می‌شود و وقتی به صفر برسد، منبع آزاد می‌شود)."},{"k":"h","t":"کی کدام؛ و دام حلقه مرجع"},{"k":"p","t":"قاعده ساده: اول unique_ptr؛ چون مالکیتش روشن است و هزینه اضافی ندارد. فقط وقتی واقعاً چند جا باید همزمان صاحب یک منبع باشند و ندانی کدام آخر از همه می‌رود، shared_ptr لازم می‌شود. ولی shared_ptr یک دام دارد: حلقه مرجع. اگر A یک shared_ptr به B داشته باشد و B هم یک shared_ptr به A، شمارنده هیچ‌وقت صفر نمی‌شود و هر دو برای همیشه می‌مانند. راه‌حل، weak_ptr است که به منبع اشاره می‌کند بدون اینکه شمارنده را زیاد کند و حلقه را می‌شکند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","unique_ptr","shared_ptr","weak_ptr"],"rows":[["مالکیت","انحصاری (یکی)","اشتراکی (شمارنده)","بدون مالکیت"],["انتقال","با std::move","با کپی (شمارنده++)","—"],["هزینه","تقریباً صفر","شمارنده اتمیک","کم"],["کاربرد","پیش‌فرضِ همه‌جا","مالکیت واقعاً مشترک","شکستن حلقه مرجع"]]},{"k":"warn","title":"دام رایج","t":"shared_ptr را به‌صورت پیش‌فرض به کار نبر «چون امن‌تر به‌نظر می‌رسد»؛ هم سربار شمارنده اتمیک دارد و هم مالکیت را مبهم می‌کند. در بیشتر موارد یک صاحبِ روشن (unique_ptr) طراحی بهتر و سریع‌تری است."},{"k":"tip","title":"نکته منتور","t":"هرگز با new خام شروع نکن و بعد smart pointer نساز؛ با make_unique یا make_shared بساز تا هم استثنا-امن باشد و هم یک تخصیص کمتر داشته باشد: auto p = std::make_unique<Widget>();"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["unique_ptr قابل‌کپی نیست، فقط std::move","shared_ptr با شمارنده مرجع، آخرین که رفت delete می‌کند","همیشه make_unique و make_shared"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"smart.cpp","code":"#include <memory>\nauto p = std::make_unique<int>(42);\nauto s1 = std::make_shared<int>(7);\nauto s2 = s1;   // شمارنده = 2\n// وقتی s1 و s2 بروند، خودکار آزاد می‌شود"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: unique_ptr قابل‌کپی نیست، فقط std::move بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"unique_ptr چرا قابل‌کپی نیست؟","opts":["باگ","چون مالکیت یکتاست؛ کپی یعنی دو مالک و delete دوبار — فقط move مجاز است","کند","ممکن نیست"],"ans":1,"why":"اگر کپی می‌شد دو اشاره‌گر یک حافظه را delete می‌کردند؛ move مالکیت را منتقل می‌کند نه کپی."},{"q":"تفاوت اصلی unique_ptr و shared_ptr چیست؟","opts":["سرعت","unique_ptr مالکیت انحصاری دارد و فقط با move منتقل می‌شود؛ shared_ptr مالکیت اشتراکی با شمارنده مرجع دارد","نوع حافظه","اندازه"],"ans":1,"why":"unique_ptr یعنی دقیقاً یک صاحب؛ کپی‌اش ممکن نیست و فقط با move جابه‌جا می‌شود. shared_ptr اجازه می‌دهد چند صاحب داشته باشد و وقتی شمارنده صفر شد منبع آزاد می‌شود."},{"q":"حلقه مرجع (reference cycle) چیست و چطور حل می‌شود؟","opts":["یک حلقه for","وقتی دو shared_ptr به هم اشاره می‌کنند و شمارنده هیچ‌وقت صفر نمی‌شود؛ با weak_ptr که شمارنده را زیاد نمی‌کند","باگ کامپایلر","با delete دستی"],"ans":1,"why":"اگر A و B هرکدام shared_ptr به دیگری داشته باشند، شمارنده هر دو همیشه حداقل ۱ است و هیچ‌وقت آزاد نمی‌شوند؛ weak_ptr اشاره می‌کند بدون نگه‌داشتنِ مالکیت و حلقه را می‌شکند."}]'::jsonb),
('cpp-b8', 'cpp', 'وراثت و چندریختی مجازی', 56, 14, '[{"k":"p","t":"وراثت با : public و متد مجازی با virtual؛ وقتی متد virtual باشد فراخوانی از اشاره‌گر پایه به نسخه واقعی می‌رود — و مخرب پایه باید مجازی باشد."},{"k":"h","t":"وراثت و متد مجازی (virtual)"},{"k":"p","t":"وراثت در C++ با : public انجام می‌شود و فرزند متدهای پایه را به ارث می‌برد. ولی برای اینکه چندریختی کار کند — یعنی فراخوانی از اشاره‌گرِ پایه، نسخه واقعیِ فرزند را اجرا کند — متد پایه باید virtual اعلام شده باشد. بدون virtual، انتخاب متد در زمان کامپایل و بر اساس نوع اشاره‌گر است (statisch)، نه نوع واقعی شیء. با virtual، جدول مجازی (vtable) ساخته می‌شود و انتخاب در زمان اجرا بر اساس نوع واقعی انجام می‌شود."},{"k":"h","t":"چرا مخرب پایه باید مجازی باشد"},{"k":"p","t":"اگر شیء فرزند را با اشاره‌گرِ پایه delete کنی و مخرب پایه virtual نباشد، فقط مخرب پایه صدا زده می‌شود و مخرب فرزند اجرا نمی‌شود — پس منابعی که فرزند گرفته آزاد نمی‌شود (رفتار تعریف‌نشده). به همین دلیل هر کلاسی که قرار است از آن ارث برده شود و شیءهایش با اشاره‌گر پایه delete شوند، باید مخرب مجازی (virtual ~Base()) داشته باشد. این یکی از آن قوانینی است که نادیده‌گرفتنش، باگ‌های پنهان و خطرناک می‌سازد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","بدون virtual","با virtual"],"rows":[["انتخاب متد","زمان کامپایل (نوع اشاره‌گر)","زمان اجرا (نوع واقعی شیء)"],["مکانیزم","فراخوانی مستقیم","جدول مجازی (vtable)"],["چندریختی","کار نمی‌کند","کار می‌کند"],["هزینه","کمتر","یک indirection کوچک"]]},{"k":"warn","title":"دام رایج","t":"فراموش‌کردن virtual روی مخربِ کلاس پایه، وقتی شیء فرزند را با اشاره‌گر پایه delete می‌کنی، باعث می‌شود مخرب فرزند اجرا نشود و منابعش نشت کند — یک باگ پنهان که خیلی دیر خودش را نشان می‌دهد."},{"k":"tip","title":"نکته منتور","t":"در C++ مدرن برای بازنویسی متد در فرزند از کلمه override استفاده کن؛ اگر امضا با متد مجازی پایه یکی نباشد، کامپایلر خطا می‌دهد و از بازنویسیِ ناخواسته (که در واقع یک متد جدید است) جلوگیری می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["virtual در پایه، override در فرزند","اشاره‌گر پایه به شیء فرزند + متد مجازی = چندریختی","مخرب غیرمجازی پایه هنگام حذف از پایه، رفتار تعریف‌نشده است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"virt.cpp","code":"struct Shape {\n    virtual double area() const = 0;   // خالص\n    virtual ~Shape() = default;\n};\nstruct Circle : Shape {\n    double area() const override { return 3.14; }\n};"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: virtual در پایه، override در فرزند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا مخرب کلاس پایه باید virtual باشد؟","opts":["سرعت","تا حذف شیء فرزند از اشاره‌گر پایه، مخرب فرزند را هم صدا بزند","اجباری نیست","برای کپی"],"ans":1,"why":"بدون مخرب مجازی، فقط مخرب پایه صدا می‌خورد و منابع فرزند نشت می‌کنند."},{"q":"چرا برای چندریختی در C++ متد پایه باید virtual باشد؟","opts":["برای سرعت","بدون virtual انتخاب متد در زمان کامپایل و بر اساس نوع اشاره‌گر است؛ virtual آن را به زمان اجرا و نوع واقعی شیء منتقل می‌کند","اجباری نیست","برای کاهش حافظه"],"ans":1,"why":"بدون virtual، اگر اشاره‌گر از نوع پایه باشد، متد پایه اجرا می‌شود حتی اگر شیء واقعی فرزند باشد؛ virtual با vtable انتخاب را بر اساس نوع واقعی در اجرا انجام می‌دهد."},{"q":"چرا مخرب کلاس پایه باید مجازی (virtual) باشد؟","opts":["برای زیبایی","تا هنگام delete از طریق اشاره‌گر پایه، مخرب فرزند هم اجرا شود و منابعش آزاد گردد","برای سرعت","اجباری نیست"],"ans":1,"why":"اگر مخرب پایه virtual نباشد و شیء فرزند با اشاره‌گر پایه delete شود، فقط مخرب پایه اجرا می‌شود و پاک‌سازی فرزند انجام نمی‌شود که باعث نشت منابع و رفتار تعریف‌نشده است."}]'::jsonb),
('cpp-b9', 'cpp', 'کانتینرهای STL', 56, 15, '[{"k":"p","t":"STL کانتینرهای آماده مثل vector و map و string را می‌دهد؛ vector آرایه پویا، map درخت مرتب و unordered_map هش است."},{"k":"h","t":"کانتینرهای STL؛ ساختارهای آماده"},{"k":"p","t":"کتابخانه استاندارد C++ (STL) مجموعه‌ای از کانتینرهای آماده و بهینه دارد که لازم نیست خودت بنویسی: vector یک آرایه پویا با دسترسی ایندکسی O(1) و رشد خودکار است؛ list لیست پیوندی دوطرفه برای درج/حذف سریع؛ map یک درخت مرتب برای نگاشت کلید-مقدار با جست‌وجوی O(log n)؛ و unordered_map جدول هش با جست‌وجوی میانگین O(1). برای متن هم string هست که همه عملیات رایج را مدیریت می‌کند و نگرانی مدیریت حافظه دستی را حذف می‌کند."},{"k":"h","t":"انتخاب کانتینر بر اساس عملیات"},{"k":"p","t":"انتخاب کانتینر باید بر اساس عملیات غالب باشد: اگر زیاد با ایندکس می‌خوانی و به انتها اضافه می‌کنی، vector تقریباً همیشه جواب درست است (و به‌خاطر پیوستگی حافظه، کش‌دوست هم هست). اگر نیاز به نگاشت کلید-مقدار مرتب داری map و اگر فقط سرعت جست‌وجو مهم است unordered_map. یک اشتباه رایج، استفاده از list فقط به‌خاطر «درج سریع» است؛ ولی چون گره‌هایش پراکنده‌اند و کش‌ناپذیر، در عمل اغلب vector حتی برای درج هم سریع‌تر است مگر واقعاً در وسط زیاد درج/حذف کنی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["کانتینر","ساختار","دسترسی/جست‌وجو","کی استفاده شود"],"rows":[["vector","آرایه پویا","ایندکس O(1)","پیش‌فرض؛ خواندن با ایندکس"],["list","لیست پیوندی دوطرفه","پیمایش O(n)","درج/حذف واقعی در وسط"],["map","درخت مرتب","O(log n)","نگاشت مرتب‌شده"],["unordered_map","جدول هش","میانگین O(1)","جست‌وجوی سریع با کلید"],["string","متن پویا","—","همه عملیات متنی"]]},{"k":"warn","title":"دام رایج","t":"vector را دست‌کم نگیر و بی‌دلیل سراغ list نرو؛ چون حافظه vector پیوسته است، در عمل برای اکثر الگوها — حتی درج — از list سریع‌تر است. فقط وقتی واقعاً در وسطِ لیست زیاد درج/حذف می‌کنی و ایندکس‌ها پایدار لازم داری، list را در نظر بگیر."},{"k":"tip","title":"نکته منتور","t":"بعد از حذف‌های زیاد یا reserve از قبل، اگر می‌دانی vector بزرگ‌تر از نیاز شده، shrink_to_fit() حافظه اضافی را برمی‌گرداند؛ ولی در حالت عادی نگران ظرفیت vector نباش چون رشدش هوشمند و آمورتیزه O(1) است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["vector با push_back رشد می‌کند و دسترسی O(1)","map کلیدها را مرتب نگه می‌دارد؛ unordered_map سریع‌تر","string قابل‌اتصال با + و مقایسه با =="]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"stl.cpp","code":"#include <vector>\n#include <map>\nstd::vector<int> v = {3, 1, 4};\nv.push_back(5);\nstd::map<std::string, int> ages;\nages[\"sara\"] = 30;"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: vector با push_back رشد می‌کند و دسترسی O(1) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت map و unordered_map چیست؟","opts":["هیچ","map درخت قرمز‌سیاه و مرتب با O(log n)؛ unordered_map هش با میانگین O(1) ولی نامرتب","اندازه","نوع کلید"],"ans":1,"why":"map ترتیب کلیدها را می‌دهد ولی کندتر؛ unordered_map سریع‌تر ولی ترتیبی ندارد."},{"q":"چرا unordered_map سریع‌تر از map برای جست‌وجو است؟","opts":["جدیدتر است","جدول هش است و میانگین O(1) جست‌وجو می‌کند؛ map درخت است و O(log n)","حافظه کمتر","مرتب است"],"ans":1,"why":"unordered_map با هش مستقیم به خانه موردنظر می‌رود (میانگین O(1))؛ ولی map چون درخت مرتب است باید ارتفاع درخت را طی کند (O(log n)). اگر مرتب‌بودن کلیدها لازم نیست، unordered_map سریع‌تر است."},{"q":"چرا vector معمولاً از list سریع‌تر است حتی برای درج؟","opts":["کدش بهتر است","چون حافظه‌اش پیوسته و کش‌دوست است؛ در حالی که گره‌های list پراکنده‌اند و کش را خراب می‌کنند","کوچک‌تر است","جدیدتر است"],"ans":1,"why":"پردازنده با حافظه پیوسته خیلی سریع‌تر کار می‌کند؛ پس حتی عملیاتی که از نظر Big-O برای list بهتر است، در عمل به‌خاطر کش روی vector سریع‌تر اجرا می‌شود."}]'::jsonb),
('cpp-b10', 'cpp', 'الگوریتم‌های STL', 56, 16, '[{"k":"p","t":"الگوریتم‌های <algorithm> روی بازه‌ها کار می‌کنند؛ sort، find و transform با iterator و بدون نیاز به دانستن نوع کانتینر."},{"k":"h","t":"الگوریتم‌های STL؛ کار با بازه‌ها"},{"k":"p","t":"هدر <algorithm> مجموعه‌ای از الگوریتم‌های آماده دارد که روی «بازه» کار می‌کنند، نه روی کانتینر خاص: sort برای مرتب‌سازی، find برای جست‌وجو، transform برای تبدیل، count و accumulate برای تجمیع. این الگوریتم‌ها با iterator کار می‌کنند، پس با هر کانتینری (vector، list، آرایه) یکسان استفاده می‌شوند. فایده بزرگ، استفاده‌مجدد و بهینه بودن است؛ مثلاً sort از introsort استفاده می‌کند که در عمل بسیار سریع‌تر از مرتب‌سازی‌های دست‌نویس معمولی است."},{"k":"h","t":"iterator؛ واسط مشترک"},{"k":"p","t":"iterator مفهومی است که «پیمایش یک دنباله» را از نوع کانتینر جدا می‌کند: هر کانتینر begin() و end() دارد که ابتدای بازه و یکی‌بعدازآخر را می‌دهند و الگوریتم‌ها فقط با همین دو کار می‌کنند. به همین دلیل std::sort(v.begin(), v.end()) روی vector و list و آرایه یکسان کار می‌کند. در C++ مدرن، range-based for (for (auto x : container)) پیمایش را ساده‌تر کرده و برای الگوریتم‌ها هم rangeهای جدید (از C++20) کار با begin/end را کوتاه‌تر کرده‌اند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["الگوریتم","کار","مثال"],"rows":[["sort","مرتب‌سازی بازه","std::sort(v.begin(), v.end())"],["find","جست‌وجوی یک مقدار","std::find(..., value)"],["transform","تبدیل هر عنصر","std::transform(in, out, fn)"],["accumulate","جمع/تجمیع","std::accumulate(..., init)"],["count_if","شمارش با شرط","std::count_if(..., pred)"]]},{"k":"warn","title":"دام رایج","t":"sort روی list مستقیم کار نمی‌کند چون sort نیاز به iterator با دسترسی تصادفی دارد؛ برای list از متد خودِ list یعنی mylist.sort() استفاده کن. همیشه ببین الگوریتم چه نوع iteratorای می‌خواهد و کانتینرت آن را دارد یا نه."},{"k":"tip","title":"نکته منتور","t":"به‌جای نوشتن حلقه برای کارهای رایج، اول ببین آیا الگوریتم STL هست؛ sort، find، accumulate و امثال این‌ها نه‌تنها کوتاه‌ترند، بلکه بهینه‌تر و کمتر مستعد باگ از نسخه دست‌نویس‌اند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["std::sort بازه [begin, end) را مرتب می‌کند","lambda برای comparator سفارشی","الگوریتم‌ها با iterator عمومی‌اند نه کانتینر خاص"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"algo.cpp","code":"#include <algorithm>\nstd::vector<int> v = {5, 2, 8};\nstd::sort(v.begin(), v.end(),\n    [](int a, int b) { return a > b; });\n// v: 8 5 2 — نزولی"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: std::sort بازه [begin, end) را مرتب می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا الگوریتم‌های STL با iterator کار می‌کنند نه کانتینر؟","opts":["تصادفی","تا یک الگوریتم با هر کانتینری (vector، list، آرایه) کار کند — جداسازی الگوریتم از ساختار","سرعت","اجباری"],"ans":1,"why":"iterator رابط مشترک پیمایش است؛ پس sort برای هر ساختاری که iterator بدهد کار می‌کند."},{"q":"چرا الگوریتم‌های STL با کانتینرهای مختلف یکسان کار می‌کنند؟","opts":["چون ساده‌اند","چون با iterator (begin/end) کار می‌کنند نه با نوع خاص کانتینر، پس پیمایش از نوع داده جدا شده","چون جدیدند","چون سریع‌اند"],"ans":1,"why":"iterator یک واسط مشترک برای پیمایش هر دنباله‌ای است؛ الگوریتم فقط می‌گوید «از این شروع کن تا آنجا برو» و نمی‌داند زیرش vector است یا list یا آرایه."},{"q":"چرا std::sort روی std::list کار نمی‌کند و باید از list.sort() استفاده کرد؟","opts":["باگ است","چون std::sort نیاز به iterator با دسترسی تصادفی دارد که list ندارد؛ list متد مرتب‌سازی مخصوص خودش را دارد","کندتر است","ممکن است با cast"],"ans":1,"why":"sort استاندارد برای بازه‌هایی با دسترسی تصادفی (مثل vector) طراحی شده؛ list پیوندی دسترسی تصادفی ندارد، پس از الگوریتم مرتب‌سازی داخلی خودش استفاده می‌کند."}]'::jsonb),
('cpp-b11', 'cpp', 'Move Semantics', 56, 17, '[{"k":"p","t":"Move به‌جای کپی، منابع را منتقل می‌کند؛ با std::move و سازنده انتقال، داده‌های بزرگ بدون کپی جابه‌جا می‌شوند و کارایی چندبرابر می‌شود."},{"k":"h","t":"Move Semantics؛ منتقل‌کردن به‌جای کپی"},{"k":"p","t":"وقتی یک شیء بزرگ (مثل vector با میلیون‌ها عنصر) را برمی‌گردانی یا جابه‌جا می‌کنی، کپی‌کردنش بسیار گران است. Move Semantics می‌گوید: به‌جای کپی، «مالکیت منابع» را منتقل کن. شیء مبدأ (rvalue) دیگر لازم نیست سالم بماند، پس می‌توانی اشاره‌گرهایش را بدزدی و خودش را خالی بگذاری — این کار O(1) است به‌جای O(n). std::move یک شیء را به rvalue تبدیل می‌کند تا سازنده انتقال (move constructor) فعال شود و منابع به‌جای کپی، منتقل شوند."},{"k":"h","t":"rvalue و lvalue؛ دو دسته عبارت"},{"k":"p","t":"lvalue عبارتی است که هویت دارد و می‌توانی آدرسش را بگیری (مثل یک متغیر نام‌دار)؛ rvalue عبارتی موقت و بی‌هویت است (مثل مقدار برگشتی یک تابع یا یک عدد). سازنده کپی برای lvalueها استفاده می‌شود چون منبع هنوز لازم است، ولی سازنده انتقال برای rvalueها چون می‌دانیم این موقت دیگر استفاده نمی‌شود و می‌شود منابعش را گرفت. این تشخیص به کامپایلر اجازه می‌دهد در جاهایی که امن است، به‌جای کپیِ گران، انتقالِ ارزان انجام بدهد — و یکی از دلایل اصلی کارایی C++ مدرن است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کپی (copy)","انتقال (move)"],"rows":[["چه می‌شود","منابع duplication می‌شوند","مالکیت منابع منتقل می‌شود"],["هزینه","O(n) — متناسب با اندازه","O(1) — فقط جابه‌جایی اشاره‌گرها"],["منبع (مبدأ)","سالم می‌ماند","خالی/نامشخص می‌شود"],["کی استفاده می‌شود","برای lvalue (چیزهای نام‌دار)","برای rvalue (موقتی‌ها) با std::move"]]},{"k":"warn","title":"دام رایج","t":"std::move فقط «مجوز» انتقال است و چیزی را واقعاً جابه‌جا نمی‌کند؛ فقط نوع را طوری تبدیل می‌کند که سازنده انتقال انتخاب شود. اگر کلاست سازنده انتقال ندارد، std::move بی‌اثر است و باز کپی انجام می‌شود. ضمن اینکه بعد از move، شیء مبدأ را دیگر استفاده نکن چون وضعیتش نامشخص است."},{"k":"tip","title":"نکته منتور","t":"برای اکثر کدها لازم نیست دستی move بنویسی؛ کامپایلر با copy elision و move خودکار، بسیاری از کپی‌ها را حذف می‌کند. فقط وقتی یک کلاس مدیریت منابع دستی دارد، سازنده و عملگر انتقال بنویس (یا بهتر، با قانون صفر و smart pointer کلاً نیاز را حذف کن)."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["std::move فقط به rvalue تبدیل می‌کند، جابه‌جا نمی‌کند","سازنده انتقال منابع را می‌دزدد و منبع را خالی می‌کند","برای vector و string بزرگ، تفاوت کپی و move عظیم است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"move.cpp","code":"std::vector<int> make() {\n    std::vector<int> v(1000000, 1);\n    return v;   // انتقال، نه کپی\n}\nstd::vector<int> a = make();\nstd::vector<int> b = std::move(a);  // a خالی شد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: std::move فقط به rvalue تبدیل می‌کند، جابه‌جا نمی‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"std::move واقعاً چه می‌کند؟","opts":["داده را جابه‌جا می‌کند","فقط شیء را به rvalue کست می‌کند تا سازنده انتقال انتخاب شود","حذف می‌کند","کپی می‌کند"],"ans":0,"why":"move خودش چیزی جابه‌جا نمی‌کند؛ فقط اجازه می‌دهد سازنده انتقال منابع را بدزدد."},{"q":"Move Semantics چه چیزی را به‌جای کپی انجام می‌دهد؟","opts":["فشرده‌سازی","انتقال مالکیت منابع (مثل اشاره‌گرهای heap) از یک شیء موقت به شیء مقصد با هزینه O(1)","رمزنگاری","حذف داده"],"ans":1,"why":"چون شیء موقت (rvalue) دیگر لازم نیست، به‌جای کپی‌کردنِ گرانِ منابعش، فقط مالکیت آن‌ها به مقصد منتقل می‌شود و مبدأ خالی می‌شود — این کار ثابت است نه متناسب با اندازه."},{"q":"std::move واقعاً چه می‌کند؟","opts":["داده را جابه‌جا می‌کند","فقط شیء را به rvalue تبدیل (cast) می‌کند تا سازنده انتقال انتخاب شود؛ خودش چیزی جابه‌جا نمی‌کند","حافظه را آزاد می‌کند","کپی می‌گیرد"],"ans":1,"why":"std::move فقط یک cast است که می‌گوید «این را به‌عنوان منبع انتقال در نظر بگیر»؛ انتقال واقعی را سازنده انتقال انجام می‌دهد. پس اگر سازنده انتقال نباشد، فقط کپی اتفاق می‌افتد."}]'::jsonb),
('cpp-b12', 'cpp', 'مدیریت خطا با exception', 56, 18, '[{"k":"p","t":"C++ با try/catch/throw خطا را مدیریت می‌کند؛ RAII تضمین می‌کند حتی هنگام پرتاب استثنا منابع آزاد شوند چون مخرب‌ها صدا زده می‌شوند."},{"k":"h","t":"مدیریت خطا با exception"},{"k":"p","t":"C++ با try/catch/throw خطاها را مدیریت می‌کند: عملیات مشکوک را در try انجام می‌دهی، خطا را با throw پرتاب می‌کنی و در catch می‌گیری. استثنا در C++ برای شرایط واقعاً استثنایی است (نه جریان عادی) چون پرتابش گران است. نکته مهم: می‌توانی چند catch برای انواع مختلف خطا بنویسی و اگر یک catch با مرجع ثابت (catch (const std::exception& e)) بگیری، همه استثناهای استاندارد را پوشش می‌دهی و با e.what() پیام را می‌خوانی."},{"k":"h","t":"RAII و استثنا-ایمنی"},{"k":"p","t":"یکی از مهم‌ترین دلایل استفاده از RAII در C++، استثنا-ایمنی است: وقتی وسط تابع استثنا پرتاب می‌شود، همه شیءهای محلیِ stack تخریب می‌شوند (stack unwinding) و مخرب‌هایشان صدا زده می‌شود. پس اگر منابع داخل شیء (smart pointer، vector، lock) باشند، حتی با پرتاب استثنا هم آزاد می‌شوند و نشتی پیش نمی‌آید. ولی اگر منابع را دستی با new گرفته باشی و وسطش استثنا بیفتد، delete هرگز اجرا نمی‌شود — این هم یک دلیل دیگر که چرا RAII و smart pointer در C++ مدرن ضروری‌اند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","مدیریت با خطای بازگشتی","مدیریت با exception"],"rows":[["جریان","بررسی بعد از هر فراخوانی","پرش مستقیم به catch"],["هزینه","ارزان","گران هنگام پرتاب"],["فراموش‌کردن بررسی","آسان (کد ادامه می‌یابد)","سخت (اگر نگیری، برنامه خاتمه می‌یابد)"],["کی استفاده شود","جریان‌های عادی و موردانتظار","شرایط واقعاً استثنایی"]]},{"k":"warn","title":"دام رایج","t":"از استثنا برای جریان عادی برنامه (مثل «کاربر پیدا نشد») استفاده نکن؛ پرتاب استثنا در C++ گران است و کد را پیچیده می‌کند. برای حالت‌های موردانتظار، مقدار بازگشتی یا std::optional بهتر است و استثنا را برای خطاهای واقعی نگه دار."},{"k":"tip","title":"نکته منتور","t":"اگر از منابع دستی (new/raw pointer) استفاده می‌کنی و تابعی استثنا پرتاب می‌کند، حتماً بررسی کن که در مسیر استثنا منبع آزاد می‌شود یا نه؛ بهترین راه، تبدیل منابع به smart pointer و کانتینر است تا stack unwinding خودش پاک‌سازی کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["throw هر شیء (معمولاً std::exception مشتق) پرتاب می‌کند","catch بلوک‌ها به ترتیب و catch(...) تور آخر","noexcept تضمین می‌کند تابع استثنا ندارد — برای move مهم"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"exc.cpp","code":"#include <stdexcept>\ndouble div(double a, double b) {\n    if (b == 0)\n        throw std::invalid_argument(\"تقسیم بر صفر\");\n    return a / b;\n}\ntry { div(1, 0); }\ncatch (const std::exception& e) {\n    std::cerr << e.what();\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: throw هر شیء (معمولاً std::exception مشتق) پرتاب می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا RAII هنگام استثنا مهم است؟","opts":["سرعت","چون هنگام unwinding مخرب‌های اشیا صدا زده می‌شوند و منابع آزاد می‌مانند","اجباری","برای کپی"],"ans":1,"why":"وقتی استثنا پرتاب می‌شود، stack خالی و مخرب‌ها اجرا می‌شوند؛ اگر منبع در شیء باشد (RAII) خودکار آزاد می‌شود."},{"q":"چرا RAII باعث استثنا-ایمنی می‌شود؟","opts":["سرعت را زیاد می‌کند","چون هنگام پرتاب استثنا، شیءهای محلی تخریب و مخرب‌هایشان صدا زده می‌شوند؛ پس منابعی که داخل شیء باشند آزاد می‌شوند","کد را کوتاه می‌کند","استثنا را حذف می‌کند"],"ans":1,"why":"stack unwinding تضمین می‌کند همه شیءهای محلی موقع خروج با استثنا تخریب شوند؛ اگر منبع داخل یک شیء (مثل smart pointer) باشد، مخربش آزادش می‌کند و نشتی پیش نمی‌آید."},{"q":"چرا نباید از استثنا برای جریان عادی برنامه استفاده کرد؟","opts":["ممکن نیست","چون پرتاب استثنا در C++ گران است و برای حالت‌های موردانتظار، مقدار بازگشتی یا std::optional ساده‌تر و سریع‌تر است","کد زشت می‌شود","کامپایل نمی‌شود"],"ans":1,"why":"استثنا برای شرایط نادر طراحی شده و ساختار پرتاب/گرفتنش هزینه دارد؛ برای چیزهایی که مرتب اتفاق می‌افتند (مثل پیدا نشدن کاربر)، راه‌های سبک‌تری مثل optional وجود دارد."}]'::jsonb),
('os-r1', 'os', 'Process و Thread؛ توهمِ هم‌زمانی', 60, 1, '[{"k":"p","t":"چطور یک CPU چهارهسته‌ای همزمان ده‌ها برنامه را اجرا می‌کند وقتی ده‌ها برنامه یعنی ده‌ها برابرِ ظرفیتش؟ پاسخ، یک فریب باشکوه است: سیستم‌عامل آن‌قدر سریع بین کارها جابه‌جا می‌شود که همه فکر می‌کنند تنها هستند. فهمیدن این «توهم» کلید درک همزمانی است."},{"k":"h","t":"Process: واحدِ انزوا"},{"k":"p","t":"هر برنامه در حال اجرا یک Process است: فضایی جدا از حافظه، شناسه‌ای یکتا (PID) و وضعیتی مستقل. مرز بین Processها واقعی و سخت‌افزاری است؛ اگر یکی کرش کند، بقیه سالم می‌مانند چون نمی‌توانند به حافظه هم دست بزنند. این انزوا دلیل امنیت و پایداری است، ولی به قیمت سربار: ساختن Process و جابه‌جایی بینشان گران است چون کل فضای آدرس عوض می‌شود."},{"k":"h","t":"Thread: واحدِ اجرا"},{"k":"p","t":"Threadها خطوط اجرای مستقل «داخلِ» یک Process‌اند؛ همه Threadهای یک Process، همان حافظه را به‌اشتراک می‌گذارند. پس ارتباطشان با هم ارزان و سریع است، ولی دقیقاً همین اشتراک، خطرناکشان می‌کند: اگر دو Thread همزمان یک متغیر را تغییر دهند، نتیجه به زمان‌بندی وابسته و غیرقابل‌پیش‌بینی می‌شود — همان Race Condition معروف."},{"k":"h","t":"کجا کدام را انتخاب کنیم"},{"k":"p","t":"قاعده کلی: اگر واحدها باید کاملاً مستقل و امن از هم باشند (مثل تب‌های مرورگر یا سرویس‌های جدا)، Process؛ اگر قرار است روی یک داده مشترک کار کنند و ارتباط زیاد لازم است (مثل رندر و منطق یک بازی)، Thread. در عملِ برنامه‌نویسی، بیشتر اوقات اصلاً نباید دستی Thread ساخت؛ استخر Thread و ساختارهای هم‌روند این پیچیدگی را پنهان می‌کنند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"proc_thread.py","code":"import threading\n\ncounter = 0\nlock = threading.Lock()\n\ndef bump():\n    global counter\n    with lock:            # بدون این، نتیجه تصادفی است!\n        counter += 1\n\nthreads = [threading.Thread(target=bump) for _ in range(10)]\n[t.start() for t in threads]\n[t.join() for t in threads]\nprint(counter)            # با lock: همیشه 10"},{"k":"list","items":["counter += 1 یک عمل نیست؛ سه عمل است (خواندن، جمع، نوشتن). دو Thread می‌توانند وسط این سه عمل پرش کنند و یکی از افزایش‌ها گم شود.","with lock تضمین می‌کند در هر لحظه فقط یک Thread داخل بلوک است؛ بقیه پشت در منتظر می‌مانند. این یعنی «بخش بحرانی».","join() یعنی «صبر کن این Thread تمام شود»؛ بدون آن ممکن است قبل از پایان کارها، نتیجه را چاپ کنی."]},{"k":"def","term":"Race Condition","t":"وقتی نتیجه برنامه به ترتیب زمانیِ اجرای دستوراتِ چند Thread وابسته می‌شود؛ چون هر دو به یک داده مشترک دسترسی دارند و حداقل یکی می‌نویسد. درمانش همگام‌سازی است: قفل، ساختارهای اتمیک، یا حذف کامل حالت مشترک."},{"k":"table","head":["ویژگی","Process","Thread"],"rows":[["حافظه","جدا و ایزوله","مشترک داخل Process"],["سربار ساخت/سوییچ","زیاد","کم"],["اثر کرش یکی","بقیه سالم","کل Process می‌میرد"],["ارتباط بین‌شان","IPC (گران)","مستقیم (ارزان ولی خطرناک)"]]},{"k":"warn","title":"دام رایج","t":"افزودن Thread برای سرعت‌دادن به کارِ CPU-bound در پایتون و انتظار نتیجه؛ به‌خاطر GIL، Threadهای پایتون کد پایتونی را واقعاً همزمان اجرا نمی‌کنند. برای کار محاسباتی از multiprocessing (چند Process) استفاده کن، نه threading."},{"k":"tip","title":"نکته حرفه‌ای","t":"قبل از رسیدن به قفل و همگام‌سازی، بپرس آیا اصلاً به حالت مشترک نیاز داری؛ خیلی از Race Conditionها با «نگذراندن داده مشترک» (مثلاً صف پیام بین واحدها) از اساس حذف می‌شوند و این امن‌ترین راه است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Process واحد انزوا با حافظه جدا؛ Thread واحد اجرا با حافظه مشترک","اشتراک حافظه، Race Condition را ممکن می‌کند","بخش بحرانی را با قفل محافظت کن","برای CPU-bound در پایتون از Process استفاده کن نه Thread"]}]'::jsonb, '[{"q":"تفاوت اصلی Process و Thread چیست؟","opts":["سرعت","Process حافظه جدا و ایزوله دارد؛ Threadها حافظه مشترک داخل یک Process","Thread بزرگ‌تر است","هیچ"],"ans":1,"why":"مرز Process واقعی است و انزوا می‌آورد؛ Threadها سبک‌ترند ولی چون حافظه مشترک دارند مستعد Race Condition‌اند."},{"q":"Race Condition چه زمانی رخ می‌دهد؟","opts":["همیشه","وقتی چند Thread به داده مشترک دسترسی دارند، حداقل یکی می‌نویسد و نتیجه به زمان‌بندی وابسته می‌شود","فقط در CPU-bound","فقط با GIL"],"ans":1,"why":"دسترسی همزمان بدون همگام‌سازی به داده مشترکِ قابل‌نوشتن، ترتیب اجرا را تعیین‌کننده نتیجه می‌کند."},{"q":"چرا lock برای counter += 1 لازم است؟","opts":["برای سرعت","چون این عمل سه مرحله‌ای است و پرش وسطش می‌تواند یک افزایش را گم کند","اجباری نیست","برای حافظه"],"ans":1,"why":"خواندن، جمع و نوشتن جدا هستند؛ lock کل این سه را اتمیک می‌کند تا هیچ Threadی وسطش نپرد."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('n-os-l1', 'os', 'Process و Thread؛ توهم چندکاره‌گی', 50, 2, '[{"k":"p","t":"برنامه فایل مرده‌ی روی دیسک است؛ Process همان برنامه در حال اجرا با حافظه اختصاصی خودش. سیستم‌عامل با Context Switch آن‌قدر سریع بین Processها جابه‌جا می‌شود که به چشم می‌آید همزمان‌اند — روی یک هسته، فقط یک نفر در هر لحظه اجراست."},{"k":"code","lang":"bash","title":"terminal","code":"# چه چیزی در حال اجراست؟\n$ ps aux | head\nUSER   PID  %CPU %MEM  COMMAND\nroot     1   0.0  0.1  /sbin/init\nsara  2143  12.4  3.2  /usr/bin/python3 server.py\n\n# هر Process چند Thread دارد؟\n$ ps -o nlwp -p 2143\nNLWP\n   8\n\n# پایتون: دو Thread یک Process — حافظه مشترک\nimport threading\n\ndef worker(name):\n    print(f\"salam az {name}\")\n\nt1 = threading.Thread(target=worker, args=(\"t1\",))\nt2 = threading.Thread(target=worker, args=(\"t2\",))\nt1.start(); t2.start()\nt1.join();  t2.join()"},{"k":"visual","visual":"stackHeap","title":"شبیه‌ساز: Stack و Heap"},{"k":"table","head":["ویژگی","Process","Thread"],"rows":[["حافظه","کاملاً جدا","مشترک (Heap) — Stack جدا"],["هزینه ساخت","سنگین (کپی جدول‌ها)","سبک"],["ارتباط","IPC (pipe, socket)","مستقیم از حافظه مشترک"],["خرابی","به بقیه آسیب نمی‌زند","یک Thread می‌تواند همه را بکُشد"]]},{"k":"def","term":"Context Switch","t":"ذخیره وضعیت (رجیسترها، جدول صفحه) پردازش فعلی و بارگذاری وضعیت بعدی. هر سوئیچ چند میکروثانیه هزینه دارد؛ برای همین Processهای زیادِ فعال، کل سیستم را کند می‌کنند حتی اگر CPU بیکار به نظر برسد."},{"k":"h","t":"عمیق‌تر: Thread ارزان‌تر است، ولی قراردادش سخت‌تر"},{"k":"p","t":"چرا Thread از Process ارزان‌تر است؟ چون Process جدید یعنی کپی جدول صفحه، بازکردن فایل‌ها و ساختن فضای آدرس تازه — چند مگابایت و چند میلی‌ثانیه؛ ولی Thread فقط یک پشته و چند ثبات جدید در همان فضای آدرس فعلی می‌سازد — چند ده کیلوبایت و چند میکروثانیه. همین اشتراکِ فضای آدرس، هم قدرت است و هم خطر: دو Thread می‌توانند بدون هیچ واسطه‌ای داده رد و بدل کنند (قدرت) ولی اگر یکی، داده‌ای را که دیگری در حال خواندنش است تغییر بدهد، نتیجه «شرایط رقابتی» است — باگی که فقط گاهی ظاهر می‌شود و دیباگش کابوس است چون به زمان‌بندی وابسته است."},{"k":"code","lang":"py","title":"شرایط رقابتی در پنج خط","code":"import threading\n\ncounter = 0\n\ndef add():\n    global counter\n    for _ in range(100_000):\n        counter += 1        # خواندن، جمع، نوشتن — سه قدم جدا!\n\nt1 = threading.Thread(target=add)\nt2 = threading.Thread(target=add)\nt1.start(); t2.start()\nt1.join(); t2.join()\nprint(counter)   # تقریباً هرگز 200000 نیست — دو Thread همزمان\n                 # وسطِ «خواندن-جمع-نوشتن» همدیگر را قطع می‌کنند"},{"k":"p","t":"راه‌حل‌ها سلسله‌مراتب دارند و حرفه‌ای‌ها از پایین به بالا می‌روند: اول، اصلاً حالت مشترک نساز (هر Thread داده خودش را داشته باشد و آخر جمع شود — مثل MapReduce)؛ دوم، داده‌های تغییرناپذیر بفرست (چیزی که عوض نمی‌شود، رقابت ندارد)؛ سوم، صفِ پیام بین Threadها (queue.Queue در پایتون خودش ایمن است)؛ و فقط در آخرین راه، قفل (Lock) دورِ ناحیه بحرانی. قفل درست کار می‌کند ولی گران است و اگر اشتباه بسته شود، بن‌بست می‌سازد. قاعده طلایی: اشتراک‌حافظه را به‌عنوان آخرین راه‌حل ببین، نه اولین."}]'::jsonb, '[{"q":"دو Thread داخل یک Process چه چیزی را به اشتراک دارند؟","opts":["هیچ‌چیز","فایل‌های باز، Heap و متغیرهای سراسری — ولی Stack جدا دارند","فقط Stack","فقط رجیسترها"],"ans":1,"why":"قدرت Threadها در اشتراک حافظه است (ارتباط ارزان) و خطرشان هم در همان است (Race Condition). Stack و رجیسترها برای هر Thread مستقل‌اند."},{"q":"فرمان fork در یونیکس چه می‌کند؟","opts":["یک Thread جدید می‌سازد","یک کپی از Process جاری می‌سازد؛ پدر و فرزند از همان خط ادامه می‌دهند","برنامه را می‌بندد","حافظه را آزاد می‌کند"],"ans":1,"why":"fork یک Process فرزند تقریباً همسان می‌سازد؛ تفاوت فقط در مقدار بازگشتی است (۰ برای فرزند، PID فرزند برای پدر). shellها این‌طوری فرمان‌ها را اجرا می‌کنند."}]'::jsonb),
('n-os-l2', 'os', 'همزمانی: از Race Condition تا Deadlock', 60, 3, '[{"k":"p","t":"وقتی دو Thread همزمان به یک داده مشترک می‌رسند و حداقل یکی می‌نویسد، نتیجه به زمان‌بندی وابسته می‌شود — این یعنی Race Condition. افزایش یک شمارنده حتی «یکی زیاد کن» نیست؛ سه عمل است: بخوان، جمع کن، بنویس — و وسطش می‌تواند پرش رخ بدهد."},{"k":"code","lang":"py","title":"race_vs_lock.py","code":"import threading\n\ncounter = 0\n\ndef buggy_inc():\n    global counter\n    for _ in range(100_000):\n        counter += 1        # خواندن + جمع + نوشتن => Race!\n\ncounter = 0\nthreads = [threading.Thread(target=buggy_inc) for _ in range(4)]\n[t.start() for t in threads]\n[t.join() for t in threads]\nprint(counter)              # تقریباً هیچ‌وقت 400000 نیست!\n\n# راه‌حل: Lock — فقط یک نفر در بحران\nlock = threading.Lock()\ncounter = 0\n\ndef safe_inc():\n    global counter\n    for _ in range(100_000):\n        with lock:          # ناحیه بحرانی کوچک\n            counter += 1\n\nthreads = [threading.Thread(target=safe_inc) for _ in range(4)]\n[t.start() for t in threads]\n[t.join() for t in threads]\nprint(counter)              # همیشه 400000"},{"k":"visual","visual":"deadlock","title":"شبیه‌ساز: بن‌بست"},{"k":"def","term":"Deadlock","t":"وقتی هر Thread منتظر منبعی است که Thread دیگر گرفته و هیچ‌کس کوتاه نمی‌آید: چهار شرط لازم است (انحصار متقابل، نگه‌داشتن و انتظار، عدم پیش‌گیری، انتظار دوطرفه). راه‌حل کلاسیک: همه Threadها Lockها را به یک ترتیب ثابت بگیرند."},{"k":"warn","title":"GIL نجاتت نمی‌دهد","t":"در پایتون GIL فقط اجرای همزمان بایت‌کد را محدود می‌کند؛ Race Conditionها سر جای خودشان‌اند چون پرش بین دستورها مجاز است. هیچ زبانی تو را از فکرکردن درباره همزمانی معاف نمی‌کند."},{"k":"tip","title":"بهترین Lock، Lock حذف‌شده است","t":"اول بپرس آیا اصلاً اشتراک لازم است؟ داده‌های تغییرناپذیر (Immutable) بین Threadها بفرست یا هر Thread نتیجه‌اش را برگرداند و یکی جمع بزند — Message Passing به‌جای حافظه مشترک، کل کلاس باگ را حذف می‌کند."}]'::jsonb, '[{"q":"Race Condition دقیقاً چه زمانی رخ می‌دهد؟","opts":["وقتی CPU داغ کند","دسترسی همزمان چند اجرا به داده مشترک که حداقل یکی می‌نویسد و ترتیب اثرگذار است","فقط در دیتابیس","وقتی حافظه پر شود"],"ans":1,"why":"سه عنصر لازم‌اند: اشتراک، هم‌زمانی و نوشتن. اگر همه فقط بخوانند، هیچ Race‌ای نیست — برای همین Immutability این‌قدر قوی است."},{"q":"کدام روش Deadlock را عملاً غیرممکن می‌کند؟","opts":["افزایش تعداد Threadها","گرفتن همه Lockها به یک ترتیب سراسری ثابت","استفاده از Lock بزرگ‌تر","ری‌استارت برنامه"],"ans":1,"why":"ترتیب ثابت، شرط «انتظار دوطرفه دایره‌ای» را می‌شکند: اگر همه اول A را بگیرند بعد B، هیچ دایره‌ای شکل نمی‌گیرد."}]'::jsonb),
('n-os-l3', 'os', 'حافظه مجازی: دروغ زیبای Paging', 55, 4, '[{"k":"p","t":"هر Process فکر می‌کند یک حافظه پیوسته و خصوصی از آدرس ۰ دارد — ولی واقعیت تکه‌تکه‌های ۴KB (Page) است که جدول صفحه آن‌ها را به آدرس فیزیکی ترجمه می‌کند. نتیجه: ایزولاسیون کامل Processها + امکان اجرای برنامه‌های بزرگ‌تر از RAM با Swap."},{"k":"code","lang":"bash","title":"terminal","code":"# وضعیت واقعی حافظه\n$ free -h\n               total    used    free   available\nMem:            15Gi   9.2Gi   1.1Gi      5.4Gi\nSwap:          4.0Gi   512Mi   3.5Gi\n\n# چه چیزی Swap شده؟ (ستون VmSwap)\n$ grep VmSwap /proc/2143/status\nVmSwap:     48236 kB\n\n# Page Faultها را زنده ببین\n$ vmstat 1\nprocs  memory             swap   io   system   cpu\n r  b  swpd   free      si   so    bi    bo   in   cs\n 1  0 512000 1123456    0    0    14    28  310  540"},{"k":"table","head":["مفهوم","معنی","اثر عملی"],"rows":[["Page Fault","صفحه در RAM نبود؛ از دیسک خوانده شد","هر بار چند میکروثانیه جریمه"],["TLB","کشِ ترجمه آدرس مجازی→فیزیکی","بدون آن هر دسترسی حافظه دو برابر هزینه داشت"],["Swap","صفحات کم‌مصرف روی دیسک","نجات از OOM، ولی هزار برابر کندتر از RAM"]]},{"k":"def","term":"Thrashing","t":"وقتی RAM واقعاً پر است و سیستم وقتش را به جای کار، به جابه‌جایی صفحات بین RAM و دیسک می‌گذرد: دیسک ۱۰۰٪، برنامه‌ها قفل. درمان: RAM بیشتر، Processهای کمتر، یا swapiness کمتر — نه صبر!"},{"k":"tip","title":"چرا malloc سریع است ولی RAM مصرفی واقعی نیست؟","t":"malloc فقط آدرس مجازی رزرو می‌کند؛ صفحات فیزیکی اولین لمس (Page Fault) تخصیص می‌یابند — Lazy Allocation. برای همین است که RSS با VSZ فرق دارد و malloc یک گیگ، فوراً یک گیگ RAM نمی‌خورد."},{"k":"h","t":"عمیق‌تر: Page Fault چه هزینه‌ای دارد و چرا مهم است"},{"k":"p","t":"حافظه مجازی جادوی بزرگی است: هر برنامه فکر می‌کند همه حافظه مال خودش است، در حالی که سیستم‌عامل صفحه‌ها را بین RAM و دیسک جابه‌جا می‌کند. وقتی برنامه به صفحه‌ای می‌رسد که الان در RAM نیست، «خطای صفحه» رخ می‌دهد: سیستم‌عامل اجرای برنامه را متوقف می‌کند، صفحه‌ای را از دیسک می‌خواند (و شاید یکی را بیرون کند) و بعد ادامه می‌دهد. هزینه‌اش عظیم است: خواندن از SSD حدود ده‌ها میکروثانیه و از هارد دیسک میلی‌ثانیه‌ها — در برابر دسترسی به RAM که چند نانوثانیه است. یعنی یک خطای صفحه می‌تواند هزار تا میلیون برابر کندتر از یک دسترسی عادی باشد."},{"k":"p","t":"اینجاست که الگوریتم‌های جایگزینی صفحه مثل LRU اهمیت پیدا می‌کنند: اگر سیستم‌عامل درست پیش‌بینی کند کدام صفحه به‌زودی لازم می‌شود، خطاها کم می‌مانند و برنامه حس می‌کند همه حافظه در RAM است. و این فقط بحث سیستم‌عامل نیست — هر کشی که می‌سازی (کش دیتابیس، کش مرورگر، کش برنامه‌ات) دقیقاً همین مسئله را دارد: وقتی جا نیست، چه چیزی را بیرون کنم؟ مفهوم Working Set هم از همین‌جا می‌آید: مجموعه صفحه‌هایی که برنامه «الان» واقعاً استفاده می‌کند؛ اگر RAM کمتر از Working Set باشد، برنامه مدام در حال خطای صفحه است و عملاً روی دیسک اجرا می‌شود — همان حالت معروف «Thrashing» که سیستم با وجود CPU تقریباً بیکار، به‌شدت کند است."},{"k":"tip","title":"نکته منتور","t":"وقتی سرورت «بدون دلیل» کند است، قبل از شک‌کردن به کد، vmstat و ستون si/so (swap in/out) را ببین. اگرswap فعال است، یعنی Working Set از RAM بزرگ‌تر شده و سیستم دارد روی دیسک نفس می‌کشد — و هیچ بهینه‌سازی کدی این را نجات نمی‌دهد؛ یا RAM بیشتر، یا مصرف حافظه کمتر."}]'::jsonb, '[{"q":"Page Fault یعنی چه؟","opts":["RAM خراب شده","CPU به صفحه‌ای رسید که در RAM نیست و باید از دیسک آورده شود","برنامه کرش کرده","TLB پر شده"],"ans":1,"why":"Page Fault خطا نیست؛ مکانیزم عادی حافظه مجازی است. فقط وقتی تعدادش زیاد شود (Thrashing) نشانه کمبود RAM است."},{"q":"چرا Swap سیستم را کند می‌کند؟","opts":["چون RAM را خالی می‌کند","چون دسترسی به دیسک هزاران برابر کندتر از RAM است و CPU معطل می‌ماند","چون CPU را اشغال می‌کند","کند نمی‌کند"],"ans":1,"why":"SSD خوب حدود ۱۰۰ میکروثانیه تأخیر دارد در برابر ۱۰۰ نانوثانیه RAM — سه مرتبه بزرگی. Swap برای نجات از کرش است، نه برای سرعت."}]'::jsonb),
('os-x1', 'os', 'زمان‌بندی پردازنده — عدالت در چند میلی‌ثانیه', 55, 5, '[{"k":"p","t":"سیستم تو همزمان موسیقی پخش می‌کند، مرورگر رندر می‌کند و بک‌گراند آپلود می‌کند — ولی CPU شاید ۴ هسته بیشتر نداشته باشد. جادوگر این نمایش، زمان‌بند (Scheduler) است که هر میلی‌ثانیه تصمیم می‌گیرد کدام Process بعدی اجرا شود. معیارش: هم عدالت، هم پاسخ‌گویی، هم توان کل."},{"k":"visual","visual":"queue","title":"صف آماده (Ready Queue) — صفِ صف‌ها"},{"k":"h","t":"سه سیاست کلاسیک"},{"k":"table","head":["سیاست","ایده","نقطه قوت","نقطه ضعف"],"rows":[["FCFS","اولویت با اول صف","ساده و عادلانه","اثر کاروان: یک کار طولانی همه را معطل می‌کند"],["Round Robin","هر فرایند سهم زمانی (Quantum) می‌گیرد و به ته صف می‌رود","پاسخ‌گویی عالی برای رابط کاربری","Quantum بد = سربار زیاد یا پاسخ کند"],["اولویت‌دار","هر فرایند اولویت دارد، بالاتر اول","کارهای مهم فوراً اجرا می‌شوند","گرسنگی: اولویت پایین هیچ‌وقت نوبتش نمی‌شود"]]},{"k":"p","t":"Round Robin قلب سیستم‌های تعاملی است: با Quantum حدود ۱۰ میلی‌ثانیه، چشم انسان «همزمانی» می‌بیند چون هر برنامه قبل از اینکه متوجه شوی نوبت گرفته. اگر Quantum خیلی کوچک شود، CPU بیشتر وقتش را صرف سوییچ بین فرایندها می‌کند تا خودشان؛ اگر خیلی بزرگ، دوباره اثر کاروان برمی‌گردد."},{"k":"code","lang":"py","title":"شبیه‌ساز Round Robin","code":"def round_robin(jobs: list[dict], q: int) -> list[str]:\n    queue = [dict(j) for j in jobs]\n    timeline = []\n    while queue:\n        job = queue.pop(0)\n        run = min(q, job[''burst''])\n        job[''burst''] -= run\n        timeline.append(f\"{job[''name'']}:{run}ms\")\n        if job[''burst''] > 0:\n            queue.append(job)          # به ته صف برگرد\n    return timeline\n\njobs = [{''name'': ''A'', ''burst'': 7},\n        {''name'': ''B'', ''burst'': 2},\n        {''name'': ''C'', ''burst'': 4}]\nprint('' -> ''.join(round_robin(jobs, q=2)))\n# A:2 -> B:2 -> C:2 -> A:2 -> C:2 -> A:2 -> A:1"},{"k":"def","term":"Context Switch","t":"تعویض بافت یعنی ذخیره ثبات‌ها و وضعیت فرایند فعلی و بارگذاری فرایند بعدی. هزینه‌اش واقعی است (چند میکروثانیه + سردشدن کش)؛ هنر زمان‌بند، حداقل‌کردن تعداد آن‌ها بدون قربانی‌کردن پاسخ‌گویی است."},{"k":"tip","title":"نکته منتور","t":"زمان‌بند لینوکس (CFS) به‌جای صف ساده، از «زمان مجازی» استفاده می‌کند: هر فرایند یک درخت قرمز‌سیاه از زمان اجرا نگه می‌دارد و همیشه چپ‌ترین (کمترین زمان مجازی) اجرا می‌شود — عدالت ریاضیاتی واقعی."}]'::jsonb, '[{"q":"اثر کاروان (Convoy Effect) مشکل کدام سیاست است؟","opts":["Round Robin","FCFS — یک فرایند طولانی، همه کوتاه‌ها را پشت خود نگه می‌دارد","اولویت‌دار","هیچ‌کدام"],"ans":1,"why":"در FCFS ترتیب ورود مقدس است؛ اگر اولی ۱۰ ثانیه بخواهد، ده فرایند ۱۰۰ میلی‌ثانیه‌ای پشتش میانگین انتظار وحشتناکی پیدا می‌کنند."},{"q":"چرا Quantum خیلی کوچک در Round Robin بد است؟","opts":["فرایندها گرسنه می‌مانند","سربار Context Switch آن‌قدر زیاد می‌شود که CPU مشغول تعویض است نه اجرا","اولویت‌ها به‌هم می‌ریزد","حافظه پر می‌شود"],"ans":1,"why":"هر تعویض چند میکروثانیه هزینه دارد؛ با Quantum یک میلی‌ثانیه‌ای شاید ۱۰٪ CPU فقط صرف سوئیچ شود — کار مفید کم می‌شود."}]'::jsonb),
('os-b1', 'os', 'نقش سیستم‌عامل', 63, 6, '[{"k":"p","t":"سیستم‌عامل واسط بین سخت‌افزار و برنامه‌هاست؛ منابع (CPU، حافظه، دستگاه‌ها) را مدیریت و با فراخوانی سیستم، خدمات را به برنامه‌ها می‌دهد."},{"k":"h","t":"سیستم‌عامل؛ مدیر منابع و فروشنده دروغ‌های مفید"},{"k":"p","t":"سیستم‌عامل دو نقش همزمان دارد: «مدیر منابع» — زمان CPU، حافظه، دیسک و شبکه را بین برنامه‌های حریص تقسیم می‌کند تا هیچ‌کس همه‌چیز را نگیرد و سیستم قفل نشود؛ و «سرویس‌دهنده انتزاع» — سخت‌افزار پیچیده را پشت رابط‌های ساده پنهان می‌کند. اما تعریف عمیق‌ترش این است: سیستم‌عامل مجموعه‌ای از دروغ‌های مفید است! به هر برنامه می‌گوید «کل CPU مال توست» (مجازی‌سازی پردازنده با زمان‌بندی)، «کل حافظه مال توست» (حافظه مجازی با جدول صفحه) و «کل دیسک یک فایل‌سیستم منظم است» (درحالی‌که بلوک‌ها پخش‌اند). هر برنامه در حباب توهم خودش اجرا می‌شود — و این توهم‌هاست که همزمانی، امنیت و سادگی را ممکن می‌کنند."},{"k":"h","t":"Kernel، System Call و مرز اعتماد"},{"k":"p","t":"CPU دو حالت اجرا دارد: کاربر (User) و هسته (Kernel). کد برنامه‌ات در حالت کاربر است — حق ندارد مستقیم به دیسک، شبکه یا حافظه دیگران دست بزند. هر وقت چنین چیزی لازم دارد، باید از درِ رسمی وارد شود: System Call — مثل open() یا send() — که CPU را به حالت هسته می‌برد، هسته با حق کامل کار را انجام می‌دهد و برمی‌گردد. این مرز، ستون امنیت است: باگی در مرورگرت نباید بتواند کل سیستم را خراب کند چون مرورگر اصلاً به آن بخش‌ها دسترسی ندارد. و هزینه‌اش واقعی است: هر system call یک تعویض حالت است (چند صد نانوثانیه) — به همین دلیل سیستم‌های پربازده، عمل‌ها را دسته می‌کنند و I/O را غیرهمگام می‌کنند تا تعداد عبور از مرز کم شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"دیدن انتزاع‌ها از نزدیک","code":"import os, psutil\n\n# هر process در حباب خودش است:\nprint(os.getpid())            # PID من\nprint(os.getppid())           # PID پدرم (شلم یا ترمینال)\n\n# سیستم‌عامل چه چیزی را به من «دروغ» می‌گوید؟\nprint(psutil.virtual_memory())   # حافظه «کل» از دید من\nprint(psutil.cpu_percent())      # CPU چند درصد مشغول است\n\n# strace در لینوکس، system callها را لو می‌دهد:\n# strace -c python3 script.py\n# → می‌بینی هر خط پایتون، ده‌ها read/write/mmap است"},{"k":"def","term":"System Call (فراخوانی سیستم)","t":"درِ رسمی عبور برنامه از حالت کاربر به حالت هسته برای درخواست خدمت (فایل، شبکه، حافظه). هر system call یک تعویض حالت با هزینه واقعی است — و به همین دلیل بهینه‌سازی‌های I/O مدرن (io_uring، epoll) همه درباره کم‌کردن همین عبورهاست."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["فراخوانی سیستم درگاه برنامه به هسته است","حالت کاربر و هسته، دسترسی‌ها را جدا می‌کند","مدیریت پردازش، حافظه، فایل و دستگاه چهار وظیفه اصلی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"c","title":"syscall.c","code":"// read یک فراخوانی سیستم است\n#include <unistd.h>\nchar buf[100];\nssize_t n = read(0, buf, 100);\n// برنامه از حالت کاربر به هسته می‌رود و برمی‌گردد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: فراخوانی سیستم درگاه برنامه به هسته است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا برنامه‌ها نمی‌توانند مستقیم به سخت‌افزار دست بزنند؟","opts":["کند","چون در حالت کاربرند و فقط هسته اجازه دارد؛ این جداسازی امنیت و پایداری می‌سازد","ممکن نیست","اجباری"],"ans":1,"why":"اگر هر برنامه مستقیم سخت‌افزار را می‌گرفت، یک برنامه می‌توانست کل سیستم را خراب کند؛ هسته واسط امن است."},{"q":"چرا برنامه‌ها نمی‌توانند مستقیم به دیسک بنویسند؟","opts":["کند می‌شود","چون در حالت کاربر اجرا می‌شوند و دسترسی سخت‌افزاری فقط در حالت هسته است — این جداسازی، امنیت و پایداری کل سیستم را می‌سازد","دیتا خراب می‌شود","ممکن نیست و تمام"],"ans":1,"why":"اگر هر برنامه مستقیم به سخت‌افزار می‌رسید، یک باگ ساده می‌توانست فایل‌های سیستم را پاک کند. مرز کاربر/هسته یعنی حق دسترسی، فقط با اجازه و نظارت هسته."},{"q":"«حافظه مجازی» چه توهمی می‌سازد؟","opts":["حافظه بیشتر از RAM","هر process فکر می‌کند کل فضای آدرس پیوسته مال خودش است — هسته با جدول صفحه آن را به RAM/دیسک واقعی ترجمه می‌کند","حافظه سریع‌تر","کش"],"ans":1,"why":"این توهم سه هدیه دارد: ایزولگی (هرکس فضای خودش را می‌بیند)، پیوستگی ظاهری (بدون نگرانی از پراکندگی) و بیشتر‌از‌RAM بودن (با swap) — همه با یک جدول ترجمه."}]'::jsonb),
('os-b2', 'os', 'Process و فضای آدرس', 63, 7, '[{"k":"p","t":"Process نمونه‌ای در حال اجرای برنامه با فضای آدرس مستقل است؛ کد، داده، heap و stack هر process جداست و خرابی یکی بقیه را نمی‌گیرد."},{"k":"h","t":"Process؛ واحد ایزولگی و صاحب منابع"},{"k":"p","t":"Process یعنی «برنامه در حال اجرا» — نه خود فایل اجرایی. هر process سه چیز دارد: فضای آدرس خصوصی (کد، داده‌ها، stack و heap که هیچ process دیگری نمی‌بیند)، توصیف‌گرهای منابع (فایل‌های باز، اتصالات شبکه) و یک شناسه (PID). وقتی مرورگرت کرش می‌کند و فقط یک تب می‌رود، دلیلش همین ایزولگی است: هر تب process خودش را دارد و مرگ یکی، بقیه را نمی‌برد. این امنیت هم می‌آورد: process بدافزار نمی‌تواند حافظه بانک را بخواند چون اصلاً در فضای آدرسش نیست. بهای ایزولگی، گرانی است: ساخت process و تعویض بینشان چند میکروثانیه و حافظه قابل‌توجه می‌خواهد — برای همین threadها و containerها به‌عنوان راه‌حل‌های سبک‌تر متولد شدند."},{"k":"h","t":"زندان‌های تو در تو؛ از process تا container"},{"k":"p","t":"حالا می‌فهمی Docker از کجا آمده: container یک process است که هسته دورش «حصار» بیشتری کشیده — Namespaceها می‌گویند «فایل‌سیستم، شبکه و processهای خودت را می‌بینی نه بقیه را» و cgroupها می‌گویند «از CPU و حافظه فقط این‌قدر». پس container ماشین مجازی نیست (هسته مشترک است) بلکه همان ایزولگی process که کامل‌تر شده. و داخل هر process مدرن، ایزولگی کوچک‌تری هم هست: threadها. همه threadهای یک process فضای آدرس را مشترک‌اند (پس ارتباطشان ارزان است) ولی هرکدام stack و شمارنده برنامه خودش را دارد (پس مستقل اجرا می‌شوند). طیف را ببین: process (ایزوله، گران) ← thread (مشترک، سبک‌تر) ← coroutine (سبک‌ترین، داوطلبانه). انتخاب بین این سه، یکی از مهم‌ترین تصمیم‌های هر سیستم هم‌روند است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"آناتومی یک process در لینوکس","code":"ps aux | head              # همه processها با CPU/حافظه\npstree -p                  # درخت پدر-فرزندی با PID\n\n# هر process یک پوشه در /proc دارد — پنجره‌اش به هسته:\ncat /proc/$(pgrep -n python3)/status | head\n# → Name، State، VmRSS (حافظه واقعی)، Threads\n\n# درخت حافظه یک process:\ncat /proc/$$/maps | head\n# → هر تکه: کد، heap، stack، کتابخانه‌ها"},{"k":"def","term":"فضای آدرس (Address Space)","t":"کل بازه آدرس‌هایی که یک process می‌تواند ببیند — تقسیم‌شده به بخش‌های کد (فقط‌خواندنی)، داده‌های سراسری، heap (تخصیص پویا، رو به بالا) و stack (فراخوانی‌ها، رو به پایین). هسته با صفحه‌بندی، این فضا را به حافظه فیزیکی ترجمه و از دید processهای دیگر پنهانش می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر process فضای آدرس مجازی خودش را دارد","fork یک کپی از process می‌سازد؛ exec برنامه جدید جایگزین می‌کند","PID شناسه و process والد-فرزندی دارند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"c","title":"fork.c","code":"pid_t pid = fork();\nif (pid == 0) {\n    // فرزند\n    printf(\"من فرزندم\\n\");\n} else {\n    // والد\n    printf(\"فرزندم %d است\\n\", pid);\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر process فضای آدرس مجازی خودش را دارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"بعد از fork، چند process اجرا می‌شود؟","opts":["یکی","دو — والد و فرزند که هر دو از همان نقطه ادامه می‌دهند","سه","هیچ"],"ans":1,"why":"fork یک کپی کامل می‌سازد؛ کد یک‌بار اجرا ولی در دو process، و خروجی fork در هرکدام متفاوت است."},{"q":"چرا کرش یک تب کروم، کل مرورگر را نمی‌بندد؟","opts":["شانس","چون هر تب process جدا با فضای آدرس خصوصی است؛ مرگ یک process، حافظه بقیه را لمس نمی‌کند","کش دارد","چند نخ دارد"],"ans":1,"why":"ایزولگی process یعنی فاجعه «محصور» می‌شود. بهایش مصرف بیشتر RAM است — معامله‌ای که کروم عمداً قبول کرده."},{"q":"تفاوت اصلی container و ماشین مجازی چیست؟","opts":["سرعت","container هسته میزبان را مشترک است و فقط namespace و cgroup اضافه می‌کند؛ VM کل سیستم‌عامل مهمان را با Hypervisor شبیه می‌سازد","امنیت","اندازه"],"ans":1,"why":"VM یک هسته کامل اضافه دارد (گیگابایت‌ها و دقیقه‌ها)؛ container فقط حصارهای هسته روی یک process عادی (مگابایت‌ها و میلی‌ثانیه‌ها) — همان ایزولگی، بسیار سبک‌تر."}]'::jsonb),
('os-b3', 'os', 'Thread و تفاوت با Process', 63, 8, '[{"k":"p","t":"Thread واحد اجرای سبک داخل یک process است؛ threadهای یک process حافظه را به اشتراک دارند ولی processها فضای آدرس جدا — پس thread ارزان‌تر ولی پرخطرتر است."},{"k":"h","t":"Thread؛ اشتراک با سرعت، و با خطر"},{"k":"p","t":"threadهای یک process همه‌چیز را مشترک‌اند — heap، فایل‌های باز، متغیرهای سراسری — به‌جز دو چیز: stack (متغیرهای محلی و فراخوانی‌های خودش) و برنامه‌اشاره‌گر (جایی که الان اجرا می‌شود). این اشتراک یعنی ارتباط بین threadها تقریباً رایگان است (یک متغیر مشترک کافی است) — برعکس processها که pipe و socket لازم دارند. ولی همان اشتراک، ریشه همه دردهاست: وقتی دو thread همزمان یک داده مشترک را بخوانند و بنویسند، نتیجه به زمان‌بندی وابسته می‌شود — race condition. هیچ کامپایلری این را نمی‌گیرد و گاهی فقط در production و زیر بار ظاهر می‌شود. پس ذهنیت thread این است: «اشتراک یعنی سرعت، ولی هر داده مشترک یک قرارداد همگام‌سازی می‌خواهد»."},{"k":"h","t":"چندمغزی واقعی در برابر همزمانی ظاهری"},{"k":"p","t":"دو مفهوم که همیشه قاطی می‌شوند: concurrency یعنی «چند کار در حال پیشرفت» (حتی با یک هسته، با تعویض سریع) و parallelism یعنی «چند کار در حال اجرای همزمان فیزیکی» (چند هسته). Python با GIL فقط به اولی می‌رسد برای کد CPU-bound — یک قفل سراسری که اجازه نمی‌دهد دو thread پایتونی همزمان کد اجرا کنند؛ پس برای پردازش سنگین باید multiprocessing (چند process) یا C-extensions استفاده کنی. ولی برای I/O-bound (وب، فایل، دیتابیس) حتی Python با thread عالی است چون نخِ منتظر، قفل را رها می‌کند. این تشخیص — CPU-bound در برابر I/O-bound — قبل از هر انتخاب معماری همگام‌سازی، اولین سوالی است که باید جواب بدهی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"Race condition و درمانش با قفل","code":"import threading\n\ncounter = 0\nlock = threading.Lock()\n\ndef broken():          # ❌ بدون قفل\n    global counter\n    for _ in range(100_000):\n        counter += 1   # خواندن، جمع، نوشتن — ۳ عمل جدا!\n\ndef safe():            # ✓ با قفل\n    global counter\n    for _ in range(100_000):\n        with lock:\n            counter += 1\n\nts = [threading.Thread(target=safe) for _ in range(4)]\n[t.start() for t in ts]; [t.join() for t in ts]\nprint(counter)   # 400000 — با broken() کمتر می‌شد"},{"k":"def","term":"Race Condition (شرایط مسابقه)","t":"وقتی نتیجه نهایی به ترتیبِ زمان‌بندی‌نشده‌ی عمل‌های چند thread وابسته می‌شود. ریشه‌اش: عملی که چند مرحله دارد (خواندن-تغییر-نوشتن) و thread دیگری می‌تواند وسطش بپرد. درمان: قفل، عمل اتمیک، یا حذف اشتراک — به همین ترتیب اولویت."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["threadها stack جدا ولی heap و داده مشترک دارند","ساخت و تعویض thread از process بسیار ارزان‌تر است","اشتراک حافظه یعنی نیاز به هماهنگی (lock)"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"c","title":"thread.c","code":"#include <pthread.h>\nvoid* work(void* arg) {\n    printf(\"سلام از thread\\n\");\n    return NULL;\n}\npthread_t t;\npthread_create(&t, NULL, work, NULL);\npthread_join(t, NULL);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: threadها stack جدا ولی heap و داده مشترک دارند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا threadها باید با lock هماهنگ شوند؟","opts":["کندند","چون حافظه مشترک دارند و دسترسی همزمان می‌تواند داده را خراب کند","اجباری","برای سرعت"],"ans":1,"why":"دو thread اگر همزمان یک متغیر مشترک را بخوانند/بنویسند، نتیجه غیرقابل‌پیش‌بینی می‌شود؛ lock نوبت‌دهی می‌کند."},{"q":"چرا counter += 1 با وجود سادگی‌اش، race condition دارد؟","opts":["ندارد","چون سه عمل جداست — خواندن مقدار، جمع، نوشتن — و thread دیگر می‌تواند بین این سه بپرد و نوشتنش، نوشتن قبلی را پاک کند","چون پایتون کند است","GIL مشکل است"],"ans":1,"why":"دو thread هم مقدار ۵ را می‌خوانند، هر دو ۶ حساب و می‌نویسند — یک افزایش گم شد. به این عملِ چندمرحله‌ای غیرقابل‌تقسیم می‌گویند و قفل آن را اتمیک می‌کند."},{"q":"برای دانلود همزمان ۱۰۰ فایل در پایتون، thread یا process؟","opts":["process","thread — چون I/O-bound است و GIL هنگام انتظار شبکه رها می‌شود؛ process سربار بی‌مورد دارد","فرقی ندارد","هیچ‌کدام"],"ans":1,"why":"در I/O، نخ بیشترِ وقتش منتظر است و قفل سراسری را نگه نمی‌دارد — پس GIL مانع نیست. multiprocessing برای جایی است که CPU واقعاً همزمان بخواهد."}]'::jsonb),
('os-b4', 'os', 'زمان‌بندی CPU', 63, 9, '[{"k":"p","t":"زمان‌بند تصمیم می‌گیرد کدام thread بعدی اجرا شود؛ Round Robin با سهم زمانی و اولویت‌دار با درجه اهمیت، تعادل عدالت و پاسخ‌گویی را می‌سازند."},{"k":"h","t":"توهم همزمانی؛ هنرِ تقسیم میلی‌ثانیه‌ها"},{"k":"p","t":"روی لپ‌تاپت شاید ۸ هسته باشد ولی همزمان ده‌ها برنامه «در حال اجرا» می‌بینی — چون سیستم‌عامل هر میلی‌ثانیه چند بار تصمیم می‌گیرد کدام process روی هر هسته بنشیند و Context Switch را انجام می‌دهد: ذخیره ثبات‌ها و وضعیت فعلی، بارگذاری بعدی. چشم انسان این را «همزمانی» می‌بیند. این تصمیم‌گیرنده، زمان‌بند (Scheduler) است و سه معیار متضاد را باید بالانس کند: throughput (کار کل سیستم)، latency (هر process چقدر منتظر ماند) و fairness (هیچ‌کس گرسنه نماند). هر سیستم‌عامل نقطه بالانس خودش را دارد — لینوکس دسکتاپ پاسخ‌گویی را ترجیح می‌دهد تا موس گیر نکند؛ سرورهای batch، throughput را."},{"k":"h","t":"Round Robin و Quantum؛ چرا ۱۰ میلی‌ثانیه"},{"k":"p","t":"ساده‌ترین سیاست منصفانه: صف دایره‌ای و سهم زمانی ثابت (Quantum). هر process سهمش را می‌گیرد و به ته صف می‌رود — پس هیچ‌کس بیش از یک صفِ Quantum معطل نمی‌ماند. حالا عدد Quantum خودِ مهندسی است: خیلی کوچک (مثل ۱ms) یعنی Context Switchهای مکرر — هرکدام چند میکروثانیه هزینه و سرد شدن کش — و CPU به‌جای کار، مشغول تعویض می‌شود. خیلی بزرگ (مثل ۱s) یعنی کلیک موس باید تا پایان Quantum صبر کند و سیستم «خشک» می‌شود. منطقه طلایی معمولاً ۱ تا ۱۰ میلی‌ثانیه است — جایی که سربار زیر ۱٪ می‌ماند و پاسخ‌گویی زیر آستانه ادراک انسان. زمان‌بند لینوکس (CFS) از این هم فراتر رفته و به‌جای Quantum ثابت، «زمان مجازی» را مساوی می‌کند تا حتی بارهای کوتاه هم منصفانه نوبت بگیرند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"شبیه‌ساز Round Robin در ۱۵ خط","code":"def round_robin(jobs, quantum):\n    queue = [dict(j) for j in jobs]   # کپی: نام + burst\n    timeline, wait = [], {}\n    t = 0\n    while queue:\n        job = queue.pop(0)\n        run = min(quantum, job[''burst''])\n        timeline.append(f\"{job[''name'']}×{run}\")\n        t += run\n        job[''burst''] -= run\n        if job[''burst''] > 0:\n            queue.append(job)\n    return '' → ''.join(timeline)\n\nprint(round_robin([{''name'': ''A'', ''burst'': 7},\n                   {''name'': ''B'', ''burst'': 2},\n                   {''name'': ''C'', ''burst'': 4}], quantum=2))\n# A×2 → B×2 → C×2 → A×2 → C×2 → A×2 → A×1"},{"k":"def","term":"Context Switch (تعویض بافت)","t":"فرایند ذخیره وضعیت کامل یک thread (ثبات‌ها، شمارنده برنامه، جدول صفحه) و بارگذاری بعدی. هزینه‌اش فقط CPU نیست — کش‌های L1/L2 هم سرد می‌شوند و thread بعدی باید دوباره داده‌هایش را از RAM بیاورد؛ پس زمان‌بندِ خوب، تعداد تعویض‌ها را هم مدیریت می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Context Switch ذخیره و بازیابی وضعیت thread است","Quantum بزرگ = پاسخ کند؛ کوچک = سربار زیاد","thread آماده در صف و در حال اجرا روی CPU است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"حالت‌های thread","code":"New → Ready → Running → Terminated\n              ↑    ↓\n           Blocked (منتظر I/O)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Context Switch ذخیره و بازیابی وضعیت thread است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Context Switch چیست؟","opts":["تعویض کابل","ذخیره وضعیت thread فعلی و بارگذاری وضعیت thread بعدی","خاموش‌کردن CPU","کپی حافظه"],"ans":1,"why":"CPU فقط یک thread اجرا می‌کند؛ برای تعویض باید وضعیت قبلی ثبت شود تا بعداً ادامه یابد."},{"q":"اثر کاروان (Convoy Effect) مشکل کدام سیاست است؟","opts":["Round Robin","FCFS — یک job طولانی اول صف، همه کوتاه‌ها را پشت خود نگه می‌دارد و میانگین انتظار را خراب می‌کند","اولویت‌دار","هیچ‌کدام"],"ans":1,"why":"در FCFS ترتیب ورود مقدس است؛ یک job ده‌ثانیه‌ای، ده job صد میلی‌ثانیه‌ای را معطل می‌کند. Quantum داشتن (Round Robin) دقیقاً همین را درمان می‌کند."},{"q":"اگر Quantum را از ۴ms به ۲۰۰ms ببریم چه می‌شود؟","opts":["همه‌چیز بهتر","سربار تعویض کم می‌شود ولی پاسخ‌گویی افت می‌کند — کلیک‌ها و رویدادها تا پایان سهم ۲۰۰ میلی‌ثانیه‌ای منتظر می‌مانند","فرقی ندارد","کرش می‌کند"],"ans":1,"why":"Quantum بزرگ یعنی تعویض کمتر (خوب برای throughput) ولی تأخیر بیشتر برای هر رویداد تازه (بد برای کاربر). بالانس این دو، خودِ هنر زمان‌بندی است."}]'::jsonb),
('os-b5', 'os', 'Race Condition', 56, 10, '[{"k":"p","t":"Race Condition وقتی نتیجه به ترتیب اجرای threadها وابسته می‌شود؛ عملیات خواندن-تغییر-نوشتن اگر اتمی نباشد، با اجرای موازی گم‌شدن به‌روزرسانی می‌دهد."},{"k":"h","t":"Race Condition؛ نتیجه به «ترتیب» وابسته می‌شود"},{"k":"p","t":"وقتی چند thread به یک داده مشترک دسترسی دارند و حداقل یکی می‌نویسد، نتیجه می‌تواند به ترتیبِ تصادفیِ اجرا وابسته شود — این Race Condition است. ریشه‌اش این است که عملیات‌هایی که در کد یک خط به‌نظر می‌رسند، در واقع چند مرحله‌اند: خواندنِ مقدار فعلی، تغییر، و نوشتنِ نتیجه. اگر دو thread بین این مراحل درهم بروند، یکی از به‌روزرسانی‌ها گم می‌شود — به این «گم‌شدن به‌روزرسانی» (lost update) می‌گویند."},{"k":"h","t":"چرا ++counter اتمی نیست"},{"k":"p","t":"شاید فکر کنی counter++ یک عمل ساده است، ولی در سطح سخت‌افزار سه عمل است: بخوان، جمع کن، بنویس — و وسطش می‌تواند پرش رخ بدهد. دو thread می‌توانند هر دو مقدار ۵ را بخوانند، هر دو به ۶ برسند، و هر دو ۶ را بنویسند؛ پس یکی از افزایش‌ها گم می‌شود. راه‌حل، اتمی‌کردنِ این بخش بحرانی است: یا با قفل (mutex) یا با عملیات اتمی سخت‌افزاری که وسطش نوبت را نمی‌دهد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["شرط لازم برای race","توضیح"],"rows":[["داده مشترک","حداقل یک داده بین threadها مشترک باشد"],["حداقل یک نوشتن","اگر همه فقط بخوانند، race نیست"],["عدم همگام‌سازی","هیچ قفل یا عملیات اتمی محافظت نکند"]]},{"k":"warn","title":"دام رایج","t":"Race Condition موذی‌ترین نوع باگ است چون «همیشه» رخ نمی‌دهد؛ شاید هزاران بار درست اجرا شود و فقط گاهی خراب شود. اگر باگی داری که گهگاه و بی‌دلیل ظاهر می‌شود و با داده مشترک بین threadها سر و کار دارد، اولین متهم race condition است."},{"k":"tip","title":"نکته منتور","t":"بهترین راه اجتناب، اصلاً به اشتراک‌نگذاشتن است؛ اگر هر thread داده خودش را داشته باشد و فقط نتیجه نهایی ترکیب شود، race اصلاً وجود ندارد. وقتی مجبور به اشتراکی، آن را تا جای ممکن محدود و کوتاه نگه دار."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["بخش بحرانی کدی است که به داده مشترک دسترسی دارد","دو thread همزمان ++ را بخوانند و یکی بنویسند، یکی گم می‌شود","راه‌حل: mutex یا عملیات اتمی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"c","title":"race.c","code":"int counter = 0;\n// thread 1: counter++\n// thread 2: counter++\n// ممکن است counter == 1 شود نه 2!\n// چون هر دو ۰ خواندند، ۱ نوشتند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: بخش بحرانی کدی است که به داده مشترک دسترسی دارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا ++counter در دو thread می‌تواند یکی گم شود؟","opts":["باگ کامپایلر","چون خواندن، افزایش و نوشتن سه عمل جداست و threadها می‌توانند وسط آن پرش کنند","ممکن نیست","CPU کند"],"ans":1,"why":"++ اتمی نیست؛ اگر دو thread همزمان مقدار قدیمی را بخوانند، هر دو همان را می‌نویسند و یکی از افزایش‌ها گم می‌شود."},{"q":"چرا counter++ در محیط چندریسمانی اتمی نیست؟","opts":["چون کند است","چون سه مرحله دارد (خواندن، جمع، نوشتن) و threadها می‌توانند وسطش درهم بروند و یک به‌روزرسانی گم شود","چون حافظه می‌گیرد","چون زبان اجازه نمی‌دهد"],"ans":1,"why":"دو thread می‌توانند هر دو مقدار قدیمی را بخوانند و هر دو نتیجه یکسان بنویسند؛ پس یکی از افزایش‌ها گم می‌شود. اتمی‌کردن یعنی این سه مرحله بدون وقفه انجام شوند."},{"q":"بهترین راه کلی برای اجتناب از Race Condition چیست؟","opts":["افزایش تعداد thread","به اشتراک‌نگذاشتن داده بین threadها تا حد ممکن و محدودکردنِ بخش مشترک","استفاده از حافظه بیشتر","کاهش سرعت CPU"],"ans":1,"why":"اگر داده مشترک نباشد، race وجود ندارد؛ پس اولویت با طراحی‌ای است که هر thread داده خودش را دارد و فقط نتیجه ترکیب می‌شود."}]'::jsonb),
('os-b6', 'os', 'Mutex و Lock', 56, 11, '[{"k":"p","t":"Mutex قفلی است که فقط یک thread همزمان می‌تواند نگه دارد؛ قبل از بخش بحرانی lock و بعد unlock — و فراموشی unlock یعنی بن‌بست برای همه."},{"k":"h","t":"Mutex؛ قفلی که نوبت می‌دهد"},{"k":"p","t":"Mutex (مخفف Mutual Exclusion) قفلی است که در هر لحظه فقط یک thread می‌تواند نگهش دارد. قبل از ورود به بخش بحرانی (آن قسمت کد که به داده مشترک می‌رسد)، thread باید قفل را بگیرد (lock) و بعد از کارش آزاد کند (unlock). بقیه threadهایی که می‌خواهند وارد شوند، پشت قفل منتظر می‌مانند. این‌طوری بخش بحرانی همیشه فقط یک اجراکننده دارد و race از بین می‌رود."},{"k":"h","t":"قفل را کوچک نگه دار؛ و هرگز فراموش نکن"},{"k":"p","t":"قفل هزینه دارد — هر threadی که پشتش می‌ماند معطل می‌شود؛ پس بخش بحرانی باید تا جای ممکن کوتاه باشد و فقط همان خطوطی را بگیرد که واقعاً به داده مشترک می‌رسند، نه کل تابع را. مهم‌تر: هر lock باید دقیقاً یک unlock داشته باشد، حتی اگر وسطش خطا بیفتد. فراموش‌کردن unlock یعنی بقیه threadها برای همیشه پشت قفل می‌مانند — عملاً یک بن‌بست. برای همین در زبان‌های مدرن از ساختارهایی استفاده می‌شود که unlock را خودکار انجام می‌دهند (مثل with در پایتون یا lock_guard در ++C)."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ساختار","زبان","unlock خودکار"],"rows":[["with threading.Lock()","پایتون","بله، در خروج از بلاک"],["lock_guard / unique_lock","++C","بله، با تخریب شیء (RAII)"],["synchronized / try-with","جاوا","بله، در خروج از بلاک"],["defer mu.Unlock()","Go","بله، با defer"]]},{"k":"warn","title":"دام رایج","t":"قفل را دورِ عملیات کند (مثل I/O یا شبکه) نینداز؛ اگر یک thread داخل بخش بحرانی منتظر شبکه بماند، همه بقیه هم پشت قفل معطل می‌شوند و همزمانی عملاً از بین می‌رود. فقط اطرافِ دسترسی به داده مشترک قفل بگذار."},{"k":"tip","title":"نکته منتور","t":"ترتیب ثابت گرفتن قفل‌ها را در کل برنامه رعایت کن؛ اگر همه threadها قفل‌ها را همیشه به یک ترتیب بگیرند، یکی از شرایط اصلی بن‌بست از بین می‌رود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["lock/unlock همیشه جفت و حتی در خطا","std::lock_guard در C++ با RAII خودکار unlock می‌کند","قفل زیاد و درشت، موازی‌سازی را از بین می‌برد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"cpp","title":"mutex.cpp","code":"#include <mutex>\nstd::mutex mtx;\nint counter = 0;\nvoid safe_inc() {\n    std::lock_guard<std::mutex> lock(mtx);\n    counter++;   // بخش بحرانی محافظت‌شده\n}   // unlock خودکار با RAII"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: lock/unlock همیشه جفت و حتی در خطا بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت lock_guard بر lock دستی چیست؟","opts":["سریع‌تر","با RAII حتی در استثنا قفل آزاد می‌شود و deadlockِ فراموشی حذف می‌شود","کوتاه‌تر همیشه","اجباری"],"ans":1,"why":"اگر وسط بخش بحرانی استثنا پرتاب شود، unlock دستی اجرا نمی‌شود ولی مخرب lock_guard همیشه قفل را آزاد می‌کند."},{"q":"چرا بخش بحرانی باید تا جای ممکن کوتاه باشد؟","opts":["برای زیبایی کد","چون هر thread پشت قفل معطل می‌شود؛ قفلِ طولانی همزمانی را عملاً از بین می‌برد","چون حافظه کم می‌آید","چون کامپایلر خطا می‌دهد"],"ans":1,"why":"قفل یعنی بقیه منتظرند؛ پس هرچه دیرتر آزاد شود، بقیه بیشتر معطل می‌شوند. باید فقط خطوطِ دسترسی به داده مشترک داخل قفل باشند، نه عملیات کند مثل I/O."},{"q":"اگر unlock فراموش شود چه اتفاقی می‌افتد؟","opts":["سرعت زیاد می‌شود","بقیه threadها برای همیشه پشت قفل می‌مانند و عملاً سیستم قفل می‌شود","داده پاک می‌شود","چیزی نمی‌شود"],"ans":1,"why":"Mutex آزادنشده یعنی هیچ thread دیگری نمی‌تواند وارد بخش بحرانی شود؛ همه منتظر می‌مانند و پیشرفت متوقف می‌شود. به همین دلیل از ساختارهای unlock خودکار استفاده می‌کنند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('os-b7', 'os', 'Deadlock و شرایط آن', 56, 12, '[{"k":"p","t":"Deadlock وقتی چند thread هرکدام قفلی را نگه داشته و منتظر قفل دیگری‌اند و هیچ‌کس جلو نمی‌رود؛ چهار شرط لازم دارد و با حذف هرکدام شکسته می‌شود."},{"k":"h","t":"Deadlock؛ همه منتظر، هیچ‌کس جلو نمی‌رود"},{"k":"p","t":"بن‌بست وقتی رخ می‌دهد که چند thread هرکدام قفلی را نگه داشته و منتظر قفلی است که دیگری نگه داشته — یک چرخه انتظار که هیچ‌کس نمی‌تواند از آن خارج شود. کلاسیک‌ترین مثال: thread اول قفل A را دارد و B را می‌خواهد، thread دوم قفل B را دارد و A را؛ هر دو برای همیشه منتظر می‌مانند. بن‌بست چهار شرط لازم دارد که اگر حتی یکی را حذف کنی، شکسته می‌شود."},{"k":"h","t":"چهار شرط و راه شکستن هرکدام"},{"k":"p","t":"چهار شرط بن‌بست: (۱) انحصار متقابل — منبع قابل‌اشتراک نیست؛ (۲) نگهداری و انتظار — thread قفلی را نگه داشته و دنبال دیگری است؛ (۳) بدون پیش‌خرابکاری — قفل را نمی‌توان به زور گرفت؛ (۴) انتظار چرخه‌ای — زنجیره‌ای از انتظارها حلقه می‌سازد. عملی‌ترین راه شکستن، ازبین‌بردن انتظار چرخه‌ای است: همه threadها قفل‌ها را با یک ترتیب جهانی ثابت بگیرند تا حلقه‌ای شکل نگیرد. راه دیگر، تلاش برای گرفتن قفل با timeout و رهاکردن همه و شروع دوباره است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["شرط","چطور شکسته می‌شود"],"rows":[["انحصار متقابل","استفاده از منابع قابل‌اشتراک یا ساختارهای lock-free"],["نگهداری و انتظار","گرفتن همه قفل‌های لازم به‌صورت یکجا"],["بدون پیش‌خرابکاری","گرفتن قفل با timeout و رهاکردن در صورت شکست"],["انتظار چرخه‌ای","ترتیب جهانی ثابت برای گرفتن قفل‌ها"]]},{"k":"warn","title":"دام رایج","t":"بن‌بست هم مثل race condition «همیشه» نیست؛ فقط وقتی رخ می‌دهد که دو thread دقیقاً در لحظه بدی به قفل‌ها برسند. پس کدی که «معمولاً کار می‌کند» هم می‌تواند بن‌بست داشته باشد و در بدترین زمان — زیر بار بالا — ظاهر شود."},{"k":"tip","title":"نکته منتور","t":"اگر برنامه‌ات ناگهان بی‌دلیل «یخ» کرد و هیچ خطایی نداد، به بن‌بست شک کن. با گرفتن stack trace همه threadها می‌توانی ببینی هرکدام پشت کدام قفل منتظر است و حلقه را پیدا کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["چهار شرط: انحصار، نگه‌داشتن و انتظار، عدم پیش‌گرفتن، دوره انتظار","راه‌حل: همه threadها قفل‌ها را به یک ترتیب بگیرند","تشخیص با timeout و try_lock"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"بن‌بست کلاسیک","code":"Thread A: lock(L1) → lock(L2)\nThread B: lock(L2) → lock(L1)\n→ هر دو منتظر هم، برای همیشه!\nراه: هر دو اول L1 بعد L2"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: چهار شرط: انحصار، نگه‌داشتن و انتظار، عدم پیش‌گرفتن، دوره انتظار بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"ساده‌ترین راه جلوگیری از Deadlock چیست؟","opts":["حذف thread","همه threadها قفل‌ها را به یک ترتیب جهانی بگیرند تا دوره‌ای شکل نگیرد","افزایش CPU","timeout"],"ans":1,"why":"اگر همه اول L1 بعد L2 بگیرند، هیچ دوره‌ای شکل نمی‌گیرد؛ Deadlock نیاز به ترتیب متضاد دارد."},{"q":"کدام یک از چهار شرط بن‌بست نیست؟","opts":["انحصار متقابل","نگهداری و انتظار","ترتیب الفبایی نام threadها","انتظار چرخه‌ای"],"ans":2,"why":"نام threadها هیچ ربطی به بن‌بست ندارد؛ چهار شرط واقعی، انحصار متقابل، نگهداری و انتظار، بدون پیش‌خرابکاری و انتظار چرخه‌ای‌اند."},{"q":"عملی‌ترین راه جلوگیری از بن‌بست چیست؟","opts":["حذف همه قفل‌ها","گرفتن همه قفل‌ها با یک ترتیب جهانی ثابت، تا انتظار چرخه‌ای شکل نگیرد","افزایش حافظه","کاهش تعداد thread"],"ans":1,"why":"اگر همه threadها همیشه قفل‌ها را به یک ترتیب بگیرند، نمی‌تواند حلقه‌ای از انتظار شکل بگیرد؛ پس شرط چهارم بن‌بست از بین می‌رود."}]'::jsonb),
('os-b8', 'os', 'حافظه مجازی و Paging', 56, 13, '[{"k":"p","t":"حافظه مجازی به هر process این توهم را می‌دهد که کل حافظه مال اوست؛ MMU آدرس مجازی را با جدول صفحه به آدرس فیزیکی ترجمه می‌کند."},{"k":"h","t":"حافظه مجازی؛ توهمِ «کل حافظه مال من است»"},{"k":"p","t":"هر برنامه فکر می‌کند کل حافظه از آنِ خودش است و آدرس‌ها از صفر شروع می‌شوند — ولی این یک توهم مفید است که سیستم‌عامل می‌سازد. در واقعیت، حافظه فیزیکی بین برنامه‌ها تقسیم می‌شود و آدرس‌هایی که برنامه می‌بیند «مجازی»‌اند. سخت‌افزاری به نام MMU هر آدرس مجازی را با جدولی به آدرس فیزیکی واقعی ترجمه می‌کند. این کار سه فایده دارد: جداسازی (برنامه‌ها نمی‌توانند حافظه هم را بخوانند)، استفاده بهتر از حافظه، و امکان بزرگ‌تر بودن حافظه برنامه از رم واقعی."},{"k":"h","t":"Paging و صفحه‌ها"},{"k":"p","t":"ترجمه آدرس بر اساس صفحه (page) انجام می‌شود؛ حافظه به تکه‌های هم‌اندازه (معمولاً ۴ کیلوبایت) تقسیم می‌شود و جدول صفحه برای هر صفحه مجازی می‌گوید در کدام صفحه فیزیکی است. وقتی برنامه به صفحه‌ای می‌رسد که فعلاً در رم نیست (مثلاً به دیسک منتقل شده)، یک Page Fault رخ می‌دهد و سیستم‌عامل آن صفحه را از دیسک به رم می‌آورد و اجرا را ادامه می‌دهد. به این جابه‌جایی بین رم و دیسک، swapping می‌گویند؛ اگر زیاد شود سیستم به‌شدت کند می‌شود چون دیسک میلیون‌ها برابر کندتر از رم است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["مفهوم","چیست","اثر"],"rows":[["MMU","سخت‌افزار ترجمه آدرس مجازی به فیزیکی","جداسازی و امکان حافظه مجازی"],["صفحه (Page)","تکه هم‌اندازه حافظه (معمولاً ۴KB)","واحد ترجمه و جابه‌جایی"],["Page Fault","دسترسی به صفحه‌ای که در رم نیست","توقف تا آوردن صفحه از دیسک"],["Swapping","جابه‌جایی صفحه بین رم و دیسک","اگر زیاد شود، کندی شدید (thrashing)"]]},{"k":"warn","title":"دام رایج","t":"وقتی سیستم به‌شدت کند می‌شود ولی CPU مشغول نیست، احتمالاً در حال thrashing است — یعنی مدام صفحه‌ها را بین رم و دیسک جابه‌جا می‌کند. راه‌حل، کم‌کردن مصرف حافظه یا افزایش رم است، نه قوی‌کردن CPU."},{"k":"tip","title":"نکته منتور","t":"درک صفحه‌بندی به تو کمک می‌کند بفهمی چرا «لوکالیتی» در کارایی مهم است: کدی که به حافظه نزدیک به هم دسترسی دارد، صفحه‌های کمتری را درگیر می‌کند و کشِ بهتری دارد تا کدی که در حافظه می‌پرد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["حافظه به صفحه‌های هم‌اندازه تقسیم می‌شود","جدول صفحه نگاشت مجازی→فیزیکی را نگه می‌دارد","صفحه‌های کم‌استفاده به دیسک swap می‌شوند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"ترجمه آدرس","code":"آدرس مجازی → [جدول صفحه] → آدرس فیزیکی\nاگر صفحه در RAM نبود → Page Fault\n→ خواندن از دیسک → ادامه"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: حافظه به صفحه‌های هم‌اندازه تقسیم می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Page Fault چیست؟","opts":["خرابی RAM","دسترسی به صفحه‌ای که در RAM نیست و باید از دیسک خوانده شود","خطای برنامه","کمبود CPU"],"ans":1,"why":"وقتی صفحه به دیسک swap شده، دسترسی به آن خطا می‌دهد تا سیستم‌عامل صفحه را برگرداند — کند ولی درست."},{"q":"Page Fault چه زمانی رخ می‌دهد؟","opts":["وقتی رم پر است","وقتی برنامه به صفحه‌ای دسترسی می‌خواهد که فعلاً در رم نیست و باید از دیسک آورده شود","وقتی CPU داغ می‌کند","وقتی برنامه بسته می‌شود"],"ans":1,"why":"MMU می‌بیند آن صفحه در جدول به رم نگاشت نشده؛ پس اجرای آن دستور متوقف می‌شود تا سیستم‌عامل صفحه را از دیسک به رم بیاورد و بعد اجرا ادامه یابد."},{"q":"مهم‌ترین فایده حافظه مجازی برای امنیت چیست؟","opts":["سرعت بیشتر","جداسازی؛ هیچ برنامه‌ای نمی‌تواند به حافظه برنامه دیگر دسترسی پیدا کند چون ترجمه آدرس‌ها جداست","حجم کمتر","سادگی کد"],"ans":1,"why":"هر برنامه جدول ترجمه خودش را دارد و آدرس‌هایش فقط به حافظه خودش نگاشت می‌شود؛ پس راهی برای خواندن یا نوشتن حافظه برنامه دیگر ندارد."}]'::jsonb),
('os-b9', 'os', 'فایل‌سیستم', 56, 14, '[{"k":"p","t":"فایل‌سیستم داده را به‌صورت فایل و دایرکتوری سازمان می‌دهد و inode متادیتای هر فایل را نگه می‌دارد؛ مسیرها در یونیکس سلسله‌مراتبی‌اند."},{"k":"h","t":"فایل‌سیستم؛ سازمان‌دهی داده روی دیسک"},{"k":"p","t":"فایل‌سیستم تعیین می‌کند داده چطور روی دیسک ذخیره و بازیابی شود و آن را به شکل «فایل و دایرکتوری» که ما می‌شناسیم ارائه می‌دهد. در یونیکس، هر فایل یک inode دارد که متادیتایش را نگه می‌دارد: اندازه، مجوزها، مالک و مهم‌تر از همه، آدرس بلوک‌های واقعی داده روی دیسک. نام فایل فقط یک برچسب است که به inode اشاره می‌کند — به همین دلیل یک فایل می‌تواند چند نام (hard link) داشته باشد که همه به یک inode می‌رسند."},{"k":"h","t":"همه‌چیز فایل است"},{"k":"p","t":"یکی از ایده‌های زیبای یونیکس این است که «همه‌چیز فایل است»: دستگاه‌ها، socketها و حتی اطلاعات سیستم هم به شکل فایل دیده می‌شوند و با همان read/write باز می‌شوند. مثلاً /proc اطلاعات زنده kernel و processها را به شکل فایل ارائه می‌دهد. این یکسان‌سازی یعنی برنامه‌نویس فقط یک مدل ذهنی (فایل) دارد و می‌تواند با همه‌چیز به یک شکل کار کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ساختار","نگه می‌دارد"],"rows":[["inode","متادیتا و آدرس بلوک‌های داده (نه نام، نه محتوا)"],["نام فایل (دایرکتوری)","نگاشت نام به inode"],["دیتای فایل","محتوای واقعی در بلوک‌های دیسک"]]},{"k":"warn","title":"دام رایج","t":"وقتی فایلی را حذف می‌کنی ولی یک فرایند هنوز آن را باز نگه داشته، فضایش واقعاً آزاد نمی‌شود تا آن فرایند بسته شود — چون inode تا وقتی مرجع دارد زنده می‌ماند. اگر دیسک پر بود ولی فایلی نمی‌دیدی، دنبال فرایندهایی بگرد که فایل حذف‌شده را باز نگه داشته‌اند."},{"k":"tip","title":"نکته منتور","t":"تفاوت hard link و symbolic link را بدان: hard link یک نامِ دیگر برای همان inode است و با حذف اصلی از بین نمی‌رود؛ symbolic link فقط یک میان‌بر است که به مسیر اشاره می‌کند و اگر مقصد حذف شود، خراب می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["inode شماره، اندازه و بلوک‌های فایل را دارد نه نام","دایرکتوری نگاشت نام به inode است","hard link چند نام به یک inode؛ soft link مسیر به مسیر"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"fs.sh","code":"ls -li file.txt      # شماره inode\nln file.txt hard     # hard link (همان inode)\nln -s file.txt soft  # soft link (مسیر)\n# حذف file.txt: hard می‌ماند، soft می‌شکند"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: inode شماره، اندازه و بلوک‌های فایل را دارد نه نام بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا حذف فایل اصلی، hard link را خراب نمی‌کند؟","opts":["باگ","چون هر دو به یک inode اشاره دارند و داده تا حذف آخرین لینک می‌ماند","کش","ممکن نیست"],"ans":1,"why":"نام‌ها فقط ورودی دایرکتوری‌اند؛ داده به inode وصل است و تا شمارنده لینک صفر نشود حذف نمی‌شود."},{"q":"inode چه چیزی را نگه می‌دارد؟","opts":["فقط نام فایل","متادیتای فایل و آدرس بلوک‌های داده؛ ولی نه خود نام","محتوای فایل","تاریخچه تغییرات"],"ans":1,"why":"نام فایل جداست و فقط به inode اشاره می‌کند؛ خود inode اندازه، مجوزها، مالک و آدرس بلوک‌های واقعی داده را دارد. به همین دلیل یک inode می‌تواند چند نام داشته باشد."},{"q":"معنی «همه‌چیز فایل است» در یونیکس چیست؟","opts":["همه داده‌ها متن‌اند","دستگاه‌ها، socketها و اطلاعات سیستم هم مثل فایل باز و خوانده/نوشته می‌شوند و یک مدل ذهنی واحد می‌سازند","همه‌چیز باید ذخیره شود","فایل‌ها مهم‌ترند"],"ans":1,"why":"این یکسان‌سازی یعنی برای کار با سخت‌افزار، شبکه و سیستم هم همان read/write فایل کافی است؛ پس برنامه‌نویس یک مدل ساده برای همه‌چیز دارد."}]'::jsonb),
('os-b10', 'os', 'ورودی/خروجی و Buffering', 56, 15, '[{"k":"p","t":"عملیات I/O بسیار کندتر از CPU است؛ سیستم‌عامل با buffer و وقفه، CPU را از منتظرماندن نجات می‌دهد و I/O ناهمزمان را ممکن می‌کند."},{"k":"h","t":"I/O کند است؛ buffer پلِ سرعت‌هاست"},{"k":"p","t":"دستگاه‌های ورودی/خروجی (دیسک، شبکه) میلیون‌ها برابر کندتر از CPU هستند. اگر CPU بخواهد برای هر byte صبر کند، عملاً بیکار می‌ماند. راه‌حل، buffer است: یک ناحیه حافظه که داده در آن جمع می‌شود تا یکجا و بهینه منتقل شود — به‌جای هزار انتقال کوچک، چند انتقال بزرگ. سیستم‌عامل با وقفه (interrupt) هم کار می‌کند: به‌جای اینکه CPU مدام بپرسد «داده رسید؟»، دستگاه وقتی کارش تمام شد خودش خبر می‌دهد و CPU تا آن موقع کار مفید دیگری انجام می‌دهد."},{"k":"h","t":"I/O ناهمزمان؛ منتظر نمان"},{"k":"p","t":"در I/O همگام، thread تا تمام‌شدنِ خواندن/نوشتن معطل می‌ماند. ولی با I/O ناهمزمان، درخواست را می‌دهی و به کار دیگر می‌رسی؛ وقتی داده آماده شد (با callback یا رویداد) خبرت می‌کنند. این اساس مدل‌هایی مثل event loop در Node است که با یک thread، هزاران اتصال شبکه را مدیریت می‌کنند — چون هیچ‌وقت برای I/O منتظر نمی‌مانند، بلکه هنگام آماده‌شدنِ داده واکنش نشان می‌دهند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["روش","رفتار thread","کی مناسب است"],"rows":[["همگام (blocking)","تا پایان I/O معطل می‌ماند","کد ساده با I/O کم"],["ناهمزمان (non-blocking)","منتظر نمی‌ماند؛ هنگام آماده‌شدن داده واکنش می‌دهد","اتصالات شبکه زیاد، سرورها"]]},{"k":"warn","title":"دام رایج","t":"نوشتن مستقیمِ byte به byte به دستگاه یا شبکه بسیار کند است؛ همیشه از buffer (یا buffered stream) استفاده کن تا داده یکجا منتقل شود. تفاوت می‌تواند چندین مرتبه بزرگی سرعت باشد."},{"k":"tip","title":"نکته منتور","t":"وقتی می‌بینی برنامه‌ات CPU کمی مصرف می‌کند ولی کند است، احتمالاً منتظر I/O است. در این حالت قوی‌کردن CPU کمکی نمی‌کند؛ باید I/O را ناهمزمان کنی یا تعداد عملیات I/O را با buffer کم کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["buffer داده را جمع می‌کند تا یک‌جا بنویسد","وقفه به CPU خبر می‌دهد I/O تمام شد","I/O ناهمزمان یعنی CPU حین انتظار، کار دیگر کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"چرخه I/O","code":"برنامه: write() → داده به buffer\nCPU: ادامه کار دیگر\nدستگاه: نوشتن → وقفه\nهسته: اطلاع به برنامه (تمام شد)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: buffer داده را جمع می‌کند تا یک‌جا بنویسد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا buffering سرعت ظاهری I/O را بالا می‌برد؟","opts":["داده را فشرده می‌کند","چون برنامه منتظر دستگاه نمی‌ماند؛ داده به buffer سپرده و ادامه می‌دهد","CPU را زیاد می‌کند","دیسک را سریع می‌کند"],"ans":1,"why":"نوشتن به RAM (buffer) سریع است؛ دستگاه بعداً در پس‌زمینه می‌نویسد و CPU آزاد می‌شود."},{"q":"چرا buffer سرعت I/O را بالا می‌برد؟","opts":["داده را فشرده می‌کند","با جمع‌کردن داده و انتقال یکجای آن، تعداد عملیاتِ گرانِ I/O را کم می‌کند","CPU را سریع می‌کند","حافظه را آزاد می‌کند"],"ans":1,"why":"هر عملیات I/O هزینه ثابت بالایی دارد؛ با buffer به‌جای هزار انتقال کوچک، چند انتقال بزرگ انجام می‌شود و مجموع هزینه به‌شدت کم می‌شود."},{"q":"مزیت I/O ناهمزمان چیست؟","opts":["داده سریع‌تر منتقل می‌شود","thread برای I/O منتظر نمی‌ماند و هنگام آماده‌شدن داده واکنش می‌دهد؛ پس یک thread می‌تواند چندین کار را پیش ببرد","امن‌تر است","حافظه کمتری می‌گیرد"],"ans":1,"why":"چون thread معطل نمی‌ماند، می‌تواند همزمان چند درخواست I/O را پیش ببرد و هنگام آماده‌شدن هرکدام پاسخ بدهد — پایه event loop و سرورهای پرکانکشن."}]'::jsonb),
('os-b11', 'os', 'مجازی‌سازی', 56, 16, '[{"k":"p","t":"مجازی‌سازی یک سخت‌افزار را چند ماشین مجازی می‌کند؛ Hypervisor منابع را بین مهمان‌ها تقسیم و هرکدام سیستم‌عامل کامل خودشان را دارند."},{"k":"h","t":"مجازی‌سازی؛ یک سخت‌افزار، چند ماشین"},{"k":"p","t":"مجازی‌سازی اجازه می‌دهد روی یک سخت‌افزار فیزیکی، چند «ماشین مجازی» مستقل اجرا شود که هرکدام سیستم‌عامل کامل خودشان را دارند و از هم بی‌خبرند. نرم‌افزاری به نام Hypervisor منابع (CPU، رم، دیسک، شبکه) را بین مهمان‌ها تقسیم و مدیریت می‌کند. فایده بزرگش جداسازی و استفاده بهینه از سخت‌افزار است: به‌جای ده سرور نیمه‌خالی، یک سرور قوی با ده ماشین مجازی که هرکدام پرکارند."},{"k":"h","t":"VM در برابر کانتینر"},{"k":"p","t":"ماشین مجازی یک سیستم‌عامل کامل (با kernel جدا) را شبیه‌سازی می‌کند، پس سنگین است و دقیقه‌ها طول می‌کشد بالا بیاید. کانتینر سبک‌تر است چون kernel را با میزبان شریک می‌شود و فقط فضای کاربری را جداسازی می‌کند؛ پس ثانیه‌ها بالا می‌آید و چندین برابر بیشتر در یک ماشین جا می‌شود. کانتینر برای اجرای چندین نسخه از «همان برنامه» عالی است، ولی VM جداسازی قوی‌تری دارد چون kernel جدا دارد — برای اجرای سیستم‌عامل‌های متفاوت یا جداسازی امنیتی سخت‌گیرانه، هنوز VM انتخاب است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","ماشین مجازی","کانتینر"],"rows":[["kernel","جدا برای هر مهمان","مشترک با میزبان"],["زمان بالاآمدن","دقیقه‌ها","ثانیه‌ها"],["جداسازی","قوی (kernel جدا)","سبک‌تر (فضای کاربری)"],["مناسب برای","سیستم‌عامل‌های متفاوت، جداسازی سخت‌گیرانه","چند نسخه از یک برنامه، میکروسرویس"]]},{"k":"warn","title":"دام رایج","t":"کانتینرها جداسازیِ kernel ندارند، پس یک آسیب‌پذیری در kernel میزبان می‌تواند همه کانتینرها را تحت تاثیر قرار دهد؛ برای بارهای با امنیت خیلی حساس، VM (یا ترکیب کانتینر داخل VM) جداسازی قوی‌تری می‌دهد."},{"k":"tip","title":"نکته منتور","t":"اینکه بدانی «کانتینر ماشین مجازی نیست» یکی از مهم‌ترین مفاهیم DevOps مدرن است؛ کانتینر فقط یک فرایند جداسازی‌شده روی همان kernel میزبان است، نه یک سیستم‌عامل جدید."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Type-1 مستقیم روی سخت‌افزار، Type-2 روی سیستم‌عامل","هر VM سیستم‌عامل کامل دارد — سنگین ولی ایزوله","کانتینر سبک‌تر است چون هسته مشترک است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"لایه‌ها","code":"VM:  سخت‌افزار → Hypervisor → [OS+App] [OS+App]\nکانتینر: سخت‌افزار → OS → [App] [App] (هسته مشترک)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Type-1 مستقیم روی سخت‌افزار، Type-2 روی سیستم‌عامل بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا کانتینر از VM سبک‌تر است؟","opts":["جدیدتر","چون سیستم‌عامل مهمان ندارد و همه هسته میزبان را مشترک‌اند","فشرده‌تر","کوچک‌تر همیشه"],"ans":1,"why":"هر VM یک هسته و سیستم‌عامل کامل بالا می‌آورد؛ کانتینر فقط process ایزوله روی هسته مشترک است."},{"q":"چرا کانتینر از ماشین مجازی سبک‌تر و سریع‌تر است؟","opts":["چون کدش کمتر است","چون kernel را با میزبان شریک می‌شود و سیستم‌عامل کامل جدا ندارد","چون فشرده است","چون شبکه ندارد"],"ans":1,"why":"VM برای هر مهمان یک kernel کامل بالا می‌آورد که سنگین و کند است؛ کانتینر فقط فضای کاربری را جدا می‌کند و از kernel میزبان استفاده می‌کند، پس ثانیه‌ای بالا می‌آید."},{"q":"Hypervisor چه کاری انجام می‌دهد؟","opts":["کد را کامپایل می‌کند","منابع سخت‌افزار را بین ماشین‌های مجازی تقسیم و اجرای آن‌ها را مدیریت می‌کند","داده را رمز می‌کند","شبکه را قطع می‌کند"],"ans":1,"why":"Hypervisor لایه‌ای بین سخت‌افزار و ماشین‌های مجازی است که CPU و رم و دیسک را بین مهمان‌ها تقسیم می‌کند و هرکدام را مستقل اجرا می‌کند."}]'::jsonb),
('os-b12', 'os', 'Boot و لود شدن سیستم', 56, 17, '[{"k":"p","t":"وقتی کامپیوتر روشن می‌شود، firmware bootloader را اجرا و آن هسته را بارگذاری می‌کند؛ هسته init را می‌سازد و بقیه سرویس‌ها از آن بالا می‌آیند."},{"k":"h","t":"از دکمه پاور تا دسکتاپ؛ زنجیره boot"},{"k":"p","t":"وقتی کامپیوتر روشن می‌شود، ابتدا firmware (BIOS یا UEFI) اجرا می‌شود که سخت‌افزار را اولیه‌سازی و bootloader را پیدا و اجرا می‌کند. bootloader (مثل GRUB) وظیفه‌اش بارگذاری هسته سیستم‌عامل به حافظه و سپردن کنترل به آن است. هسته که بالا آمد، سخت‌افزار را می‌شناسد، driverها را لود می‌کند و اولین فرایند کاربری (init یا systemd با PID 1) را می‌سازد. از آن به بعد، همه سرویس‌ها و برنامه‌ها فرزندانِ همین init هستند."},{"k":"h","t":"چرا init با PID 1 مهم است"},{"k":"p","t":"init اولین فرایند است و والدِ همه فرایندهای دیگر؛ اگر فرایندی یتیم شود (والدش بمیرد)، init سرپرستی‌اش را می‌گیرد تا یتیمِ رهاشده‌ای نماند. systemd (init مدرن لینوکس) فراتر از این، سرویس‌ها را با وابستگی‌هایشان به ترتیب بالا می‌آورد: اول شبکه، بعد سرویس‌هایی که به شبکه نیاز دارند. همچنین سرویس‌های مرده را restart و لاگ‌ها را مدیریت می‌کند؛ برای همین درک systemd برای مدیریت سرور لینوکس ضروری است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["مرحله","مسئول","کار"],"rows":[["۱. firmware","BIOS / UEFI","اولیه‌سازی سخت‌افزار و اجرای bootloader"],["۲. bootloader","GRUB","بارگذاری kernel و سپردن کنترل"],["۳. kernel","هسته سیستم‌عامل","شناخت سخت‌افزار، driverها، ساخت init"],["۴. init","systemd (PID 1)","بالاآوردن سرویس‌ها و سرپرستی فرایندها"]]},{"k":"warn","title":"دام رایج","t":"اگر سرویسی بالا نمی‌آید، اول log آن را با systemd ببین (journalctl)؛ خیلی‌وقت‌ها مشکل این است که سرویس قبل از وابستگی‌اش (مثل شبکه یا دیتابیس) شروع شده و باید ترتیبش اصلاح شود."},{"k":"tip","title":"نکته منتور","t":"درک این زنجیره (firmware → bootloader → kernel → init → سرویس‌ها) به تو کمک می‌کند وقتی سیستم بالا نمی‌آید یا سرویسی کار نمی‌کند، بدانی مشکل در کدام حلقه است و کجا دنبال بگردی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["BIOS/UEFI اولین کد و bootloader را پیدا می‌کند","bootloader (مثل GRUB) هسته را به RAM می‌آورد","init/systemd والد همه processهاست"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"ترتیب boot","code":"روشن → UEFI → bootloader → هسته → init\n→ سرویس‌ها (network, ssh, ...) → login"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: BIOS/UEFI اولین کد و bootloader را پیدا می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"نقش init/systemd چیست؟","opts":["نمایش گرافیکی","اولین process که بقیه سرویس‌ها را به ترتیب و با وابستگی بالا می‌آورد","کامپایل","آنتی‌ویروس"],"ans":1,"why":"init با PID 1 والد همه است و سرویس‌ها را بر اساس وابستگی‌شان (اول شبکه بعد ssh) راه‌اندازی می‌کند."},{"q":"ترتیب درست زنجیره boot کدام است؟","opts":["kernel → firmware → bootloader","firmware → bootloader → kernel → init","init → kernel → bootloader","bootloader → init → firmware"],"ans":1,"why":"اول firmware سخت‌افزار را اولیه‌سازی و bootloader را اجرا می‌کند؛ bootloader هسته را بارگذاری می‌کند؛ هسته init را می‌سازد و init بقیه سرویس‌ها را بالا می‌آورد."},{"q":"چرا init را «والد همه فرایندها» می‌گویند؟","opts":["چون اولین برنامه است","چون اولین فرایند کاربری است و فرزندانِ فرایندهای مرده را سرپرستی می‌کند و بقیه سرویس‌ها از آن بالا می‌آیند","چون سریع‌ترین است","چون بیشترین حافظه را دارد"],"ans":1,"why":"init با PID 1 اولین فرایند کاربری است؛ همه سرویس‌ها مستقیم یا غیرمستقیم از آن شروع می‌شوند و فرایندهای یتیم‌شده را هم او سرپرستی می‌کند."}]'::jsonb),
('dp-r1', 'dp', 'Factory و Strategy: مرگِ if/elseهای بلند', 55, 1, '[{"k":"p","t":"دو تا از پرکاربردترین الگوهای طراحی، در واقع درمان یک درد مشترک‌اند: زنجیره if/else که با هر مورد جدید بلندتر و ترسناک‌تر می‌شود. Factory ساختن را از «کجا» جدا می‌کند و Strategy رفتار را از «کی». وقتی این دو را بفهمی، نیمی از کدهای پیچیده‌ای که می‌بینی، راه‌حلِ ساده‌تری دارند."},{"k":"h","t":"Factory: ساخت را بسپار"},{"k":"p","t":"مسئله: هرجا new PaymentGateway() بنویسی، کدت به یک پیاده‌سازی خاص گره می‌خورد؛ فردا که درگاه دوم اضافه شود، ده فایل را باید بگردی. Factory یعنی یک «کارگاه ساخت» که بر اساس ورودی، نمونه درست را تحویل می‌دهد: createGateway(''sadad'') یا createGateway(''mellat''). حالا افزودن درگاه جدید یعنی افزودن یک کلاس و یک خط به کارگاه — بقیه کد اصلاً خبردار نمی‌شود. Factory Method و Abstract Factory نسخه‌های رسمی‌تر همین ایده‌اند؛ ولی حتی یک تابع ساده makeX() هم ۸۰٪ فایده را می‌گیرد."},{"k":"h","t":"Strategy: رفتار را تعویض‌پذیر کن"},{"k":"p","t":"تخفیف عادی، تخفیف یلدا، تخفیف سازمانی — هرکدام یک فرمول. راه ناشی: if type == ''yalda'' ... در وسط تابع محاسبه. راه Strategy: یک Interface به نام DiscountStrategy با متد apply و سه پیاده‌سازی مستقل؛ تابع محاسبه فقط strategy.apply(price) را صدا می‌زند و نمی‌داند کدام است. حالا تخفیف جدید یعنی یک کلاس جدید؛ تابع اصلی هرگز تغییر نمی‌کند و هر Strategy جداگانه تست می‌شود. تفاوتش با حالت قبلی فقط زیبایی نیست — نقطه تغییر از «وسط منطق حیاتی» به «حاشیه امن» منتقل شده."},{"k":"h","t":"کجا NOT؟ ساده‌سازی قبل از الگو"},{"k":"p","t":"الگو هزینه دارد: Interface و کلاس‌های بیشتر یعنی فایل‌های بیشتر. اگر فقط دو حالت داری و تا سال‌ها سومی نمی‌آید، یک if ساده خواناتر از Strategy است. قاعده عملی: وقتی مورد سوم اضافه شد، ریفکتور کن — «سه بار تکرار، قانون است». الگوهای طراحی برای مدیریت تغییرِ محتمل‌اند، نه برای نمایش دانش؛ بهترین کد، ساده‌ترین کدی است که تغییراتِ واقعیِ آینده را ارزان می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"strategy.py","code":"from abc import ABC, abstractmethod\n\nclass DiscountStrategy(ABC):\n    @abstractmethod\n    def apply(self, price: float) -> float: ...\n\nclass NoDiscount(DiscountStrategy):\n    def apply(self, price): return price\n\nclass YaldaDiscount(DiscountStrategy):\n    def apply(self, price): return price * 0.7\n\nclass OrgDiscount(DiscountStrategy):     # ← افزودن = یک کلاس\n    def apply(self, price): return price * 0.85\n\n# منطق اصلی: هیچ if درباره نوع تخفیف ندارد\ndef checkout(price: float, strategy: DiscountStrategy):\n    return round(strategy.apply(price), 2)\n\nprint(checkout(1000, YaldaDiscount()))   # 700.0"},{"k":"list","items":["checkout هیچ چیزی درباره انواع تخفیف نمی‌داند — فقط «یک استراتژی» را اجرا می‌کند.","افزودن تخفیف سازمانی، حتی یک خط از کد قبلی را تغییر نداد؛ فقط یک کلاس اضافه شد.","هر Strategy در یک فایل تستِ مستقل و میلی‌ثانیه‌ای، جداگانه تست می‌شود.","اگر تخفیف‌ها از Config می‌آمدند، یک Factory انتخابِ Strategy را هم از checkout بیرون می‌برد."]},{"k":"def","term":"اصل باز برای تغییر، بسته برای توسعه","t":"همان OCP از SOLID در لباس الگو: نقطه‌ای که تغییر می‌کند (انتخاب رفتار) از نقطه‌ای که پایدار است (اجرای رفتار) جدا می‌شود. Factory و Strategy هر دو همین جداسازی‌اند — یکی برای «ساخت»، یکی برای «رفتار». وقتی این را ببینی، بقیه الگوها هم همین جمله‌اند با لباس‌های مختلف."},{"k":"table","head":["","بدون الگو","با الگو"],"rows":[["افزودن مورد جدید","دست‌زدن به if/else وسط منطق","افزودن کلاس جدید؛ منطق اصلی دست‌نخورده"],["تست","یک تابع بزرگ با ده حالت","هر رفتار یک تست مستقل"],["خوانایی","ifهای تودرتو","نام کلاس، خودش توضیح است"]]},{"k":"warn","title":"دام رایج","t":"Strategy برای هر if: اگر شرط فقط دو حالت ساده است و تغییرش هم محتمل نیست، الگو نزن — یک if خوانا بهتر از چهار فایل کلاس است. الگو وقتی توجیه دارد که «تعداد موارد رشد می‌کند» یا «رفتارها در زمان اجرا عوض می‌شوند»."},{"k":"tip","title":"نکته حرفه‌ای","t":"در ریویوی بعدی، دنبال if/elseهایی بگرد که «بر اساس نوع» شاخه می‌بندند — هرکدام کاندید Strategy است. و هر new مستقیمی که در چند جا تکرار شده، کاندید Factory. این دو جست‌وجو، سریع‌ترین راهِ دیدنِ الگوها در کد واقعی‌اند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Factory ساخت را و Strategy رفتار را از نقطه استفاده جدا می‌کند.","افزودن مورد جدید باید یعنی «افزودن کلاس»، نه «تغییر منطق اصلی».","الگو برای تغییر محتمل است؛ قانون سه‌بار تکرار، زمان ریفکتور را می‌گوید."]}]'::jsonb, '[{"q":"چه زمانی if/else ساده بهتر از Strategy است؟","opts":["هیچ‌وقت","وقتی فقط دو حالت ساده هست و افزودن مورد جدید محتمل نیست — الگوی بی‌مورد خوانایی را کم می‌کند","وقتی کد کوتاه باشد","وقتی جاوا باشد"],"ans":1,"why":"الگو هزینه ساختار دارد؛ برای دو حالت ثابت، if ساده شفاف‌تر است. استراتژی وقتی می‌درخشد که موارد رشد کنند یا در اجرا عوض شوند."},{"q":"مزیت واقعی Factory چیست؟","opts":["کد کوتاه‌تر","کدِ استفاده‌کننده را از پیاده‌سازیِ خاص جدا می‌کند؛ تغییر یا افزودن پیاده‌سازی یک‌جا انجام می‌شود","سرعت بیشتر","الزام زبان"],"ans":1,"why":"وقتی new در یک کارگاه متمرکز باشد، افزودن درگاه پرداخت جدید یعنی یک کلاس و یک خط رجیستری — نه جست‌وجو در ده فایل."},{"q":"چرا Strategy تست را آسان می‌کند؟","opts":["خودکار تست می‌نویسد","چون هر رفتار یک کلاس مستقل و کوچک است که بدون راه‌اندازی کل سیستم تست می‌شود","مهم نیست","تست لازم ندارد"],"ans":1,"why":"به‌جای یک تابع بزرگ با ده شاخه که هر تستش باید همه‌چیز را بچیند، هر Strategy جداگانه و میلی‌ثانیه‌ای بررسی می‌شود."}]'::jsonb),
('dp-r2', 'dp', 'Observer و Decorator: ارتباطِ بدون گره', 55, 2, '[{"k":"p","t":"بیشتر کدهای درهم‌تنیده از دو نیاز ساده می‌آیند: «وقتی اتفاقی افتاد، خبرم کن» و «این قابلیت را بدون تغییر کلاس اضافه کن». Observer و Decorator پاسخ کلاسیک این دو نیازند — و هر دو، وابستگی را از «مستقیم و محکم» به «قراردادی و شل» تبدیل می‌کنند. سیستم‌های Event-Driven مدرن، ورژن توزیع‌شده Observer‌اند."},{"k":"h","t":"Observer: خبرم کن، نپرس"},{"k":"p","t":"جایگزین Polling است: به‌جای اینکه هر ثانیه بپرسی «سفارش آماده شد؟»، یک‌بار می‌گویی «آماده شد خبر بده». Subject فهرستی از ناظرها نگه می‌دارد و وقتی وضعیتش عوض شد، notify همه را صدا می‌زند. زیبایی‌اش در جهت وابستگی است: Subject فقط می‌داند ناظرها یک متد update دارند — نمی‌داند ایمیل‌اند یا SMS یا داشبورد. همین الگو را می‌شناسی: event listener مرورگر، سیگنال‌های UI، و Kafka در مقیاس سرویس‌ها. فقط مواظب باش: ناظرِ کند، Subject را کند می‌کند — اعلان‌های سنگین باید غیرهمگام شوند."},{"k":"h","t":"Decorator: لایه‌های پیاز"},{"k":"p","t":"می‌خواهی به تابع یا کلاسی قابلیت اضافه کنی — لاگینگ، کش، محدودیت نرخ — بدون اینکه خودش را دست بزنی؟ Decorator دورش را می‌گیرد: همان Interface را پیاده می‌کند، درخواست را می‌گیرد، کار خودش را انجام می‌دهد و به لایه داخل می‌سپارد. مثل پیاز: هر لایه یک مسئولیت. ترکیب‌پذیری‌اش جادوست: CachedRateLimitedLogger(service) — سه قابلیت بدون اینکه service هیچ‌کدام را بداند. در پایتون با سینتکس @decorator و در جاوااسکریپت با Higher-Order Function، این الگو روزمره است."},{"k":"h","t":"تشخیص مهم: Observer در برابر Mediator"},{"k":"p","t":"وقتی چند شیء باید از هم خبر داشته باشند، دو راه داری: Observer برای رابطه یک‌به‌چند (یک رویداد، چند واکنش مستقل) و Mediator برای رابطه چند‌به‌چندِ درهم (همه با همه حرف می‌زنند و منطق میانجی جمع می‌شود). نشانه نیاز به Mediator: وقتی تغییر در یک کامپوننت، چند کامپوننت دیگر را بی‌دلیل درگیر می‌کند و «چه‌کسی از چه خبر دارد» دیگر قابل‌ردیابی نیست. در عمل، Mediator زیاد یعنی مرزها اشتباه کشیده شده‌اند — قبل از ساختنش، یک‌بار مسئولیت‌ها را دوباره تقسیم کن."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"observer-decorator.js","code":"// Observer سبک — EventEmitter خانگی\nclass OrderEvents {\n  constructor() { this.listeners = new Map(); }\n  on(event, fn) {\n    if (!this.listeners.has(event)) this.listeners.set(event, []);\n    this.listeners.get(event).push(fn);\n  }\n  emit(event, data) {\n    (this.listeners.get(event) ?? []).forEach((fn) => fn(data));\n  }\n}\nconst bus = new OrderEvents();\nbus.on(''placed'', (o) => sendEmail(o));   // ناظر ۱\nbus.on(''placed'', (o) => updateStock(o)); // ناظر ۲ — مستقل\nbus.emit(''placed'', { id: 42 });\n\n// Decorator — کش دورِ تابع، بدون دست‌زدن به آن\nconst withCache = (fn) => {\n  const cache = new Map();\n  return (key) => cache.has(key)\n    ? cache.get(key)\n    : cache.set(key, fn(key)).get(key);\n};\nconst cachedUser = withCache(fetchUser);"},{"k":"list","items":["OrderEvents نمی‌داند ناظرها چه می‌کنند — فقط update می‌زند؛ ایمیل و موجودی کاملاً از هم بی‌خبرند.","افزودن ناظر سوم (مثلاً امتیاز وفاداری) یعنی یک خط on جدید — emitter و بقیه ناظرها دست‌نخورده.","withCache رفتار «کش‌کردن» را دور fetchUser می‌پیچد؛ fetchUser اصلاً نمی‌داند کش شده.","Decoratorها ترکیب می‌شوند: withLog(withCache(fn)) — هر لایه یک مسئولیت، مثل پیاز."]},{"k":"def","term":"وابستگی شل (Loose Coupling)","t":"وقتی اجزا فقط از طریق قراردادِ کوچک با هم حرف می‌زنند و از جزئیات هم بی‌خبرند؛ تغییرِ یک جزء، بقیه را نمی‌شکند. Observer و Decorator و Message Queue همه ابزارهای یک هدف‌اند: سفت‌نکردنِ گره‌ها. معیار ساده: اگر بتوانی یک جزء را با نسخه ساختگی جایگزین کنی بدون اینکه بقیه بفهمند، وابستگی شل است."},{"k":"table","head":["الگو","مسئله","مثال روزمره"],"rows":[["Observer","یک رویداد، چند واکنش مستقل","listener کلیک، Kafka، سیگنال UI"],["Decorator","افزودن قابلیت بدون تغییر کلاس","کش، لاگ، Rate Limit دور تابع"],["Mediator","ارتباط درهمِ چند‌به‌چند","کنترلر فرم که همه فیلدها را هماهنگ می‌کند"]]},{"k":"warn","title":"دام رایج","t":"Observerهای همگامِ سنگین: اگر notify() ده ناظر را پشت‌سرهم و همگام صدا بزند، کندترین ناظر سرعت کل را تعیین می‌کند و خطای یک ناظر بقیه را از خبر می‌اندازد. اعلان‌های مهم را جدا کن: اولویت‌دارها همگام و سبک، بقیه با صف پیام غیرهمگام."},{"k":"tip","title":"نکته حرفه‌ای","t":"هر وقت خواستی در کدی بنویسی «بعد از این کار، این سه کار را هم انجام بده»، یک ثانیه مکث کن: این یعنی Observer. و هر وقت خواستی کپیِ یک تابع را با «کمی تغییر» بسازی، یعنی Decorator. این دو مکثِ کوچک، از بزرگ‌ترین منابع کدِ درهم جلوگیری می‌کنند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Observer: خبر بده، نپرس — رابطه یک‌به‌چندِ شل.","Decorator: قابلیت جدید به‌شکل لایه دور کلاس، بدون دست‌زدن به آن.","هر دو وابستگی را از مستقیم به قراردادی تبدیل می‌کنند."]}]'::jsonb, '[{"q":"Observer چه چیزی را جایگزین می‌کند؟","opts":["ارث‌بری","Polling — پرسیدن مدامِ «خبری شد؟» با «خبر شد بگو»","حلقه for","تراکنش"],"ans":1,"why":"پرسیدن مدام هم منابع هدر می‌دهد هم تأخیر می‌سازد؛ اعلانِ رویدادمحور دقیقاً همان لحظه که اتفاق افتاد خبر می‌دهد."},{"q":"مزیت اصلی Decorator چیست؟","opts":["سرعت","افزودن رفتار بدون تغییر کلاس اصلی — و ترکیب چند لایه با هم","حافظه کمتر","سینتکس ساده‌تر"],"ans":1,"why":"کش و لاگ و Rate Limit هرکدام یک لایه جدا می‌شوند؛ کلاس اصلی تمیز می‌ماند و هر لایه جداگانه تست و حذف می‌شود."},{"q":"چه زمانی Observer کافی نیست و باید ناهمگام شد؟","opts":["هیچ‌وقت","وقتی ناظرها کند یا خطاپذیرند — چون در notify همگام، کندترین و خطای هر ناظر به بقیه سرایت می‌کند","وقتی جاوا باشد","وقتی ناظر کم باشد"],"ans":1,"why":"در اعلان همگام، ناظرها پشت‌سرهم اجرا می‌شوند؛ یک ناظر ۵ ثانیه‌ای کل زنجیره را نگه می‌دارد و یک استثنا بقیه را بی‌خبر می‌گذارد — صف پیام این را حل می‌کند."}]'::jsonb),
('n-dp-l1', 'dp', 'الگوهای ساختاری: تولد اشیا', 50, 3, '[{"k":"p","t":"مسئله: ساخت مستقیم شی با new، کد را به جزئیات وابسته می‌کند. اگر نوع کانال اطلاع‌رسانی از روی Config انتخاب شود و فردا کانال جدیدی اضافه شود، بدون الگو باید ده‌جا if/else را دست بزنیم. Factory یعنی «ساخت را بسپار به کسی که می‌داند»."},{"k":"code","lang":"py","title":"factory.py","code":"class Channel:\n    def send(self, msg: str): ...\n\nclass EmailChannel(Channel):\n    def send(self, msg): print(f\"[email] {msg}\")\n\nclass SmsChannel(Channel):\n    def send(self, msg): print(f\"[sms] {msg}\")\n\n# Factory: تنها جایی که if/else زندگی می‌کند\ndef create_channel(kind: str) -> Channel:\n    if kind == \"email\": return EmailChannel()\n    if kind == \"sms\":   return SmsChannel()\n    raise ValueError(f\"unknown channel: {kind}\")\n\n# بقیه‌ی سیستم فقط Channel می‌شناسد — کانال جدید یعنی یک خط به Factory\ndef notify(user, text):\n    ch = create_channel(user.preferred)\n    ch.send(text)"},{"k":"code","lang":"py","title":"singleton.py","code":"class Config:\n    _instance = None\n\n    def __new__(cls):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n            cls._instance.values = {}\n        return cls._instance\n\na, b = Config(), Config()\nprint(a is b)   # True — یک نمونه برای همه\n\n# ولی در تست:\ncfg = Config()          # چه مقادیری دارد؟ از کجا آمده؟\n# Singleton یعنی وابستگی پنهان — Mock کردنش کابوس است"},{"k":"warn","title":"Singleton = حالت سراسری در لباس موجه","t":"Singleton تست‌پذیری را می‌کشد (نمی‌توانی نمونه جایگزین بدهی)، ترتیب ساخت را مخفی می‌کند و در همزمانی قفل می‌خواهد. اغلب «تزریق یک نمونه مشترک» (Dependency Injection) همان کار را بدون معایبش انجام می‌دهد."},{"k":"def","term":"دسته Creational","t":"الگوهایی که «چگونه ساخته شود» را کنترل می‌کنند: Factory Method (ساخت شرطی)، Abstract Factory (خانواده‌های سازگار)، Builder (ساخت مرحله‌ای شی پیچیده)، Singleton (تک‌نمونه) و Prototype (ساخت با کپی)."}]'::jsonb, '[{"q":"Factory Method چه چیزی را از بقیه کد حذف می‌کند؟","opts":["نیاز به کلاس‌ها","وابستگی بقیه سیستم به نوع دقیق شی — if/else ساخت فقط یک‌جا می‌ماند","نیاز به تست","همه حلقه‌ها"],"ans":1,"why":"بقیه سیستم فقط با قرارداد (Channel) کار می‌کنند؛ افزودن TelegramChannel یعنی یک خط در Factory و صفر تغییر در مصرف‌کننده‌ها — Open/Closed."},{"q":"چرا Singleton در تست مشکل‌ساز است؟","opts":["کند است","نمونه سراسری بین تست‌ها نشت می‌کند و نمی‌توان جایگزین کنترل‌شده تزریق کرد","فقط در جاوا کار می‌کند","مشکلی ندارد"],"ans":1,"why":"تست خوب ایزوله است؛ Singleton به‌ذات سراسری است. ترتیب اجرای تست‌ها نتیجه را عوض می‌کند — کلاسیک‌ترین منبع Flaky Test."}]'::jsonb),
('n-dp-l2', 'dp', 'الگوهای رفتاری: تقسیم کار اشیا', 60, 4, '[{"k":"p","t":"الگوهای رفتاری درباره «چگونه اشیا با هم حرف می‌زنند» هستند. Observer جایگزین Polling است: به‌جای اینکه مدام بپرسی «خبری شد؟»، می‌گویی «خبر شد بگو». Strategy جایگزین if/elseهای بلند انتخاب رفتار است: هر رفتار یک شی می‌شود و در زمان اجرا تعویض می‌شود."},{"k":"code","lang":"py","title":"observer_strategy.py","code":"# Observer: ناشر خبر می‌دهد، مشترک‌ها واکنش می‌دهند\nclass EventBus:\n    def __init__(self):\n        self.subs = {}\n\n    def on(self, event, fn):\n        self.subs.setdefault(event, []).append(fn)\n\n    def emit(self, event, data):\n        for fn in self.subs.get(event, []):\n            fn(data)\n\nbus = EventBus()\nbus.on(\"order.created\", lambda o: print(f\"anbar: amade-sazi {o}\"))\nbus.on(\"order.created\", lambda o: print(f\"sms: {o} sabt shod\"))\nbus.emit(\"order.created\", \"#1042\")   # هر دو بدون شناختن هم اجرا می‌شوند\n\n# Strategy: الگوریتم تخفیف، یک شی قابل‌تعویض\nclass PercentOff:\n    def __init__(self, p): self.p = p\n    def apply(self, price): return price * (1 - self.p)\n\nclass FlatOff:\n    def __init__(self, amount): self.amount = amount\n    def apply(self, price): return max(0, price - self.amount)\n\ndef checkout(price, strategy):\n    return strategy.apply(price)\n\nprint(checkout(1000, PercentOff(0.2)))   # 800\nprint(checkout(1000, FlatOff(150)))      # 850"},{"k":"table","head":["مسئله","الگو","ایده کلیدی"],"rows":[["انتشار خبر بدون شناختن گیرنده‌ها","Observer","ناشر فقط می‌گوید «اتفاق افتاد»"],["انتخاب رفتار در زمان اجرا","Strategy","هر الگوریتم یک شی"],["ترتیب ثابت مراحل با جزئیات متغیر","Template Method","اسکلت در پایه، جزئیات در فرزند"],["پیمایش بدون افشای ساختار","Iterator","next() بدون دانستن آرایه/درخت"]]},{"k":"tip","title":"Strategy در برابر State","t":"ساختار هر دو یکسان است؛ تفاوت در نیت: در Strategy مشتری الگوریتم را انتخاب می‌کند (تخفیف درصدی یا ثابت)؛ در State خود شی وقتی وضعیتش عوض می‌شود رفتارش عوض می‌شود (سفارش: پرداخت‌نشده → ارسال‌شده)."}]'::jsonb, '[{"q":"Observer چه جایگزینی برای Polling است؟","opts":["درخواست مکرر برای بررسی تغییر","فراخوانی خودکار مشترک‌ها در لحظه وقوع رویداد","ذخیره در دیتابیس","صف پیام"],"ans":1,"why":"Polling یعنی پرسیدنِ تکراری حتی وقتی خبری نیست (اتلاف)؛ Observer یعنی واکنش دقیقاً وقتی اتفاق می‌افتد — و ناشر نیازی ندارد مشترک‌ها را بشناسد."},{"q":"Strategy چه بویی از کد را از بین می‌برد؟","opts":["حلقه‌های تو در تو","if/else یا switchهای بلند انتخاب رفتار که با هر گزینه جدید بلندتر می‌شوند","متغیرهای سراسری","کامنت‌ها"],"ans":1,"why":"هر گزینه جدید در if/else یعنی دست‌زدن به تابع مشترک (خطر شکستن بقیه)؛ با Strategy یک کلاس جدید اضافه می‌شود و کد قدیمی دست نمی‌خورد."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('n-dp-l3', 'dp', 'الگوهای ساختاری و الگوها در دنیای واقعی', 55, 5, '[{"k":"p","t":"الگوهای ساختاری نحوه ترکیب اشیا را شکل می‌دهند: Decorator بدون وراثت قابلیت اضافه می‌کند (لاگینگ دور یک تابع)، Adapter رابط ناسازگار را ترجمه می‌کند (مثل کتابخانه‌هایی که در فرانت‌اند Axios را به Fetch وصل می‌کنند). و خبر خوب: تو همین حالا هم داری از الگوها استفاده می‌کنی — MVC، Repository و Dependency Injection همه الگوهای اعمال‌شده‌اند."},{"k":"code","lang":"py","title":"decorator_adapter.py","code":"import time, functools\n\n# Decorator: رفتار دور تابع، بدون دست‌زدن به آن\ndef timed(fn):\n    @functools.wraps(fn)\n    def wrapper(*args, **kwargs):\n        start = time.perf_counter()\n        result = fn(*args, **kwargs)\n        print(f\"{fn.__name__}: {time.perf_counter() - start:.3f}s\")\n        return result\n    return wrapper\n\n@timed\ndef heavy_report(rows):\n    return sum(rows)\n\nheavy_report(range(1_000_000))   # heavy_report: 0.021s\n\n# Adapter: پرداخت‌یار قدیمی با امضای متفاوت\nclass LegacyGateway:\n    def do_pay(self, card_number, amount_in_rials): ...\n\nclass GatewayAdapter:\n    def __init__(self, legacy): self.legacy = legacy\n    def pay(self, card, amount_tomans):      # امضای مدرن تیم\n        self.legacy.do_pay(card, amount_tomans * 10)\n\n# کل سیستم با .pay() مدرن کار می‌کند؛ فقط این کلاس Legacy را می‌شناسد"},{"k":"table","head":["اگر می‌شنوی…","احتمالاً الگو"],"rows":[["«این سرویس را Mock کن»","پشت هر Mock یک Adapter یا Proxy نهفته"],["«Middleware بنویس»","Decorator/Chain of Responsibility"],["«Hook اضافه کن»","Observer"],["«Connection Pool»","Object Pool + Proxy"],["«ORM»","Data Mapper / Active Record"]]},{"k":"warn","title":"الگوزدگی (Over-Engineering)","t":"الگو راه‌حل برای درد است، نه تزئین کد. «Factory برای کلاسی که یک‌جا و همیشه یک نوع ساخته می‌شود» یا «Strategy برای دو حالت ثابت» فقط پیچیدگی اضافه می‌کند. اول کد ساده مستقیم؛ وقتی درد واقعی ظاهر شد، الگو."}]'::jsonb, '[{"q":"Decorator چه برتری‌ای نسبت به وراثت دارد؟","opts":["سریع‌تر است","ترکیب رفتارها در زمان اجرا بدون انفجار کلاس‌های فرزند — لاگ‌دار + کش‌دار + … قابل ترکیب‌اند","ساده‌تر است","تست نمی‌خواهد"],"ans":1,"why":"وراثت ترکیب‌نشدنی است: LoggingCachingRetryHttpClient کی تمام می‌شود؟ Decoratorها لایه‌لایه روی هم سوار می‌شوند و هرکدام یک مسئولیت دارند."},{"q":"Adapter چه زمانی لازم می‌شود؟","opts":["وقتی کد کند است","وقتی با رابطی کار داریم که امضایش با چیزی که سیستم انتظار دارد ناسازگار است","وقتی حافظه کم است","هرگز در وب"],"ans":1,"why":"سرویس‌های خارجی، کتابخانه‌های قدیمی، APIهای نسخه‌های مختلف — هر جای «دنیای واقعی با قرارداد ما فرق دارد» جای Adapter است؛ تغییرات را در یک کلاس کوچک حبس می‌کند."}]'::jsonb),
('dp-x1', 'dp', 'ضدالگوها و Refactor به سمت الگوها', 50, 6, '[{"k":"p","t":"الگوهای طراحی را نباید «از قبل» اعمال کرد — باید نشانه‌ها را شناخت و وقتی درد ظاهر شد، به‌سراغشان رفت. این درس درباره سه بوی بد رایج و الگویی است که درمانش می‌کند: زنجیره if/else که با هر نوع جدید بلندتر می‌شود (درمان: Strategy یا رجیستری)، کدی که برای انجام یک کار باید ده متد را پشت‌سرهم و به ترتیب صدا زد (درمان: Facade)، و کلاسی که همه‌چیز را می‌داند و همه از او می‌پرسند (درمان: تفکیک مسئولیت و Mediator). مهارت واقعی، «بوییدن» این حالت‌ها وسط کد معمولی است."},{"k":"code","lang":"java","title":"refactor-strategy.java","code":"// ❌ بوی بد: با هر روش پرداخت جدید، این متد باز می‌شود\npublic double fee(Order o) {\n    if (o.method.equals(\"card\"))    return o.total * 0.02;\n    if (o.method.equals(\"wallet\"))  return 500;\n    if (o.method.equals(\"cod\"))     return o.total * 0.01 + 2000;\n    // ... و ماه بعد یک if دیگر ...\n}\n\n// ✓ Strategy: هر روش، یک پیاده‌سازی؛ متد اصلی دیگر هرگز باز نمی‌شود\ninterface FeePolicy { double fee(Order o); }\n\nrecord CardFee()   implements FeePolicy {\n    public double fee(Order o) { return o.total() * 0.02; }\n}\nrecord WalletFee() implements FeePolicy {\n    public double fee(Order o) { return 500; }\n}\n\nclass Checkout {\n    private final Map<String, FeePolicy> policies = Map.of(\n        \"card\", new CardFee(),\n        \"wallet\", new WalletFee());\n\n    double fee(Order o) {\n        var p = policies.get(o.method());\n        if (p == null) throw new IllegalArgumentException(o.method());\n        return p.fee(o);\n    }\n}"},{"k":"code","lang":"py","title":"refactor-facade.py","code":"# ❌ مشتری باید این مراسم را بلد باشد:\nimg = load(''photo.raw'')\nnorm = normalize(img)\ndenoised = remove_noise(norm, strength=2)\nresized = resize(denoised, (1920, 1080))\nwatermarked = add_watermark(resized, ''bitcode'')\nsave(watermarked, ''out.jpg'')\n\n# ✓ Facade: یک در، پشتش همه مراسم\nclass PhotoPipeline:\n    def export(self, src, dst, size=(1920, 1080)):\n        img = self._load(src)\n        img = self._normalize(img)\n        img = self._denoise(img)\n        img = self._resize(img, size)\n        self._save(self._watermark(img), dst)\n\nPhotoPipeline().export(''photo.raw'', ''out.jpg'')\n# جزئیات پشت در ماند؛ تغییر قدرت نویز‌گیری، هیچ مشتری‌ای را لمس نمی‌کند"},{"k":"list","items":["بوی God Class: فایل بالای ۵۰۰ خط که «همه‌چیزدان» است → تفکیک به Serviceهای کوچک + Mediator اگر هماهنگی لازم است","بوی زنجیره وارثی عمیق: پنج سطح extends → ترکیب و Strategy","بوی کپی‌پیست با ifهای متفاوت: سه کلاس ۹۰٪ مشابه → Template Method (اسکلت مشترک + قدم‌های قابل‌override)","بوی فراخوانی‌های پراکنده ده‌تایی: عملیات واحدی که همه‌جا با همان ترتیب تکرار می‌شود → Facade"]},{"k":"warn","title":"مهندسی بیش از حد","t":"الگو برای دردی است که وجود دارد، نه دردی که شاید بیاید. سه کلاس ساده با چند if خوانا، بهتر از معماری Strategy-Factory-Registry برای مسئله‌ای است که دو حالت دارد و احتمالاً همین دو حالت می‌ماند. قانون سه: وقتی برای سومین بار همان منطق را با تغییر جزئی کپی کردی، آنگاه انتزاع کن — قبلش زود است."},{"k":"tip","title":"نکته منتور","t":"تمرین این هفته: یکی از پروژه‌هایت را باز کن و دنبال بلندترین زنجیره if/else بگرد. بدون تغییر رفتار، فقط همان یک جا را به دیکشنریِ Strategy تبدیل کن و تستش را بنویس. حس «کد دیگر از تغییر نمی‌ترسد» را که بچشی، بقیه الگوها خودشان سراغت می‌آیند."}]'::jsonb, '[{"q":"کی باید از Strategy استفاده کنیم؟","opts":["همیشه برای هر شرطی","وقتی چند رفتار هم‌خانواده داریم و احتمال افزودن/تعویض رفتار در اجرا هست","فقط در جاوا","وقتی کلاس بزرگ است"],"ans":1,"why":"Strategy وقتی ارزشش را دارد که رفتارها قابل‌تعویض و افزایشی باشند — باز/بسته در عمل: افزودن رفتار جدید بدون دست‌زدن به کد موجود."},{"q":"Facade چه چیزی را حل می‌کند؟","opts":["پیچیدگی الگوریتم","زیرسیستم پیچیده‌ای که مشتری‌ها مجبورند مراسمش را بدانند — یک در ساده جلویش می‌گذارد","تعداد کلاس‌ها","سرعت اجرا"],"ans":1,"why":"Facade جزئیات را پشت یک API ساده پنهان می‌کند؛ مشتری فقط در را می‌بیند و تغییرات پشت در، آزادانه انجام می‌شود."}]'::jsonb),
('dp-b1', 'dp', 'چرا الگوهای طراحی', 63, 7, '[{"k":"p","t":"الگوهای طراحی راه‌حل‌های آزموده برای مسائل تکراری طراحی‌اند؛ نام مشترکی می‌دهند که تیم با یک کلمه، یک ساختار کامل را می‌فهمد."},{"k":"h","t":"الگوها؛ واژگان مشترکِ تجربه"},{"k":"p","t":"الگوهای طراحی کد آماده نیستند — «نام‌گذاریِ تجربه‌اند»: راه‌حل‌هایی که ده‌ها بار در پروژه‌های مختلف ظاهر شده‌اند و کتاب Gang of Four در ۱۹۹۴ برایشان اسم گذاشت. ارزش واقعی‌شان سه چیز است: اول، ارتباط — وقتی در Review می‌گویی «اینجا یک Strategy می‌خواهد نه if-else»، یک جمله، یک طراحی کامل را منتقل می‌کند. دوم، پیشگیری — الگوها می‌گویند «این مشکل ساختاری را قبلاً هزاران نفر حل کرده‌اند؛ چرخت را دوباره نساز». سوم، و مهم‌تر، تشخیص بوی بد — هر الگو در پاسخ به یک بوی بد متولد شده: Observer جواب «اشتراک تغییرات بدون وابستگی مستقیم» است، Strategy جواب «خانواده‌ای از الگوریتم‌های قابل‌تعویض». پس درست‌ترین راه یادگیری‌شان، حفظ‌کردن UML نیست — فهمیدن این است که هرکدام کدام درد را درمان می‌کند و چه بویی باید تو را به یادش بیندازد."},{"k":"h","t":"سه خانواده و قانون اعتدال"},{"k":"p","t":"الگوها سه خانواده‌اند: Creational (ساخت اشیاء را انعطاف‌پذیر می‌کنند — Factory، Builder، Singleton)، Structural (چطور اجزا به هم وصل شوند — Adapter، Decorator، Facade) و Behavioral (چطور با هم حرف بزنند — Observer، Strategy، Command). و اما هشدار جدی: الگو بدون نیاز، پیچیدگی خالص است — «Over-Engineering با اسم قشنگ». کلاسی که سه متد ساده دارد را با AbstractFactory نساز! نشانه استفاده درست این است که بوی بد را اول حس کرده باشی: if-else‌های بلند روی «نوع» (بوی Strategy)، وابستگی به جزئیات ساخت (بوی Factory)، تغییر چند جا با هر افزودن رفتار (بوی Observer). قاعده طلایی: «اول ساده بنویس؛ وقتی بو بلند شد، الگوی مناسب را وارد کن» — الگوها برای مدیریت پیچیدگی‌اند، نه ساختنش."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"از بوی بد تا الگو؛ قبل و بعد","code":"# ❌ بوی بد: هر نوع جدید = تغییر این تابع\n# def notify(users, channel):\n#     for u in users:\n#         if channel == ''email'': send_email(u)\n#         elif channel == ''sms'': send_sms(u)\n#         elif channel == ''push'': send_push(u)   # باز یک elif!\n\n# ✓ Strategy: خانواده رفتار، پشت یک قرارداد\nclass EmailChannel:\n    def send(self, user, msg): send_email(user, msg)\nclass SmsChannel:\n    def send(self, user, msg): send_sms(user, msg)\n\ndef notify(users, channel):      # channel هر چیزی با send()\n    for u in users:\n        channel.send(u, ''خبر جدید!'')\n\nnotify(users, SmsChannel())      # افزودن کانال جدید:\nnotify(users, PushChannel())     # فقط یک کلاس تازه"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["خانواده","مسئله","الگوهای معروف"],"rows":[["Creational","ساخت منعطف و مستقل از کلاس مشخص","Factory، Builder، Singleton"],["Structural","ترکیب اجزا و سازگاری رابط‌ها","Adapter، Decorator، Facade"],["Behavioral","تقسیم مسئولیت و ارتباط اشیاء","Observer، Strategy، Command"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سه دسته: ساختاری، رفتاری، تولدی","الگو راه‌حل است نه کتابخانه؛ باید با مسئله‌ات وفق دهی","دانستن زمانِ استفاده مهم‌تر از خود الگوست"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"دسته‌ها","code":"تولد:     چطور شیء بسازیم (Factory, Builder)\nساختاری:  چطور ترکیب کنیم (Adapter, Decorator)\nرفتاری:   چطور رفتار تقسیم کنیم (Strategy, Observer)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سه دسته: ساختاری، رفتاری، تولدی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"الگوی طراحی با کتابخانه چه تفاوتی دارد؟","opts":["هیچ","الگو یک ساختار و ایده برای مسئله تکراری است که خودت پیاده می‌کنی؛ کتابخانه کد آماده است","سرعت","اندازه"],"ans":1,"why":"کتابخانه را صدا می‌زنی؛ الگو را با توجه به مسئله‌ات پیاده می‌کنی — الگو زبان مشترک طراحی است نه کد."},{"q":"ارزش اصلی دانستن نام الگوها چیست؟","opts":["کد سریع‌تر","زبان مشترک — گفتن «Observer» در یک کلمه، یک طراحی کاملِ امتحان‌پس‌داده را منتقل می‌کند و Review و مستندات را فشرده می‌کند","مصاحبه","UML"],"ans":1,"why":"الگوها واژگان‌اند؛ مثل اصطلاحات پزشکی که یک کلمه‌شان یک تشخیص کامل است. بدون این زبان مشترک، هر طراحی باید از صفر توضیح داده شود."},{"q":"کی استفاده از الگو اشتباه است؟","opts":["هیچ‌وقت","وقتی بوی بدی وجود ندارد — اعمال الگو روی مسئله ساده فقط لایه‌های بی‌فایده اضافه می‌کند؛ الگو درمانِ پیچیدگی است نه سازنده‌اش","همیشه","فقط در جاوا"],"ans":1,"why":"هر الگو هزینه دارد: کلاس‌ها و انتزاع‌های بیشتر. اگر مسئله با سه خط کد ساده حل می‌شود، الگو یعنی پیچیدگی خالص — اول ساده، و الگو فقط وقتی بو بلند شد."}]'::jsonb),
('dp-b2', 'dp', 'Singleton', 63, 8, '[{"k":"p","t":"Singleton تضمین می‌کند یک کلاس فقط یک نمونه دارد و دسترسی سراسری می‌دهد؛ برای تنظیمات و اتصال مشترک — ولی استفاده زیادش بوی بد است."},{"k":"h","t":"Singleton؛ ساده‌ترین الگو، پرمناقشه‌ترین"},{"k":"p","t":"ایده Singleton ساده است: از یک کلاس، دقیقاً یک نمونه وجود داشته باشد و دسترسی سراسری به آن — مثل اتصال استخر دیتابیس، تنظیمات برنامه یا Logger. پیاده‌سازی کلاسیک: سازنده خصوصی + یک نقطه دسترسی که نمونه را یک‌بار می‌سازد و بعد همان را برمی‌گرداند. ولی چرا این‌قدر بحث دارد؟ سه اتهام جدی: اول، «وضعیت سراسری پنهان» — هر کدی می‌تواند به آن دست بزند و دنباله اثرش را گرفتن سخت می‌شود (چیزی که تست را کابوس می‌کند چون نمی‌شود نمونه‌اش را ایزوله کرد). دوم، نقض مسئولیت واحد — کلاس هم کارش را می‌کند هم مسئول تعداد نمونه‌های خودش است. سوم، همگام‌سازی در محیط چندنخی که اگر بی‌دقت باشد دو نمونه می‌سازد. نتیجه مدرن: به‌جای اینکه کلاس «خودش» تنها باشد، وابستگی را یک‌بار بساز و تزریق کن (Dependency Injection) — همان سود، بدون قفل‌شدگی."},{"k":"h","t":"Lazy در برابر Eager و مسئله threadها"},{"k":"p","t":"اگر Singleton لازم است، دو راه ساخت با مصالحه‌هایشان را بشناس. Eager: نمونه همان لحظه بارگذاری کلاس ساخته می‌شود — ساده و thread-safe ذاتی (کلاس فقط یک‌بار load می‌شود) ولی اگر هیچ‌وقت استفاده نشود هدر رفته و شروع برنامه را کند می‌کند. Lazy (ساخت در اولین استفاده): شروع سریع‌تر ولی در محیط چندنخی خطرناک — دو thread همزمان می‌بینند «هنوز ساخته نشده» و دو نمونه می‌سازند؛ درمانش قفل دوتایی (Double-Checked Locking) یا holder idiom است که ساخت را به بارگذاری یک کلاس داخلی موکول می‌کند. ولی واقعیت مهندسی امروز: در زبان‌های مدرن، containerهای DI (مثل Spring) یا ماژول‌های پایتون (که ذاتاً یک‌بار load می‌شوند) و closureها، نیاز به Singleton کلاسیک را تقریباً حذف کرده‌اند. Singleton را به‌عنوان یک «الگوی تاریخی با درس‌های واقعی درباره وضعیت سراسری» بشناس — و قبل از نوشتنش، دو بار بپرس «واقعاً باید تنها باشد یا فقط می‌خواهم راحت دسترسی‌اش داشته باشم؟»"},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"java","title":"سه نسخه؛ از خطرناک تا مدرن","code":"// ۱) Eager — ساده، امن، شاید هدر\nclass Config1 {\n    private static final Config1 INSTANCE = new Config1();\n    private Config1() {}\n    static Config1 get() { return INSTANCE; }\n}\n\n// ۲) Lazy thread-safe — holder idiom (بهترین کلاسیک)\nclass Config2 {\n    private Config2() {}\n    private static class Holder {\n        static final Config2 INSTANCE = new Config2();\n    }\n    static Config2 get() { return Holder.INSTANCE; }\n    // ساخت هنگام اولین get — و thread-safe چون\n    // بارگذاری کلاس داخلی توسط JVM قفل می‌شود\n}\n\n// ۳) مدرن: اصلاً Singleton نساز — تزریق کن\nrecord Config(String url) {}\nvar config = loadConfig();            // یک‌بار، اینجا\nnew OrderService(config);             // وابستگی صریح است"},{"k":"warn","title":"دام رایج","t":"Singleton کلاسیک، تست‌نویسی را خراب می‌کند: تست‌ها نمی‌توانند نمونه را جایگزین کنند (سازنده خصوصی است!) و حالت تست قبلی به بعدی نشت می‌کند. اگر کدی به Singleton وصل است و نمی‌شود بدون دیتابیس تستش کرد — همان لحظه بوی بد را حس کن و به سمت تزریق وابستگی برو."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سازنده خصوصی و نمونه استاتیک","در چند thread باید ساخت همگام شود","تست را سخت می‌کند؛ وابستگی را پنهان می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"singleton.py","code":"class Config:\n    _instance = None\n    def __new__(cls):\n        if cls._instance is None:\n            cls._instance = super().__new__(cls)\n        return cls._instance\n\nConfig() is Config()   # True"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سازنده خصوصی و نمونه استاتیک بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Singleton زیاد، ضدالگو تلقی می‌شود؟","opts":["کند","چون وابستگی را پنهان و state سراسری می‌سازد که تست و موازی‌سازی را سخت می‌کند","ممکن نیست","حافظه"],"ans":1,"why":"وقتی هر کجا بتوان به یک نمونه سراسری رسید، وابستگی‌ها نامرئی و تغییرات state غیرقابل‌ردیابی می‌شود."},{"q":"انتقاد اصلی به Singleton چیست؟","opts":["کند است","وضعیت سراسری پنهان می‌سازد — هر کدی می‌تواند بخواند و بنویسد، اثرها قابل‌ردیابی نیستند و ایزوله‌کردن برای تست سخت می‌شود","قدیمی است","حافظه می‌گیرد"],"ans":1,"why":"مشکل «تعداد یک» نیست — «دسترسی همه‌کس» است. وقتی هر ماژول بتواند به یک حالت مشترک دست بزند، فهم و تست رفتار سیستم نمایی سخت می‌شود. تزریق وابستگی، دسترسی را صریح و محدود می‌کند."},{"q":"holder idiom چطور بدون قفل، thread-safe است؟","opts":["قفل دارد","ساخت نمونه را به بارگذاری کلاس داخلی موکول می‌کند — و JVM تضمین می‌کند هر کلاس دقیقاً یک‌بار و به‌طور اتمیک load شود","شانسی","volatile است"],"ans":1,"why":"بارگذاری کلاس در JVM ذاتاً قفل‌شده است؛ Holder فقط وقتی بارگذاری می‌شود که اولین‌بار get() صدا شود — پس هم lazy است و هم بدون نوشتن یک خط قفل، امن."}]'::jsonb),
('dp-b3', 'dp', 'Factory Method', 63, 9, '[{"k":"p","t":"Factory ساخت شیء را پشت یک تابع پنهان می‌کند تا کلاینت نداند دقیقاً چه کلاسی ساخته می‌شود؛ برای انتخاب نوع بر اساس ورودی عالی است."},{"k":"h","t":"Factory؛ وقتی «new» تصمیم‌گیری است"},{"k":"p","t":"بوی بدِ Factory آشناست: کدی که بسته به شرایط باید یکی از چند کلاس را بسازد — و این تصمیم با if-else و newهای پراکنده در چند جا تکرار می‌شود. حالا اگر نوع چهارمی اضافه شود، باید همه آن جاهای پراکنده را پیدا کنی. Factory Method این تصمیم را «پشت یک قرارداد» می‌برد: فراخواننده فقط می‌گوید «یک Logger بده» و اینکه این یعنی FileLogger است یا CloudLogger، در یک‌جا — داخل Factory — تصمیم گرفته می‌شود. نتیجه: افزودن نوع جدید یعنی یک کلاس جدید + یک خط در Factory؛ هیچ فراخواننده‌ای لمس نمی‌شود. و مهم‌تر از افزودن نوع: فراخواننده‌ها دیگر به کلاس‌های «مشخص» وابسته نیستند، به «انتزاع» (رابط Logger) — و این همان وارونگی وابستگی است که تست را ممکن می‌کند: در تست، Factory را با یک MockLogger جابه‌جا کن."},{"k":"h","t":"Factory کجا نه؛ مرز باریک Over-Engineering"},{"k":"p","t":"Factory برای «انتخاب بین چند پیاده‌سازی» است — نه برای هر new. اگر فقط یک کلاس هست و هیچ انتخابی در کار نیست، نوشتن LoggerFactory برای Logger یعنی یک لایه و یک فایل اضافه برای صفر سود؛ این همان مصرف‌گرایی الگوهاست که الگوها را بدنام کرده. سه نشانه که Factory واقعاً لازم است: تصمیم ساخت به «پیکربندی/محیط» وابسته است (تست → InMemoryRepo، تولید → PostgresRepo)، نوع «حین اجرا» معلوم می‌شود (پلاگین‌ها، فرمت فایل ورودی)، یا ساخت «پیچیده» است و باید کپسوله شود. و یک گونه مهم را بشناس: Simple Factory (یک کلاس با متد static) برای انتخاب ساده کافی است؛ Abstract Factory که «خانواده‌ای از Factoryها» می‌سازد فقط وقتی لازم است که چند خانواده محصول سازگار باید با هم انتخاب شوند — مثل تم UI که دکمه و منو و دیالوگِ هم‌خانواده می‌خواهد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"ts","title":"Factory؛ یک تصمیم، یک‌جا","code":"interface PaymentGateway {\n  charge(amount: number): Promise<Receipt>;\n}\n\n// خانواده پیاده‌سازی‌ها\nclass ZarinpalGateway implements PaymentGateway { /* ... */ }\nclass StripeGateway   implements PaymentGateway { /* ... */ }\n\n// تصمیم — فقط این یک تابع\ntype Gateway = ''zarinpal'' | ''stripe'';\nfunction createGateway(kind: Gateway): PaymentGateway {\n  switch (kind) {\n    case ''zarinpal'': return new ZarinpalGateway();\n    case ''stripe'':   return new StripeGateway();\n  }\n  // TypeScript: افزودن نوع بدون case جدید = خطای کامپایل!\n}\n\n// فراخواننده‌ها فقط انتزاع را می‌بینند:\nasync function checkout(gw: PaymentGateway) {\n  return gw.charge(2_500_000);\n}\nawait checkout(createGateway(config.gateway));"},{"k":"def","term":"وارونگی وابستگی در Factory","t":"فراخواننده به «انتزاع» (interface محصول) وابسته است نه به «کلاس‌های مشخص»؛ Factory تنها جایی است که کلاس‌های واقعی را می‌شناسد. نتیجه: تعویض پیاده‌سازی (یا Mock در تست) بدون لمس فراخواننده‌ها — همان چیزی که کد را باز برای گسترش و بسته برای تغییر می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["کلاینت به اینترفیس وابسته است نه کلاس مشخص","افزودن نوع جدید، کد کلاینت را عوض نمی‌کند","منطق انتخاب در یک جا متمرکز می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"factory.py","code":"def make_logger(kind):\n    if kind == ''file'': return FileLogger()\n    if kind == ''db'':   return DbLogger()\n    return ConsoleLogger()\n\nlog = make_logger(config.logger_kind)\nlog.write(''شروع'')   # نمی‌داند و لازم نیست بداند کدام"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: کلاینت به اینترفیس وابسته است نه کلاس مشخص بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت Factory بر new مستقیم چیست؟","opts":["سرعت","کلاینت به نوع مشخص وابسته نمی‌شود و منطق انتخاب در یک جا متمرکز و قابل‌تغییر است","کمتر کد","اجباری"],"ans":1,"why":"اگر کلاینت new DbLogger() بزند، به آن کلاس میخکوب می‌شود؛ Factory اجازه می‌دهد بدون لمس کلاینت، نوع عوض شود."},{"q":"افزودن نوع جدید با Factory چه چیزی را تغییر می‌دهد؟","opts":["همه فراخواننده‌ها","فقط یک کلاس جدید + یک شاخه در Factory — فراخواننده‌ها چون به انتزاع وابسته‌اند دست‌نخورده می‌مانند","هیچ‌چیز","رابط‌ها"],"ans":1,"why":"این دقیقاً اصل «باز برای گسترش، بسته برای تغییر» است: گسترش با افزودن است، نه ویرایش کد موجود — پس خطر شکستن رفتار قدیمی صفر است."},{"q":"کی نوشتن Factory اشتباه است؟","opts":["هیچ‌وقت","وقتی فقط یک پیاده‌سازی هست و انتخابی در کار نیست — لایه اضافه برای صفر سود؛ Factory برای «تقسیمِ انتخاب» است نه هر new","همیشه","فقط در پایتون"],"ans":1,"why":"الگوها درمان‌اند؛ بدون بیماری، دارو یعنی عارضه. اگر تصمیمی بین چند نوع نیست، همان new مستقیم ساده‌ترین و خواناترین راه است."}]'::jsonb),
('dp-b4', 'dp', 'Builder', 63, 10, '[{"k":"p","t":"Builder ساخت اشیا پیچیده با تنظیمات زیاد را مرحله‌به‌مرحله و خوانا می‌کند؛ به‌جای سازنده با ده پارامتر، زنجیره‌ای از تنظیمات."},{"k":"h","t":"Builder؛ ساختارِ ساختنِ چیزهای پیچیده"},{"k":"p","t":"بوی بدِ Builder: سازنده‌ای با هفت پارامتر که سه‌تایش اختیاری — و فراخوانی‌هایی مثل new Order(a, null, null, true, null, 0, null) که خواننده نمی‌داند آن true مال چیست. سازنده‌های تودرتوی overloaded هم مشکل را حل نمی‌کنند چون ترکیب‌های ممکن انفجاری‌اند. Builder می‌گوید: ساختن یک شیء پیچیده را «مراحل نام‌دار و اختیاری» کن — order.customer(sara).items(cart).coupon(''FALL10'').build() — هر مرحله می‌گوید چه می‌کند، ترتیب آزاد است، و مقادیر پیش‌فرض و اعتبارسنجی یک‌جا در build() انجام می‌شود. و یک برد پنهان: Builder می‌تواند شیء «تغییرناپذیر» بسازد — همه فیلدها final و بدون setter — چون فقط Builder به سازنده دسترسی دارد. پس الگو نه برای زیبایی، که برای «قابل‌خواندن‌کردنِ ساختِ پیچیده» و تضمین اعتبار شیء از لحظه تولد است."},{"k":"h","t":"Fluent API و مرزِ لازم بودن"},{"k":"p","t":"زیبایی Builder در زنجیره روانش است (Fluent Interface) — ولی این زیبایی قیمت دارد: کلاس Builder جدا، متدهای تکراری برای هر فیلد، و یک الگوی ذهنی برای هر خواننده جدید. پس قانون: Builder فقط وقتی که «پارامترهای اختیاریِ زیاد» یا «مراحل ساختِ با ترتیب آزاد» واقعاً هست. برای کلاس سه‌فیلدی، همان سازنده ساده یا record بهتر است. در زبان‌های مدرن هم جایگزین‌های بومی را بشناس: در پایتون اغلب @dataclass با مقادیر پیش‌فرض و keyword arguments کافی است (Order(customer=''سارا'', coupon=''FALL10''))؛ در Kotlin و TypeScript، named/optional parameters اکثر موارد را بدون الگو حل می‌کنند. Builder را برای جایی نگه دار که این راه‌ها کم می‌آورند: اعتبارسنجی ترکیبی بین فیلدها، ساخت مرحله‌به‌مرحله با حالت میانی، یا زبان‌هایی مثل جاوا که پارامتر نام‌دار ندارند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"java","title":"قبل و بعد؛ ساخت یک درخواست HTTP","code":"// ❌ تله پارامترها — آن false مال چیست؟!\n// var req = new Request(url, null, null, 3000, false, null, null);\n\n// ✓ Builder — هر بخش اسم خودش را دارد\nclass HttpRequest {\n    private final String url, body, token;\n    private final int timeout;\n\n    private HttpRequest(Builder b) {\n        this.url = b.url;   this.body = b.body;\n        this.token = b.token; this.timeout = b.timeout;\n    }\n    static class Builder {\n        private String url, body, token;\n        private int timeout = 5000;          // پیش‌فرض\n        Builder(String url) { this.url = url; }\n        Builder body(String b)  { this.body = b; return this; }\n        Builder auth(String t)  { this.token = t; return this; }\n        Builder timeout(int ms) { this.timeout = ms; return this; }\n        HttpRequest build() {\n            if (token != null && !url.startsWith(\"https\"))\n                throw new IllegalStateException(\"توکن فقط روی HTTPS\");\n            return new HttpRequest(this);    // اعتبارسنجی یک‌جا\n        }\n    }\n}\n\nvar req = new HttpRequest.Builder(\"https://api.shop.ir\")\n    .auth(token).body(json).timeout(2000).build();"},{"k":"tip","title":"نکته منتور","t":"در پایتون قبل از نوشتن Builder، اول dataclass با فیلدهای پیش‌فرض و keyword arguments را امتحان کن — @dataclass(frozen=True) همان تغییرناپذیری Builder را با یک‌سوم کد می‌دهد. Builder مال جایی است که اعتبارسنجیِ بین‌فیلدی یا ساختِ واقعاً مرحله‌ای داری."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["برای اشیایی با پارامترهای زیاد و اختیاری","هر مرحله یک تنظیم و در آخر build()","کد خوانا و اشتباه ترتیب پارامتر حذف می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"builder.py","code":"query = (QueryBuilder()\n    .select(''name'', ''price'')\n    .where(''price > 100'')\n    .order_by(''price'')\n    .limit(10)\n    .build())"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: برای اشیایی با پارامترهای زیاد و اختیاری بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Builder چه مشکلی را حل می‌کند؟","opts":["کندی","سازنده‌های تودرتو و نامفهوم با پارامترهای زیاد و اختیاری که ترتیب و معنایشان گم می‌شود","حافظه","وراثت"],"ans":1,"why":"سازنده با هشت پارامتر سه‌تایشان اختیاری غیرقابل‌خواندن است؛ Builder هر تنظیم را نام‌دار و مرحله‌ای می‌کند."},{"q":"مشکل اصلی سازنده‌های پرپارامتر چیست که Builder حل می‌کند؟","opts":["کندی","خواننده نمی‌فهمد هر آرگومان موقعیتی مال چیست و ترتیب/اختیاری‌بودن را باید حفظ کند — Builder به هر بخش «نام» می‌دهد و اعتبارسنجی را یک‌جا می‌کند","حافظه","وراثت"],"ans":1,"why":"new Order(a, null, null, true, ...) یعنی خواندن امضا برای فهم هر جایگاه. Builder ساختن را «خودتوضیح» می‌کند و ترکیب‌های نامعتبر را در build() رد می‌کند."},{"q":"در زبان‌های دارای پارامتر نام‌دار (پایتون/Kotlin) چه زمانی باز هم Builder لازم است؟","opts":["هیچ‌وقت","وقتی اعتبارسنجی ترکیبی بین فیلدها، مراحل ساخت با حالت میانی، یا تغییرناپذیریِ سخت‌گیرانه لازم است","همیشه","برای سرعت"],"ans":1,"why":"پارامترهای نام‌دار مشکل خوانایی را حل می‌کنند ولی نه اعتبارسنجی بین‌فیلدی و نه ساخت مرحله‌ای با بررسی در پایان. آنجاست که ساختار Builder — یا فابریک اعتبارسنج — واقعاً سود می‌دهد."}]'::jsonb),
('dp-b5', 'dp', 'Adapter', 56, 11, '[{"k":"p","t":"Adapter رابط ناسازگار یک کلاس را به چیزی که کلاینت انتظار دارد تبدیل می‌کند؛ مثل تبدیل دوشاخه — بدون دست‌زدن به هیچ‌کدام از دو طرف."},{"k":"h","t":"Adapter؛ مترجم بین دو رابط ناسازگار"},{"k":"p","t":"خیلی‌وقت‌ها یک کلاس یا کتابخانه داری که کارش خوب است ولی رابطش با آنچه کد تو انتظار دارد یکی نیست — مثلاً کتابخانه‌ای که دما را فارنهایت می‌دهد ولی کد تو سانتی‌گراد می‌خواهد. Adapter یک کلاس واسط است که رابط ناسازگار را به چیزی که کلاینت انتظار دارد تبدیل می‌کند، بدون اینکه هیچ‌کدام از دو طرف دست بخورند. مثل تبدیل دوشاخه برق: نه پریز عوض می‌شود نه دستگاه، فقط یک قطعه کوچک وسط، این دو را به هم وصل می‌کند."},{"k":"h","t":"کی Adapter لازم می‌شود"},{"k":"p","t":"Adapter معمولاً وقتی لازم می‌شود که بخواهی از یک کلاس موجود (اغلب کتابخانه خارجی یا کد قدیمی) استفاده کنی ولی رابطش با طراحی تو جور نیست؛ یا وقتی می‌خواهی چند پیاده‌سازی مختلف با رابط‌های متفاوت را پشت یک رابط واحد یکسان کنی. فایده بزرگش این است که کد موجود را تغییر نمی‌دهد (که شاید اصلاً نتوانی) و منطق تبدیل را هم در یک جای متمرکز نگه می‌دارد، پس اگر فردا کتابخانه عوض شد، فقط Adapter عوض می‌شود نه کل کد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Adapter","تغییر مستقیم کد"],"rows":[["دست‌زدن به کد موجود","نمی‌خورد","لازم است"],["محل منطق تبدیل","یک کلاس متمرکز","پخش در کل کد"],["عوض‌شدن کتابخانه","فقط Adapter عوض می‌شود","همه‌جا دست می‌خورد"]]},{"k":"warn","title":"دام رایج","t":"Adapter را با Wrapper معمولی اشتباه نگیر؛ هدف Adapter تبدیل یک رابط به رابط دیگر است، نه فقط اضافه‌کردن قابلیت. اگر فقط می‌خواهی رفتار اضافه کنی، Decorator مناسب‌تر است؛ Adapter برای ناسازگاریِ رابط است."},{"k":"tip","title":"نکته منتور","t":"وقتی از یک API خارجی استفاده می‌کنی، حتی اگر فعلاً رابطش مناسب است، یک لایه نازک Adapter دورش بگذار؛ آن‌وقت اگر فردا API عوض شد یا خواستی کتابخانه را جایگزین کنی، فقط همان لایه دست می‌خورد نه همه کدت."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["وقتی کلاس موجود با اینترفیس موردنیاز نمی‌خواند","Adapter دور کلاس قدیمی می‌پیچد و واسط می‌شود","برای اتصال کتابخانه خارجی عالی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"adapter.py","code":"class OldPrinter:\n    def print_text(self, t): ...\n\nclass PrinterAdapter(Printer):\n    def __init__(self, old): self.old = old\n    def print(self, doc):\n        self.old.print_text(doc.text)\n# کلاینت فقط Printer می‌شناسد"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: وقتی کلاس موجود با اینترفیس موردنیاز نمی‌خواند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کی Adapter لازم می‌شود؟","opts":["همیشه","وقتی یک کلاس/کتابخانه موجود، رابطی متفاوت از آنچه کد تو انتظار دارد دارد و نمی‌خواهی هیچ‌کدام را عوض کنی","هیچ‌وقت","برای سرعت"],"ans":1,"why":"Adapter بدون تغییر کلاس قدیمی یا کلاینت، این دو را به هم وصل می‌کند؛ مثل مبدل دوشاخه برق."},{"q":"Adapter چه کاری انجام می‌دهد؟","opts":["رفتار جدید اضافه می‌کند","رابط ناسازگار یک کلاس را به آنچه کلاینت انتظار دارد تبدیل می‌کند، بدون تغییر دو طرف","کد را بهینه می‌کند","کلاس را ساده می‌کند"],"ans":1,"why":"مثل تبدیل دوشاخه، Adapter بدون دست‌زدن به کلاس موجود و کلاینت، بین این دو ترجمه می‌کند؛ پس منطق تبدیل در یک جا متمرکز می‌شود."},{"q":"چه زمانی Adapter انتخاب درستی است؟","opts":["وقتی بخواهی رفتار اضافه کنی","وقتی کلاس موجود رابطش با طراحی تو جور نیست و نمی‌توانی یا نمی‌خواهی تغییرش دهی","وقتی کد کند است","همیشه"],"ans":1,"why":"Adapter برای ناسازگاری رابط است، مخصوصاً با کتابخانه خارجی یا کد قدیمی که تغییرش ممکن نیست؛ برای اضافه‌کردن رفتار، Decorator مناسب‌تر است."}]'::jsonb),
('dp-b6', 'dp', 'Decorator', 56, 12, '[{"k":"p","t":"Decorator رفتار جدیدی را دور یک شیء می‌پیچد بدون تغییر کلاسش؛ مثل لایه‌های پیاز — هر Decorator یک مسئولیت و قابل‌ترکیب با بقیه."},{"k":"h","t":"Decorator؛ رفتار جدید بدون تغییر کلاس"},{"k":"p","t":"فرض کن یک کلاس Notification داری که پیام می‌فرستد و حالا می‌خواهی نسخه‌هایی با رمزنگاری، فشرده‌سازی یا لاگ‌گیری اضافه کنی. راه اول این است که زیرکلاس بسازی — ولی ترکیب این قابلیت‌ها (رمز+فشرده+لاگ) باعث انفجار تعداد زیرکلاس‌ها می‌شود. Decorator راه بهتر است: یک کلاس که دور شیء اصلی «پیچیده» می‌شود و رفتار جدید را اضافه می‌کند درحالی‌که همان رابط را نگه می‌دارد. چون Decorator خودش هم همان اینترفیس را دارد، می‌توان چند تا را لایه‌لایه دور هم پیچید."},{"k":"h","t":"ترکیب‌پذیری؛ قدرت واقعی"},{"k":"p","t":"قدرت Decorator در ترکیب‌پذیری است: می‌توانی یک Notification ساده را با EncryptingDecorator و بعد با LoggingDecorator بپوشانی و شیء نهایی همه این رفتارها را دارد — بدون اینکه هیچ زیرکلاسی ساخته باشی و بدون اینکه کلاس اصلی دست بخورد. هر Decorator فقط یک مسئولیت دارد و ترتیب پیچیدن، ترتیب اجرا را تعیین می‌کند. این الگو در جاوا (InputStreamها) و پایتون (توابع @decorator) به‌شکلهای مختلف استفاده می‌شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","زیرکلاس‌سازی","Decorator"],"rows":[["ترکیب قابلیت‌ها","انفجار تعداد کلاس‌ها","لایه‌لایه و منعطف"],["تغییر در اجرا","ثابت از زمان کامپایل","پویا در زمان اجرا"],["مسئولیت هر کلاس","چند قابلیت با هم","یک قابلیت در هر Decorator"]]},{"k":"warn","title":"دام رایج","t":"زیاده‌روی در Decorator کد را سخت‌خوان می‌کند؛ اگر دیدی پنج لایه Decorator دور یک شیء پیچیده‌ای و فهمیدن ترتیب اجرا سخت شده، شاید بهتر است کمی عقب بکشی و رفتارها را ساده‌تر ترکیب کنی یا از راه‌حل دیگری استفاده کنی."},{"k":"tip","title":"نکته منتور","t":"decorator در پایتون (@name بالای تابع) همین ایده را پیاده می‌کند؛ درک این الگو به تو کمک می‌کند بفهمی چرا و چطور یک تابع می‌تواند رفتار تابع دیگر را بدون تغییرش گسترش بدهد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هم‌اینترفیس با شیء اصلی و آن را در بر می‌گیرد","ترکیب چند Decorator آزادانه","در پایتون با @ به‌صورت سرراست موجود است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"decorator.py","code":"class Coffee:\n    def cost(self): return 10\nclass WithMilk:\n    def __init__(self, c): self.c = c\n    def cost(self): return self.c.cost() + 3\n\nc = WithMilk(Coffee())\nc.cost()   # 13"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هم‌اینترفیس با شیء اصلی و آن را در بر می‌گیرد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت Decorator بر وراثت برای افزودن رفتار چیست؟","opts":["سریع‌تر","رفتارها در زمان اجرا و به هر ترکیب قابل‌افزودن‌اند؛ وراثت ترکیب‌های ثابت و انفجاری از زیرکلاس می‌سازد","کمتر کد","اجباری"],"ans":1,"why":"با وراثت برای هر ترکیب (شیر+شکر، فقط شکر...) یک کلاس لازم است؛ Decorator لایه‌ها را آزادانه ترکیب می‌کند."},{"q":"چرا Decorator نسبت به زیرکلاس‌سازی برای ترکیب قابلیت‌ها بهتر است؟","opts":["سریع‌تر است","چون قابلیت‌ها را لایه‌لایه و پویا ترکیب می‌کند بدون انفجار تعداد زیرکلاس‌ها و بدون تغییر کلاس اصلی","ساده‌تر است","کمتر حافظه می‌گیرد"],"ans":1,"why":"اگر n قابلیت داشته باشی و بخواهی همه ترکیب‌ها را با زیرکلاس بسازی، تعداد کلاس‌ها نمایی می‌شود؛ ولی با Decorator هر قابلیت یک لایه است و آزادانه ترکیب می‌شوند."},{"q":"در Decorator، ترتیب رفتارها چطور تعیین می‌شود؟","opts":["تصادفی","با ترتیب پیچیدن لایه‌ها دور شیء؛ چون هر Decorator همان رابط را دارد و قابل‌ترکیب است","توسط کامپایلر","الفبایی"],"ans":1,"why":"چون هر Decorator هم خودش همان اینترفیس اصلی را دارد، می‌توانی چندتایش را پشت‌سرهم بپوشانی و ترتیبی که می‌پوشانی، ترتیب اجرای رفتارها را مشخص می‌کند."}]'::jsonb),
('dp-b7', 'dp', 'Facade', 56, 13, '[{"k":"p","t":"Facade یک رابط ساده جلوی یک زیرسیستم پیچیده می‌گذارد؛ کلاینت به‌جای ده کلاس، یک متد صدا می‌زند — پیچیدگی پشت صحنه می‌ماند."},{"k":"h","t":"Facade؛ یک در ساده جلوی پیچیدگی"},{"k":"p","t":"بعضی زیرسیستم‌ها ده‌ها کلاس و روش دارند و کار با مستقیمشان برای کلاینت سخت است. Facade یک کلاس است که یک رابط ساده و سطح‌بالا جلوی این پیچیدگی می‌گذارد: کلاینت به‌جای اینکه با ده کلاس سروکار داشته باشد، یک متد می‌خواند و Facade در پشت صحنه همه هماهنگی‌ها را انجام می‌دهد. مثل یک رستوران: تو فقط سفارش می‌دهی و غذا می‌گیری؛ آشپزخانه با همه پیچیدگی‌اش پشت صحنه است و لازم نیست بدانی چطور کار می‌کند."},{"k":"h","t":"کی Facade و تفاوت با Adapter"},{"k":"p","t":"Facade وقتی لازم است که می‌خواهی استفاده از یک زیرسیستم پیچیده را برای کلاینت ساده کنی، بدون اینکه زیرسیستم را تغییر دهی یا قدرتش را حذف کنی — کلاینت‌های پیشرفته هنوز می‌توانند مستقیم به زیرسیستم دسترسی داشته باشند. تفاوتش با Adapter این است که Adapter یک رابط موجود را به رابط دیگر «تبدیل» می‌کند (برای ناسازگاری)، ولی Facade یک رابط «ساده‌تر» جدید روی همان زیرسیستم می‌سازد (برای سهولت)."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Adapter","Facade"],"rows":[["هدف","تبدیل رابط ناسازگار","ساده‌کردن یک رابط پیچیده"],["مسئله","ناسازگاری","پیچیدگی"],["رابط","همان رابط مقصد","یک رابط جدید و ساده‌تر"]]},{"k":"warn","title":"دام رایج","t":"Facade نباید جایگزین زیرسیستم شود یا آن را پنهان کامل کند؛ فقط یک لایه سهولت است. اگر Facade آن‌قدر بزرگ شد که خودش همه منطق را دارد، یعنی دارد به یک «خدای جدید» تبدیل می‌شود — Facade باید نازک بماند و فقط هماهنگی کند."},{"k":"tip","title":"نکته منتور","t":"کتابخانه‌های خوب معمولاً یک Facade دارند؛ مثلاً وقتی یک SDK یک متد ساده send() ارائه می‌دهد که در پشتش احراز هویت، retry و سریال‌سازی را انجام می‌دهد، داری از Facade استفاده می‌کنی — این الگو را در طراحی API خودت هم به کار ببر."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["ساده‌کردن استفاده، نه حذف قابلیت","نقطه ورود واحد به زیرسیستم","زیرسیستم‌ها از کلاینت مستقل می‌مانند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"facade.py","code":"class Checkout:\n    def __init__(self):\n        self.cart, self.pay, self.ship = Cart(), Pay(), Ship()\n    def buy(self, items):\n        order = self.cart.build(items)\n        receipt = self.pay.charge(order)\n        self.ship.send(order)\n# کلاینت: Checkout().buy(items)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: ساده‌کردن استفاده، نه حذف قابلیت بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Facade چه چیزی را ساده می‌کند؟","opts":["پیاده‌سازی","رابط استفاده از یک زیرسیستم پیچیده؛ کلاینت چندین همکاری داخلی را در یک فراخوان می‌بیند","سرعت","حافظه"],"ans":1,"why":"Facade پیچیدگی را حذف نمی‌کند بلکه پنهان می‌کند؛ زیرسیستم همان کار را می‌کند ولی کلاینت با یک متد ساده سروکار دارد."},{"q":"Facade چه کاری انجام می‌دهد؟","opts":["رابط را تبدیل می‌کند","یک رابط ساده و سطح‌بالا جلوی یک زیرسیستم پیچیده می‌گذارد تا کلاینت راحت‌تر کار کند","رفتار اضافه می‌کند","کلاس را تقسیم می‌کند"],"ans":1,"why":"Facade پیچیدگی را پشت یک در ساده پنهان می‌کند؛ کلاینت یک متد می‌خواند و هماهنگی ده کلاس در پشت صحنه انجام می‌شود، بدون اینکه زیرسیستم تغییر کند."},{"q":"تفاوت Facade و Adapter چیست؟","opts":["هیچ","Adapter برای ناسازگاری، رابط را تبدیل می‌کند؛ Facade برای سهولت، یک رابط ساده‌تر جدید می‌سازد","سرعت‌شان","یکی جدیدتر است"],"ans":1,"why":"اگر دو رابط با هم جور نیستند Adapter لازم است؛ اگر یک زیرسیستم پیچیده است و می‌خواهی کار با آن راحت شود، Facade می‌سازی — دو مسئله متفاوت."}]'::jsonb),
('dp-b8', 'dp', 'Strategy', 56, 14, '[{"k":"p","t":"Strategy الگوریتم‌های جایگزین را پشت یک اینترفیس می‌گذارد تا در زمان اجرا عوض شوند؛ به‌جای if/else بزرگ، انتخاب رفتار."},{"k":"h","t":"Strategy؛ الگوریتم قابل‌تعویض"},{"k":"p","t":"فرض کن یک تابع مرتب‌سازی یا محاسبه تخفیف داری که باید چند روش مختلف داشته باشد. راه ساده یک if/else بزرگ است که همه روش‌ها را داخلش می‌گذارد — ولی با هر روش جدید، این if/else بزرگ‌تر و شکننده‌تر می‌شود. Strategy می‌گوید: هر الگوریتم را در یک کلاس جدا، پشت یک اینترفیس مشترک بگذار و در زمان اجرا انتخاب کن کدام اجرا شود. آن‌وقت افزودن روش جدید یعنی یک کلاس جدید، بدون دست‌زدن به کد موجود."},{"k":"h","t":"تزریق Strategy و حذف شرط‌ها"},{"k":"p","t":"در Strategy، کلاس اصلی (context) یک مرجع به اینترفیس Strategy نگه می‌دارد و از بیرون (معمولاً با Dependency Injection) مقداردهی می‌شود؛ پس خودش نمی‌داند و نباید بداند کدام الگوریتم اجرا می‌شود. این اصل «باز برای گسترش، بسته برای تغییر» را محقق می‌کند: الگوریتم‌های جدید اضافه می‌شوند بدون اینکه context دست بخورد. Strategy یکی از پرکاربردترین الگوهاست و هرجا یک if/else دیدی که بر اساس «نوع روش» شاخه می‌زند، کاندیدای Strategy است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","if/else بزرگ","Strategy"],"rows":[["افزودن روش جدید","تغییر if/else موجود","یک کلاس جدید، بدون تغییر"],["تست‌پذیری","سخت (همه در یک تابع)","هر الگوریتم جدا تست می‌شود"],["انتخاب روش","داخل کد، ثابت","در زمان اجرا، تزریقی"]]},{"k":"warn","title":"دام رایج","t":"برای هر if/else ساده‌ای Strategy نساز؛ اگر فقط دو حالت بدیهی داری و قرار نیست زیاد شوند، یک شرط معمولی خواناتر از سه کلاس Strategy است. Strategy وقتی ارزش دارد که روش‌ها متعددند یا مرتب اضافه می‌شوند."},{"k":"tip","title":"نکته منتور","t":"در زبان‌های مدرن، Strategy می‌تواند خیلی سبک باشد: به‌جای یک اینترفیس و چند کلاس، از تابع به‌عنوان Strategy استفاده کن (مثل پاس‌دادن یک comparator به sort) — همان ایده با کد خیلی کمتر."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر الگوریتم یک کلاس با اینترفیس مشترک","کلاینت الگوریتم را تزریق می‌گیرد","افزودن الگوریتم جدید بدون تغییر کلاینت"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"strategy.py","code":"class ByDistance:\n    def fare(self, km): return km * 1000\nclass ByZone:\n    def fare(self, km): return 20000\n\ntrip = Trip(pricing=ByDistance())\ntrip.fare(5)   # 5000"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر الگوریتم یک کلاس با اینترفیس مشترک بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Strategy چه بوی بدی را از بین می‌برد؟","opts":["کد تکراری","if/else یا switch بزرگی که بر اساس نوع، رفتار متفاوت اجرا می‌کند","کلاس بزرگ","کامنت"],"ans":1,"why":"هر شاخه if تبدیل به یک کلاس Strategy می‌شود؛ افزودن رفتار جدید یعنی یک کلاس، نه یک شاخه جدید و دست‌زدن به کد قدیمی."},{"q":"Strategy چه مشکلی را حل می‌کند؟","opts":["کندی","جایگزینی if/else بزرگِ انتخاب روش، با الگوریتم‌های جدا پشت یک اینترفیس که در زمان اجرا انتخاب می‌شوند","امنیت","حافظه"],"ans":1,"why":"به‌جای اینکه همه روش‌ها در یک شرط بزرگ باشند و با هر روش جدید تغییر کنند، هر روش یک کلاس جداست و انتخابش در اجرا انجام می‌شود؛ پس افزودن روش جدید کد قبلی را دست نمی‌زند."},{"q":"چرا در Strategy، انتخاب الگوریتم باید از بیرون تزریق شود؟","opts":["برای سرعت","تا context نداند کدام اجرا می‌شود و افزودن الگوریتم جدید نیاز به تغییرش نداشته باشد (باز برای گسترش، بسته برای تغییر)","اجباری است","برای کاهش حافظه"],"ans":1,"why":"اگر context خودش تصمیم بگیرد، با هر الگوریتم جدید باید عوض شود؛ با تزریق از بیرون، context ثابت می‌ماند و فقط مرجع Strategy عوض می‌شود — همان اصل Open-Closed."}]'::jsonb)
